```go
// internal/consensus/tools.go — exposes the runtime as agent-loop tools.
type ToolBridge struct{ sm *SessionManager }

func (b *ToolBridge) Investigate(ctx context.Context, repo, query string) (*agent.InvestigationResult, error) {
	return b.sm.Adapter().RunInvestigation(ctx, agent.InvestigationRequest{RepoPath: repo, Query: query})
}

