import { DEFAULT_BATCH_SIZE, MAX_RETRIES } from "./config.js";
import { buildState } from "./state.js";
import { validateOptions } from "./validation.js";
import { createQueue } from "./queue.js";
import { computeBackoff } from "./retry.js";
import { cacheGet, cacheSet } from "./cache.js";
import { emitMetrics } from "./metrics.js";

export class GenerationExecutor {
  // …unchanged 30-method body moved here verbatim…
}
```
Import graph is acyclic: `types → config → state/validation/queue/retry/cache/metrics/events → execution`. The class holds all mutable `this` state; helpers are pure or take a context/state object, so no circular imports are introduced. Top-level side effects (e.g., metric registration) live in exactly one designated submodule (`metrics.ts`) imported first by the barrel, preserving initialization order.

