fn test_parse_diff_writes_through_to_duckdb_cache() {
    // Raw in-memory conn, deliberately NOT created via GraphDB::open (mount.rs path).
    let conn = duckdb::Connection::open_in_memory().unwrap();
    let edges = vec![
        Edge { id: "e1".into(), source: "a".into(), target: "b".into(), label: "depends_on".into(), meta: None },
        Edge { id: "e2".into(), source: "b".into(), target: "c".into(), label: "depends_on".into(), meta: None },
    ];

