**Root cause (two independent bugs stacking on a fresh install):**

1. **`isNew` never true** — `EnsureSQLiteSchema` hardcoded `isNew := false`, so `seedSQLiteDefaults` only ran in a branch that was dead code. Fresh DBs had zero rows in `memory_groups`, so every insert referencing a group died with SQLite extended error **787 = SQLITE_CONSTRAINT_FOREIGNKEY**.
2. **Schema mirror drift** — the hand-written `CREATE TABLE` mirror diverged from the goose migrations: `memory_entries` listed `idempotency_key` in INSERTs but not in the mirror DDL; `memory_groups` was missing `normalized_tags_json`; `memory_group_members` had shape drift.

**Fix — remove `isNew` entirely, make seeding unconditional and idempotent, heal drifted tables in place, and enforce mirror↔INSERT parity by test:**

```go
// sqlite.go — boot path, same function the serve handler calls
func EnsureSQLiteSchema(db *sql.DB) error {
	if _, err := db.Exec(mirrorTables); err != nil {          // CREATE TABLE IF NOT EXISTS
		return fmt.Errorf("apply schema mirror: %w", err)
	}
	// CREATE IF NOT EXISTS never alters an existing table: heal pre-drifted
	// databases by adding the columns the old mirror omitted.
	if err := ensureColumn(db, "memory_entries", "idempotency_key", "idempotency_key TEXT"); err != nil {
		return err
	}
	if err := ensureColumn(db, "memory_groups", "normalized_tags_json",
		"normalized_tags_json TEXT NOT NULL DEFAULT '[]'"); err != nil {
		return err
	}
	if _, err := db.Exec(mirrorIndexes); err != nil {          // partial unique index, after columns exist
		return fmt.Errorf("apply schema indexes: %w", err)
	}
	return seedSQLiteDefaults(db)                             // unconditional; INSERT OR IGNORE is a no-op on existing DBs
}

func seedSQLiteDefaults(db *sql.DB) error {
	_, err := db.Exec(
		`INSERT OR IGNORE INTO memory_groups (name, normalized_tags_json)
		 VALUES ('default', '[]'), ('trash', '[]')`)
	return err
}

// ensureColumn is a no-op when the column exists, ALTERs when it does not.
func ensureColumn(db *sql.DB, table, column, ddl string) error {
	rows, err := db.Query(fmt.Sprintf("PRAGMA table_info(%s)", table))
	if err != nil { return fmt.Errorf("pragma table_info(%s): %w", table, err) }
	defer rows.Close()
	for rows.Next() {
		var cid, notnull, pk int
		var name, ctype string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &ctype, &notnull, &dflt, &pk); err != nil { return err }
		if name == column { return nil }
	}
	if err := rows.Err(); err != nil { return err }
	if _, err := db.Exec(fmt.Sprintf("ALTER TABLE %s ADD COLUMN %s", table, ddl)); err != nil {
		return fmt.Errorf("add column %s.%s: %w", table, column, err)
	}
	return nil
}
```

The mirror itself (order matters: tables → column migration → indexes, because a partial index cannot reference a column that doesn't exist on disk yet):

```sql
-- mirrorTables
CREATE TABLE IF NOT EXISTS memory_groups (
    id                    INTEGER PRIMARY KEY AUTOINCREMENT,
    name                  TEXT NOT NULL UNIQUE,
    normalized_tags_json  TEXT NOT NULL DEFAULT '[]',      -- was missing from mirror
    created_at            TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS memory_entries (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id        INTEGER NOT NULL REFERENCES memory_groups(id) ON DELETE CASCADE,
    content         TEXT NOT NULL,
    idempotency_key TEXT,                                   -- was missing from mirror
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS memory_group_members (
    group_id   INTEGER NOT NULL REFERENCES memory_groups(id) ON DELETE CASCADE,
    member_id  INTEGER NOT NULL REFERENCES memory_entries(id) ON DELETE CASCADE,
    role       TEXT NOT NULL DEFAULT 'member',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (group_id, member_id)
);
-- mirrorIndexes (applied after ensureColumn)
CREATE UNIQUE INDEX IF NOT EXISTS idx_memory_entries_idempotency_key
    ON memory_entries (idempotency_key)
    WHERE idempotency_key IS NOT NULL;                      -- NULL keys stay non-unique
```

Every `INSERT` list in `sqlite.go` was audited against the mirror — `memory_entries (group_id, content, idempotency_key)`, `memory_groups (name, normalized_tags_json)`, `memory_group_members (group_id, member_id, role)` — and a **regex-based parity test** (test 6) now fails the build if any INSERT names a column the mirror lacks.

**Root cause:** `cobra.Command.Commands()` returns subcommands **sorted alphabetically by name**, not in the order you called `AddCommand`. So `cmd.Commands()[1]` is the second subcommand *alphabetically* — and `cmd.Commands()[1].Flags().String(...)` registers the flag on whatever command happens to sit at that index. If subcommand names ever change, get reordered, or a new one is added, flags silently migrate to a different command.

**The fix:** keep a variable reference to the subcommand at creation time and register flags on that reference. Never index `cmd.Commands()`.

```go
package main

import "github.com/spf13/cobra"

// BAD — breaks the moment subcommand order/names change:
func badRoot() *cobra.Command {
	root := &cobra.Command{Use: "app"}
	root.AddCommand(&cobra.Command{Use: "zebra", Run: func(c *cobra.Command, a []string) {}})
	root.AddCommand(&cobra.Command{Use: "apple", Run: func(c *cobra.Command, a []string) {}})

	// Compiles, but lands on "zebra" (alphabetically 2nd), NOT "apple" (2nd defined)
	root.Commands()[1].Flags().String("bug-flag", "", "mislocated")
	return root
}

// GOOD — variable reference + explicit AddCommand:
func goodRoot() *cobra.Command {
	root := &cobra.Command{Use: "app"}

	createCmd := &cobra.Command{Use: "create", Run: func(c *cobra.Command, a []string) {}}
	root.AddCommand(createCmd) // register first, then wire flags
	createCmd.Flags().String("name", "", "the file name")

	// safe even though more commands get added later
	root.AddCommand(&cobra.Command{Use: "zebra", Run: func(c *cobra.Command, a []string) {}})
	return root
}
```

Key points:
- Declare the `*cobra.Command` variable, `AddCommand` it, then call `.Flags()` on the variable — order of those three lines is irrelevant to correctness.
- The same trap applies to `cmd.Commands()` for help text, aliases, or any per-subcommand wiring: resolve subcommands by `Find([]string{...})` or by variable reference, never by positional index.

**Root cause chain:** DuckDB enforces a single-process writer via a whole-file lock. The production `:3000` fleet daemon opens the default namespace's DuckDB file at startup and holds that lock (`lsof` shows `25uW` = fd 25, read/write mode, whole-file **W**rite lock) for the process's lifetime. Per-session stdio MCP servers that try to open the *same file* — even `READ_ONLY` — collide with that lock and surface as `DUCKDB_CONNECTION_LOST`. The stdio servers were innocent: **the lock holder was the fleet daemon all along.** A separate bug (BUG-034) lets stale `tsx` test daemons linger and hold locks on test-namespace files.

**Fix rules (in priority order):**

1. **Never kill the fleet daemon.** Diagnose with `lsof` first; only kill a PID that lsof proves holds the lock and that matches a disposable pattern (test daemon). A blanket `pkill -f duckdb` takes down production.
2. **Route default-ns access through the HTTP `:3000` fallback** from per-session stdio servers — they must never open the default-ns file directly.
3. **Use explicit namespaces → one DuckDB file per namespace** so independent sessions open distinct files and never contend.
4. **Kill stale `tsx` test daemons (BUG-034)** surgically, pattern-matched and lsof-re-verified.

### Code: lock-holder diagnosis (run before touching any process)

```ts
// scripts/who-holds-lock.ts  (Node/tsx, run as: tsx who-holds-lock.ts <dbPath>)
import { execSync } from "node:child_process";

const dbPath = process.argv[2] ?? "data/ns/default.db";

// FD column: "<fd><mode><lock>", e.g. "25uW" = fd 25, read/write, whole-file write lock
const lsof = execSync(`lsof "${dbPath}"`, { encoding: "utf8", stdio: ["ignore","pipe","pipe"] });
const holders = lsof.split("\n").slice(1).filter(Boolean).map(line => {
  const [cmd, pid, user, fd, ...rest] = line.split(/\s+/);
  return { cmd, pid, user, fd, lock: fd.includes("W") ? "whole-file-WRITE" : fd.includes("w") ? "partial-write" : "other" };
});

console.table(holders);
const w = holders.filter(h => h.lock === "whole-file-WRITE");
if (w.length) {
  console.error(`LOCK HELD BY: ${w[0].cmd} pid=${w[0].pid} fd=${w[0].fd} — do NOT kill if this is the :3000 fleet daemon`);
  process.exit(1); // caller must route via HTTP instead of killing
}
console.log("No write-lock holder — safe to open.");
```

### Code: namespace routing (the actual fix in DuckBrain)

```ts
// src/store.ts
import path from "node:path";

const DATA_DIR = process.env.DUCKBRAIN_DATA ?? "data";
const FLEET_DAEMON_URL = process.env.DUCKBRAIN_HTTP ?? "http://127.0.0.1:3000";
const isFleetDaemon = () => process.env.DUCKBRAIN_FLEET === "1";

/** One DuckDB file per namespace — explicit namespaces never collide. */
export function nsPath(ns: string): string {
  return path.join(DATA_DIR, "ns", ns === "default" ? "default.db" : `${ns}.db`);
}

export async function openNamespace(ns: string, opts: { readOnly?: boolean } = {}) {
  // Rule 2: the fleet daemon owns default-ns from startup. Stdio servers must
  // NOT open that file (even read-only) — route through the HTTP fallback.
  if (ns === "default" && !isFleetDaemon()) {
    return DuckHttpClient.open(FLEET_DAEMON_URL, ns, opts); // :3000 proxies DuckDB
  }
  // Rule 3: non-default namespaces are separate files → no lock contention.
  return DuckDBConnection.open(nsPath(ns), { readOnly: opts.readOnly ?? false });
}
```

