```ts
// scripts/kill-stale-test-daemons.ts
import { execSync } from "node:child_process";

const dbPath = "data/ns/test-e2e.db";
const lsof = execSync(`lsof "${dbPath}"`, { encoding: "utf8" }).trim();
if (!lsof) { console.log("no lock holder — nothing to do"); process.exit(0); }

for (const line of lsof.split("\n").slice(1)) {
  const [cmd, pid, , fd] = line.split(/\s+/);
  const cmdline = execSync(`ps -p ${pid} -o args=`, { encoding: "utf8" });
  const isTestDaemon = /tsx .*--test|test-runner|vitest/.test(cmdline);
  if (fd.includes("W") && isTestDaemon) {
    process.kill(Number(pid), "SIGTERM");              // kill ONLY the stale test daemon
    console.log(`killed stale test daemon pid=${pid} (fd=${fd})`);
  }
}
// Fleet daemon never matches the pattern → never touched.
