**Root cause (why this is the 4th occurrence):** the daemon did three half-things each time — (1) registered namespaces with existence-only checks (junk/partial dirs polluted the config), (2) mutated `duckbrain.config.json` with no atomic write and **no board commit**, so the tick produced no attributable work artifact, and (3) the audit's verdict credited only task/`board`-kind commits, so a tick that only reconciled config drift was classified `IDLE`. Each prior fix patched one link; the pattern repeated. The fix below closes all three.

**Fix 1 — the daemon reconciler** (`src/drift-reconciler.ts`): verify candidates properly, register only verified namespaces, atomically persist config, and push one board commit per registration so the work is durable and attributable:

```ts
// 1. Verification: safe name + real dir + no symlink + non-empty (+ optional marker)
export async function verifyNamespaceDir(root: string, name: string, opts: VerifyOptions = {}) {
  const reason = validateNamespaceName(name);              // ^[a-z0-9][a-z0-9-]{0,127}$ (blocks traversal/dots)
  if (reason) return { ok: false, reason };
  const st = await fsp.lstat(path.join(root, name));       // throws -> "missing on disk (ENOENT)"
  if (st.isSymbolicLink()) return { ok: false, reason: 'symlink: refusing to follow' };
  if (!st.isDirectory())    return { ok: false, reason: 'not a directory' };
  const entries = await fsp.readdir(path.join(root, name));
  if (entries.length === 0) return { ok: false, reason: 'empty dir (partial write?); retry next tick' };
  if (opts.requireMarker && !entries.some(e => ['namespace.json','manifest.json','tick.md'].includes(e)))
    return { ok: false, reason: 'no namespace marker (namespace.json|manifest.json|tick.md)' };
  return { ok: true };
}

// 2. Reconcile: register verified -> board-commit each -> atomic config write
export async function reconcileDrift({ root, configPath, config, tick, board, verify }: ReconcileOpts): Promise<ReconcileResult> {
  const scan = await scanDrift({ root, config, tick, verify });
  if (!scan.hasDrift) return { scan, config, commits: [] };          // no drift -> no mutation, no commit

  const namespaces = [...config.namespaces];
  const commits: CommitRecord[] = [];
  for (const name of scan.verified) {
    namespaces.push({ name, path: path.join(root, name), discoveredAtTick: tick, source: 'disk-audit', status: 'active' });
    commits.push(await board.commit({                                  // durable, attributable work artifact
      tick, kind: 'config-drift',
      message: `board: register namespace ${name} (disk drift @tick ${tick})`,
      namespaces: [name],
    }));
  }
  const next: DuckBrainConfig = { ...config, tick, namespaces };
  await writeJsonAtomic(configPath, next);                            // tmp file + rename, never a torn config
  return { scan, config: next, commits };
}
```

`scanDrift` surfaces *everything* for observability: `diskDirs`, `nonDirs` (stray files/symlinks, surfaced but never candidates), `missingOnDisk` (reported, never auto-removed), `newDirs`, `verified`, `rejected`.

**Fix 2 — the audit verdict** (the actual IDLE→PRODUCTIVE correction):

```ts
// Audit-side fix: any committed record (board OR config-drift) = productive.
// A tick is IDLE only when nothing was committed.
export function classifyVerdict(commits: CommitRecord[]): Verdict {
  return commits.length > 0 ? 'PRODUCTIVE' : 'IDLE';
}
```

**Fix 3 — the :3000 daemon tick handler** (`src/daemon.ts`), wired end-to-end:

```ts
export async function daemonTick({ root, configPath, tick, board, verify }: DaemonTickOptions) {
  const config = await readConfig(configPath);                        // 1. read config
  const { scan, config: next, commits } = await reconcileDrift({      // 2-4. verify+register+commit+atomic write
    root, configPath, config, tick, board, verify,
  });
  const outcome = auditTick(tick, commits);                           // 5. verdict from the commit ledger
  return { ...outcome, config: next, registered: scan.verified };
}
```

The audit now reads the board ledger for the tick; since the daemon commits each registration, tick 226 is `PRODUCTIVE`. A synced tick (zero commits) is still correctly `IDLE`.

**Root cause.** The partial unique index `WHERE col IS NOT NULL` only exempts SQL `NULL`. When the HTTP handler didn't set `idempotency_key`, the repository still bound Go's zero-value `""` into the INSERT, and `'' IS NOT NULL` is true in SQLite — so the second row collided, surfacing as `500 UNIQUE constraint failed (2067)`.

**Fix part 1 — repository layer (SQLite and PG):** normalize empty strings to `NULL` at the bind point, before the value reaches the driver. This keeps the index DDL untouched and works identically for SQLite and Postgres because both encode a `nil *string` as `NULL`.

```go
// internal/repo/normalize.go
// normalizeOptional returns a *string that is nil when s is empty,
// so the driver binds SQL NULL and the partial unique index is bypassed.
func normalizeOptional(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}
```

```go
// internal/repo/memories.go
func (r *MemoryRepo) Create(ctx context.Context, m Memory) (Memory, error) {
	// normalize BEFORE binding — applies to both SQLite and PG paths
	key := normalizeOptional(m.IdempotencyKey)

	if r.isSQLite { // modernc.org/sqlite / mattn/go-sqlite3
		res, err := r.db.ExecContext(ctx,
			`INSERT INTO memories (title, body, idempotency_key)
			 VALUES (?, ?, ?)`,
			m.Title, m.Body, key,
		)
		// ...assign ID from res.LastInsertId()
	} else { // postgres (database/sql or pgx)
		err := r.db.QueryRowContext(ctx,
			`INSERT INTO memories (title, body, idempotency_key)
			 VALUES ($1, $2, $3) RETURNING id`,
			m.Title, m.Body, key,
		).Scan(&m.ID)
	}
	return m, err
}
```

**Fix part 2 — handler wiring (DTO → model):** the optional field was only copied in the MCP path, so the HTTP handler dropped it (leaving the Go zero value, which is the empty string that triggered the bug):

```go
// internal/http/handler.go
func (h *Handler) CreateMemory(w http.ResponseWriter, r *http.Request) {
	var dto CreateMemoryRequest
	if err := json.NewDecoder(r.Body).Decode(&dto); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	mem := Memory{
		Title:          dto.Title,
		Body:           dto.Body,
		IdempotencyKey: dto.IdempotencyKey, // was missing — zero value "" was bound
	}
	saved, err := h.repo.Create(r.Context(), mem)
	if err != nil {
		// UNIQUE (2067) on a non-empty key → 409 Conflict instead of 500
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusCreated, saved)
}
```

Optionally, surface genuine duplicates as `409 Conflict` instead of `500` by checking for the SQLite extended code `2067` / PG code `23505` — but the constraint-vs-`''` collision itself is resolved by the NULL normalization.

### 1. Makefile: `CGO_ENABLED := 1` clobbers the environment

`:=` makes CGO_ENABLED unconditionally override the env var, so `GOOS=linux GOARCH=arm64 go build` tries to assemble `runtime/cgo` with the host x86 gcc and fails. The built commands are pure Go (sqlite lives only in `pkg/repository`, which no built `cmd/` imports), so CGO can be off.

```make
# before
CGO_ENABLED:=1

# after — only set a default when the caller didn't
CGO_ENABLED ?= 1
```

And pin it off in the workflow so no step re-enables it:

```yaml
# .github/workflows/ci.yml
jobs:
  build:
    runs-on: ubuntu-latest
    env:
      CGO_ENABLED: "0"   # binaries are pure Go; prevents cross-gcc requirement
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-go@v5
        with: { go-version-file: go.mod }
      - run: make build
      - run: GOOS=linux GOARCH=arm64 make build     # cross-arch now works
      - run: GOOS=windows GOARCH=amd64 make build
```

### 2. Windows keychain: restore the real Credential Manager impl, tag the stub

The purge-regression restore deleted `keychain_windows.go`, leaving only a build-tag-less stub that compiled on **all** platforms and returned `ErrSecretServiceNotAvailable` everywhere. Restore from history, constrain the stub, and guard empty blobs.

```bash
# locate the deletion and restore the real impl from the commit before it
git log --diff-filter=D --oneline -- pkg/keyring/keychain_windows.go
git checkout <deleting-commit>^ -- pkg/keyring/keychain_windows.go
```

Stub — now Windows-only builds the real impl, every other OS gets the stub:

```go
//go:build !windows
// +build !windows

package keyring

import "errors"

// ErrSecretServiceNotAvailable is returned on platforms without a secret service.
var ErrSecretServiceNotAvailable = errors.New("keychain: secret service not available")

// Get returns ErrSecretServiceNotAvailable on non-Windows platforms.
func Get(name string) ([]byte, error) { return nil, ErrSecretServiceNotAvailable }
```

Restored Windows impl with the empty-blob nil guard (a zero-length stored blob must return `(nil, nil)` — a *successful* empty read — not be conflated with not-found):

```go
//go:build windows
// +build windows

package keyring

import "unsafe"

// Get reads a generic credential from the Windows Credential Manager.
// An empty credential blob is a valid stored value, distinct from
// "credential not found" (which surfaces as a read error).
func Get(name string) ([]byte, error) {
	cred, err := credRead(name)
	if err != nil {
		return nil, err
	}
	defer credFree(cred)

	// Empty-blob nil guard: size==0 is a successful empty read, not an error.
	if cred.CredentialBlobSize == 0 {
		return nil, nil
	}
	return unsafe.Slice((*byte)(cred.CredentialBlob), cred.CredentialBlobSize), nil
}
```

### 3. `isProcessRunning`: `os.FindProcess` + `Signal(0)` never works on Windows

`Signal(0)` returns `ErrProcessDone`/`os: process already finished` semantics that are unreliable on Windows. Split per platform; Windows uses `OpenProcess` + `WaitForSingleObject` so a racing process exit is disambiguated from "never existed".

```go
// proc/process_unix.go
//go:build !windows

package proc

import (
	"os"
	"syscall"
)

// isProcessRunning reports whether the PID exists (Unix: signal 0 probe).
func isProcessRunning(pid int) bool {
	p, err := os.FindProcess(pid)
	if err != nil {
		return false
	}
	return p.Signal(syscall.Signal(0)) == nil
}
```

```go
// proc/process_windows.go
//go:build windows

package proc

import "syscall"

var (
	kernel32            = syscall.NewLazyDLL("kernel32.dll")
	openProcess         = kernel32.NewProc("OpenProcess")
	closeHandle         = kernel32.NewProc("CloseHandle")
	waitForSingleObject = kernel32.NewProc("WaitForSingleObject")
)

const (
	processQueryLimitedInformation = 0x1000
	processSync                    = 0x00100000 // allow wait on the handle
	waitTimeout                    = 0x00000102 // WAIT_TIMEOUT
)

// isProcessRunning reports whether the PID names a live process.
// OpenProcess with SYNCHRONIZE lets WaitForSingleObject tell "still running"
// (WAIT_TIMEOUT) apart from "exited since we opened it" (WAIT_OBJECT_0).
func isProcessRunning(pid int) bool {
	if pid <= 0 {
		return false
	}
	h, _, _ := openProcess.Call(uintptr(processQueryLimitedInformation|processSync), 0, uintptr(pid))
	if h == 0 {
		return false // ERROR_INVALID_PARAMETER => no such process
	}
	defer closeHandle.Call(h)
	rc, _, _ := waitForSingleObject.Call(h, 0)
	return rc == waitTimeout
}
```

### 4. Coarse Windows clock (~15.6 ms tick): zero lockout + boundary equality

`time.Since()` can be exactly `0` after a real pause, and two consecutive `time.Now()` calls can be equal — so "elapsed > duration" tests and strict `After()` comparisons misbehave. Fix: treat `duration <= 0` as "never locked", and compare the boundary with `>=` semantics.

```go
type Lockout struct {
	duration   time.Duration
	lockedUntil time.Time
}

// locked reports whether a lockout is currently active.
func (l *Lockout) locked(now time.Time) bool {
	// Zero/negative duration short-circuits: no lockout. This also avoids the
	// coarse-clock artifact where time.Since(lastFailure)==0 at small deltas.
	if l.duration <= 0 {
		return false
	}
	if l.lockedUntil.IsZero() {
		return false
	}
	// Coarse clock can make now == lockedUntil exactly at the boundary;
	// !Before means ">= " so the boundary tick still counts as locked.
	return !l.lockedUntil.Before(now)
}
```

### 5. Connection-refused text differs on Windows

Unix reports `dial tcp ...: connection refused`; Windows reports `connectex: No connection could be made because the target machine actively refused it`. Normalize with a dual-path matcher used by both code and tests.

```go
func isConnectionRefused(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "connection refused") || strings.Contains(msg, "actively refused")
}
```

