// cmd/status.go
const defaultStatusPort = 8080

func newStatusCmd() *cobra.Command {
    var port int
    cmd := &cobra.Command{
        Use:   "status",
        Short: "Show memoryd service health",
        RunE: func(cmd *cobra.Command, _ []string) error {
            if !cmd.Flags().Changed("port") {
                if v := os.Getenv("MEMORYD_STATUS_PORT"); v != "" {
                    p, err := strconv.Atoi(v)
                    if err != nil {
                        return fmt.Errorf("invalid MEMORYD_STATUS_PORT %q: %w", v, err)
                    }
                    port = p
                } else {
                    port = defaultStatusPort
                }
            }
            if port < 1 || port > 65535 {
                return fmt.Errorf("status port %d out of range 1-65535", port)
            }
            // probe http://127.0.0.1:%d/healthz
            return nil
        },
    }
    cmd.Flags().IntVar(&port, "port", defaultStatusPort,
        "status port (flag overrides MEMORYD_STATUS_PORT)")
    return cmd
}
```

**4. Five regression tests** covering the resolution chain and its failure modes:

```go
// cmd/status_test.go
func TestStatusDefaultPort(t *testing.T)        // no env, no flag  -> 8080
func TestStatusPortEnvOverride(t *testing.T)     // MEMORYD_STATUS_PORT=9000 -> 9000
func TestStatusPortInvalidEnv(t *testing.T)      // MEMORYD_STATUS_PORT=abc  -> error
func TestStatusPortOutOfRange(t *testing.T)      // 70000 -> error
func TestStatusPortFlag(t *testing.T)            // --port 9090 beats env 9090
```

Each test constructs `newStatusCmd()`, sets env/flags via `t.Setenv` / `cmd.SetArgs`, and asserts on resolved port or error.

**Root cause.** The test used hardcoded ports (19876/19877). When a sibling foreman project (hivemind sitrep server) bound `127.0.0.1:19876`, the `Available` subtest failed (`FindPort(19876)` skipped to 19877) and the `Occupied` subtest couldn't even set up its fixture (`bind: address already in use`).

**Fix.** Derive the base port from the OS instead of a constant: bind `net.Listen("127.0.0.1:0")`, read the assigned port, close the listener, then assert `FindPort(base) == base` / `FindPort(base) == base+1`. The test intent — "FindPort returns a free base, or skips an occupied base" — is unchanged, but the base can never be systematically pre-occupied by a long-lived external process.

```go
package port

import (
	"fmt"
	"net"
	"testing"
)

func TestFindPort(t *testing.T) {
	t.Run("Available", func(t *testing.T) {
		// Re-roll a few times: freeBasePort is only a hint, so if
		// something races us for the port, pick a fresh one and retry.
		for attempt := 0; ; attempt++ {
			base := freeBasePort(t)
			if got := FindPort(base); got == base {
				return
			} else if attempt == 4 {
				t.Fatalf("FindPort(%d) = %d, want %d (base kept being grabbed)", base, got, base)
			}
		}
	})

	t.Run("Occupied", func(t *testing.T) {
		// Same re-roll strategy. Assertion is still base+1 exactly;
		// only re-roll if an unrelated process grabs base+1 mid-test.
		for attempt := 0; ; attempt++ {
			base := freeBasePort(t)
			ln, err := net.Listen("tcp", fmt.Sprintf("127.0.0.1:%d", base))
			if err != nil {
				t.Fatalf("occupy %d: %v", base, err)
			}
			got := FindPort(base)
			ln.Close() // release before any re-roll
			if got == base+1 {
				return
			}
			if attempt == 4 {
				t.Fatalf("FindPort(%d) = %d, want %d", base, got, base+1)
			}
		}
	})
}

// freeBasePort asks the kernel for a currently-free TCP port on
// 127.0.0.1. The listener is closed immediately, so the port is only a
// hint at call time — but unlike a hardcoded constant, it is chosen
// from the OS and cannot be pre-occupied by a long-lived process.
func freeBasePort(t *testing.T) int {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("freeBasePort: %v", err)
	}
	defer ln.Close()
	return ln.Addr().(*net.TCPAddr).Port
}
```

**What not to change:** `FindPort` itself (function under test). The contract tested — "first free port ≥ base, skipping occupied ones" — is preserved verbatim.

