sessionValidator := middleware.SessionValidator(store, middleware.Config{
    SkipPaths: []string{
        AuthPrefix + "/login",
        AuthPrefix + "/refresh",
        AuthPrefix + "/logout",
    },
})
```

> If the `/auth` mount must stay for API-compat reasons, the minimal unblock is correcting the skip paths to reality: `"/v1/auth/api/v1/auth/login"` etc. Canonicalizing is still the right long-term fix — the skip list then matches by construction.

### Fix 2 — SQLite session table: `DATETIME` columns so `time.Time` scans work

`TEXT` timestamp columns make `database/sql`/GORM fail with `unsupported Scan, storing driver.Value type string into type *time.Time`. Rebuild with datetime affinity:

```sql
CREATE TABLE sessions (
    token      TEXT PRIMARY KEY,              -- raw session UUID
    user_id    TEXT NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at DATETIME NOT NULL
);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
```

GORM model tag must pin the affinity (GORM otherwise infers `datetime` fine, but after a raw rebuild it can drift):

```go
type Session struct {
    Token     string    `gorm:"primaryKey;column:token;type:text"`
    UserID    string    `gorm:"column:user_id;type:text"`
    CreatedAt time.Time `gorm:"column:created_at;type:datetime"`
    ExpiresAt time.Time `gorm:"column:expires_at;type:datetime"`
}

// Lookup must compare the raw UUID as stored — no accidental hashing:
func (s *SessionStore) Get(token string) (*Session, error) {
    var sess Session
    err := s.db.First(&sess, "token = ?", token).Error
    return &sess, err
}
```

If a TEXT column is unavoidable, bridge it with a scanner:

```go
type TextTime struct{ time.Time }
func (t *TextTime) Scan(v any) error {
    s, ok := v.(string)
    if !ok { return fmt.Errorf("expected string, got %T", v) }
    tt, err := time.Parse(time.RFC3339Nano, s)
    if err != nil {
        tt, err = time.Parse("2006-01-02 15:04:05.999999999-07:00", s) // sqlite datetime('now') format
    }
    if err != nil { return err }
    t.Time = tt
    return nil
}
```

### Fix 3 — Rate limiter: stop trusting `X-Forwarded-For` from untrusted peers

`getClientIP` reading XFF first means one spoofed header per request rotates buckets and the in-memory limiter never trips. Only honor XFF when the *direct peer* is a known proxy, and then take the right-most untrusted hop (RFC 7239):

```go
var trustedProxies []*net.IPNet // configured via env; empty in default deploys ⇒ XFF fully ignored

func getClientIP(r *http.Request) string {
    peerHost, _, err := net.SplitHostPort(r.RemoteAddr)
    if err != nil { peerHost = r.RemoteAddr }
    peerIP := net.ParseIP(peerHost)
    if !isTrustedProxy(peerIP) {
        return peerIP.String() // untrusted client ⇒ XFF is attacker data
    }
    hops := strings.Split(r.Header.Get("X-Forwarded-For"), ",")
    for i := len(hops) - 1; i >= 0; i-- { // right-most untrusted hop
        if ip := net.ParseIP(strings.TrimSpace(hops[i])); ip != nil && !isTrustedProxy(ip) {
            return ip.String()
        }
    }
    return peerIP.String()
}

func isTrustedProxy(ip net.IP) bool {
    for _, cidr := range trustedProxies {
        if cidr.Contains(ip) { return true }
    }
    return false
}
```

Limiter keys on the normalized IP (port stripped, IPv4-mapped IPv6 folded):

```go
type Limiter struct {
    mu   sync.Mutex
    hits map[string][]time.Time
}

func (l *Limiter) Allow(key string, limit int, window time.Duration) bool {
    l.mu.Lock(); defer l.mu.Unlock()
    now := time.Now(); cutoff := now.Add(-window)
    l.hits[key] = append(l.hits[key], now)
    kept := l.hits[key][:0]
    for _, t := range l.hits[key] { if t.After(cutoff) { kept = append(kept, t) } }
    l.hits[key] = kept
    return len(kept) <= limit
}

// handler:
if !rl.Allow("login:"+getClientIP(r), 5, time.Minute) {
    http.Error(w, "too many requests", http.StatusTooManyRequests)
    return
}
```

### Fix 4 — Probe methodology: 401 vs 404

With the skip list corrected, the validator passes auth routes through, so the router's not-found handler becomes reachable and the two responses are distinguishable:

- Validator-401: `401` with `WWW-Authenticate` and middleware body.
- Router-404: `404` with the router's `404 page not found` body.
- Before the fix, both look like `401` (validator fires first), which is exactly why the deadlock was misdiagnosed as "auth broken" instead of "skip path wrong + route double-prefixed".

