import { OLLAMA_BASE_URL, OLLAMA_DEFAULT_MODEL, OLLAMA_DEFAULT_TIMEOUT_MS, OLLAMA_ID, OLLAMA_MAX_RETRIES } from './constants';
import type { OllamaChatMessage, OllamaChatResponse, OllamaConfig, OllamaEmbeddingResponse } from './types';
import { parseChatResponse, retryable, toChatPayload, withBase } from './utils';
import { registerLLMProvider } from '../../registry'; // never imports back into ./ollama

export class OllamaLLM {
  private readonly cfg: Required<OllamaConfig>;
  constructor(cfg: OllamaConfig = {}) {
    this.cfg = { baseUrl: OLLAMA_BASE_URL, model: OLLAMA_DEFAULT_MODEL, timeoutMs: OLLAMA_DEFAULT_TIMEOUT_MS, maxRetries: OLLAMA_MAX_RETRIES, ...cfg };
  }
  get id(): string { return OLLAMA_ID; }
  async chat(messages: OllamaChatMessage[]): Promise<OllamaChatResponse> {
    return this.request(withBase(this.cfg.baseUrl, '/api/chat'), toChatPayload(this.cfg, messages));
  }
  async embed(inputs: string[]): Promise<number[][]> {
    const raw = await this.request<OllamaEmbeddingResponse>(withBase(this.cfg.baseUrl, '/api/embed'), { model: this.cfg.model, input: inputs });
    return raw.embeddings;
  }
  private async request<T>(url: string, body: unknown): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        const res = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json', ...this.cfg.headers }, body: JSON.stringify(body), signal: AbortSignal.timeout(this.cfg.timeoutMs) });
        if (!res.ok) throw new Error(`ollama http ${res.status}`);
        return parseChatResponse(await res.json()) as T;
      } catch (err) {
        if (!retryable(err) || attempt >= this.cfg.maxRetries) throw err;
      }
    }
  }
}

// ── MUST remain the last statement of core.ts ──────────────────────────────
// Registry consumers import ./index → core.ts evaluates first, so by the time
