}

func TestDeleteHookErrorIsBestEffort(t *testing.T) {
	svc := registry.NewService(&fakeStore{})
	svc.SetDeleteHook(func(context.Context, string) error { return errors.New("docker unavailable") })
	if err := svc.Delete(context.Background(), "app-2"); err != nil { // must NOT surface hook error
		t.Fatalf("hook error leaked: %v", err)
	}
}

func TestDeleteWithoutHookIsNoop(t *testing.T) {
	svc := registry.NewService(&fakeStore{}) // no SetDeleteHook call
	if err := svc.Delete(context.Background(), "app-3"); err != nil {
