// BUG 2: signed subtraction can overflow across MinInt..MaxInt.
// d := bucketMin[i] - prevMax
d := uint64(bucketMin[i]) - uint64(prevMax)  // FIX: unsigned; bucketMin[i] >= prevMax is guaranteed
...
if answer > uint64(^uint(0)>>1) { return int(^uint(0) >> 1) } // saturate instead of wrapping
```

