**2. New `deleteProject` handler — checks must run in this order:**

```go
func (s *Server) deleteProject(w http.ResponseWriter, r *http.Request, name string) {
	// 1) confirm=true checked FIRST -> 400 (before any lookup)
	if r.URL.Query().Get("confirm") != "true" {
		http.Error(w, `{"error":"confirm=true query param required"}`, http.StatusBadRequest)
		return
	}

	// 2) resolve project -> 404 via strings.Contains(not found)
	proj, err := s.db.GetProject(name)
	if err != nil {
		if strings.Contains(err.Error(), "not found") {
			http.Error(w, `{"error":"project not found"}`, http.StatusNotFound)
			return
		}
		http.Error(w, `{"error":"internal error"}`, http.StatusInternalServerError)
		return
	}

	// 3) enabled-project guard -> 409 (already soft-deleted)
	if !proj.Enabled {
		http.Error(w, `{"error":"project already disabled"}`, http.StatusConflict)
		return
	}

	// 4) soft-delete via the pre-existing primitive
	if err := s.db.DeleteProject(name); err != nil {
		http.Error(w, `{"error":"internal error"}`, http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
}
```

