Root cause (GAP-005): `lookPath` only probed cwd-relative `./<name>`, then `cmd/<name>/<name>`, then `PATH`. When `helix` ran from outside the repo root, none of those locations held the delegated binaries that ship next to the `helix` executable — so delegation broke.

Fix: resolve the sibling **next to the running executable first**, via an injectable `lookPathWithExec(name, exePath)` (tests fake `exePath` instead of installing real binaries), keeping the original cwd/PATH fallback chain. New resolution order: `<exeDir>/<name>` → `./<name>` → `cmd/<name>/<name>` → `PATH`.

**`/home/kara/internal/cli/lookpath.go`** (core fix):

```go
// LookPath resolves a delegated subcommand binary such as "helix-estimate".
// Order: 1. <exeDir>/<name> (sibling of os.Executable())  2. ./<name>
//        3. cmd/<name>/<name>  4. PATH
func LookPath(name string) (string, error) {
	exe, err := os.Executable()
	if err != nil {
		return lookPathWithExec(name, "")
	}
	return lookPathWithExec(name, exe)
}

// lookPathWithExec is the injectable resolution used by LookPath. exePath is
// the path of the currently running executable; tests fake it. An empty
// exePath skips sibling resolution and uses the cwd/PATH fallback chain.
func lookPathWithExec(name, exePath string) (string, error) {
	if exePath != "" {
		if p, ok := executableIn(filepath.Dir(exePath), name); ok {
			return p, nil
		}
	}
	if p, err := lookInCwd(name); err == nil {          // legacy: ./<name>
		return p, nil
	}
	if p, err := lookInRepoLayout(name); err == nil {   // legacy: cmd/<name>/<name>
		return p, nil
	}
	return exec.LookPath(name)                          // installed binaries
}
```

The CLI (`cmd/helix/main.go`) delegates `helix <sub>` → `helix-<sub>` via `cli.LookPath`; subcommand binaries live at `cmd/helix-estimate|identity|sandbox` and print cost/identity/sandbox output. The unit test (`internal/cli/lookpath_test.go`) exercises the injectable function with 3 subtests: **exe-dir sibling**, **cwd fallback**, **empty exePath → PATH**.

**Root cause.** `BenchmarkRunner.launchGame` called `GameEngine.startGame()`, which is a stub: it assigns roles to players and flips state to `IN_PROGRESS`, but never starts a loop (no day/night turns, no voting, no win-condition evaluation). The terminal event `WINNER_DETERMINED` is therefore never published and `GameRun.status` stays `RUNNING` forever — the benchmark hangs and the run can never complete. Two independent bugs compound it:

1. **Wrong engine path.** The engine that actually plays the game is the legacy one, exposed via `LegacyGameAdapter.startGame`.
2. **Wrong terminal event.** The legacy engine never emits `WINNER_DETERMINED`. Per MAF-GAP-005 it remaps the terminal `STATE_CHANGE` to `GAME_ENDED`. So even after switching engines, a listener on `WINNER_DETERMINED` alone would still never see completion. The fix must subscribe to **both** event types.

**Fix 1 — `BenchmarkRunner.launchGame` branches to the legacy engine with a deterministic role split:**

```typescript
// src/benchmark/BenchmarkRunner.ts
import { EventBus } from '../events/EventBus';
import { GameEvent } from '../events/GameEvent';
import { LegacyGameAdapter } from '../legacy/LegacyGameAdapter';
import { Role, BenchmarkConfig, GameRun, GameRunStatus } from './types';

/**
 * Deterministic role split used by every benchmark launch so that runs are
 * reproducible across invocations:
 *   MAFIA / SHERIFF -> modelA (mafia side)
 *   TOWN / DOCTOR   -> modelB (town side)
 */
const ROLE_SIDE: Record<Role, 'A' | 'B'> = {
  MAFIA: 'A',
  SHERIFF: 'A',
  TOWN: 'B',
  DOCTOR: 'B',
};

export class BenchmarkRunner {
  constructor(
    private readonly legacyGameAdapter: LegacyGameAdapter,
    private readonly eventBus: EventBus,
  ) {}

  async launchGame(config: BenchmarkConfig): Promise<GameRun> {
    const run = this.createRun(config);

    // Branch to the legacy engine — the ONLY path that actually plays the game
    // to a terminal state. GameEngine.startGame() is a stub (roles only) and
    // would leave the run RUNNING forever.
    const game = await this.legacyGameAdapter.startGame({
      modelA: config.modelA,
      modelB: config.modelB,
      players: config.players.map((player, index) => ({
        id: player.id,
        role: this.assignRole(index, config.players.length),
      })),
    });

    run.bindGame(game.id);
    this.subscribeToTerminalEvents(run);
    return run;
  }

  /** Deterministic round-robin over the fixed role order: MAFIA, SHERIFF, TOWN, DOCTOR. */
  private assignRole(index: number, playerCount: number): Role {
    const ordered: Role[] = ['MAFIA', 'SHERIFF', 'TOWN', 'DOCTOR'];
    return ordered[index % ordered.length];
  }

  private sideFor(role: Role): 'A' | 'B' {
    return ROLE_SIDE[role];
  }

  /**
   * Subscribes to BOTH terminal events. The modern engine documents
   * WINNER_DETERMINED, but the legacy engine — the one actually used here —
   * never emits it: it remaps the terminal STATE_CHANGE to GAME_ENDED
   * (MAF-GAP-005). Listening to only one type would resurrect the stuck-run
   * bug. completion() is idempotent so a double fire is harmless.
   */
  private subscribeToTerminalEvents(run: GameRun): void {
    const finish = (payload: { gameId: string; winner: string }) => {
      if (payload.gameId !== run.gameId) return;
      this.completeRun(run, payload);
    };

    this.eventBus.on(GameEvent.WINNER_DETERMINED, finish);
    this.eventBus.on(GameEvent.GAME_ENDED, finish);

    // Safety net: never allow a run to hang forever.
    const timeout = setTimeout(() => finish({ gameId: run.gameId, winner: 'TIMEOUT' }), run.maxDurationMs);
    run.onTerminated(() => clearTimeout(timeout));
  }

  private completeRun(run: GameRun, payload: { gameId: string; winner: string }): void {
    if (run.status !== GameRunStatus.RUNNING) return; // idempotent
    run.status = GameRunStatus.COMPLETED;
    run.winner = payload.winner;
    run.completedAt = new Date();
    this.eventBus.off(GameEvent.WINNER_DETERMINED, ...); // detach listeners (cleanup)
    this.eventBus.off(GameEvent.GAME_ENDED, ...);
  }
}
```

**Fix 2 — wire the already-implemented repository methods into the routes.** `getStatus` / `getProgress` / `listRuns` / `cancel` already exist on the runner/store; they were simply never mounted:

```typescript
// src/routes/benchmark.ts
import { Router } from 'express';
import { BenchmarkRunner } from '../benchmark/BenchmarkRunner';

export function benchmarkRouter(runner: BenchmarkRunner): Router {
  const router = Router();

  router.post('/api/v1/benchmark', async (req, res, next) => {
    try {
      const run = await runner.launchGame(req.body);
      res.status(202).json({ id: run.id, status: run.status });
    } catch (err) {
      next(err);
    }
  });

  router.get('/api/v1/benchmark/runs', (_req, res) => {
    res.json({ runs: runner.listRuns() });
  });

  router.get('/api/v1/benchmark/:id', (req, res) => {
    const run = runner.getStatus(req.params.id);
    if (!run) {
      return res.status(404).json({ error: `run ${req.params.id} not found` });
    }
    res.json({ ...run, progress: runner.getProgress(req.params.id) });
  });

  router.post('/api/v1/benchmark/:id/cancel', (req, res) => {
    const cancelled = runner.cancel(req.params.id);
    if (!cancelled) {
      return res.status(404).json({ error: 'run not found or already finished' });
    }
    res.json({ id: req.params.id, status: 'CANCELLED' });
  });

  return router;
}
```

`cancel` is the escape hatch for any run that is legitimately still playing (long games, slow models), so no client ever has to wait on a truly stuck run:

```typescript
// BenchmarkRunner.cancel
cancel(runId: string): boolean {
  const run = this.runs.get(runId);
  if (!run || run.status !== GameRunStatus.RUNNING) return false;
  run.status = GameRunStatus.CANCELLED;
  this.eventBus.emit(GameEvent.GAME_CANCELLED, { gameId: run.gameId, reason: 'client_cancel' });
  return true;
}
```

**Root cause.** The board had two durable artifacts that must agree — `events.jsonl` (append-only log) and `tasks.jsonl` (row state) — but the completion pipeline trusted the worker's "done" signal (commit message / chat) instead of verifying the durable writes. In GAP-004, judge PASS landed at tick 187, yet the `task_completed` event was never appended, so the row never flipped. Lesson encoded as a contract: **a task is completed iff (1) events.jsonl holds a `task_completed` event with `completion_id == "<task>:<real commit>"` AND (2) the tasks.jsonl row is `status=completed` carrying that same id. A message saying "complete" proves nothing.**

**The fix (three parts, all idempotent so crash/rerun is safe):**

**1. Completion contract + idempotency key** — every completion is keyed by `completion_id = f"{task_id}:{commit}"`. Event appends dedupe on `_unique`; the row flip only transitions `pending→completed` (a second run is a no-op):

```python
def flip_to_completed(self, task_id, completion_id, commit, verdict):
    with self._lock:
        rows = read_jsonl(self.path)
        for r in rows:
            if r.get("task_id") != task_id:
                continue
            if r.get("status") == "completed":
                return (True, "already_completed") if r.get("completion_id") == completion_id \
                       else (False, "completed_with_other_completion")
            r.update(status="completed", completion_id=completion_id,
                     commit=commit, judge=verdict, updated_at=_now())
            write_jsonl_atomic(self.path, rows)   # temp file + fsync + os.replace
            return True, "flipped"
        return False, "task_not_found"
```

**2. Post-worker gate** — after a worker reports done / judge PASSes, verify the *durable* state, and repair if either half is missing:

```python
def verify_task_completed(board, task_id, completion_id_=None):
    events = board.events.find("task_completed", task_id=task_id)
    if completion_id_ is not None:
        events = [e for e in events if e.get("completion_id") == completion_id_]
    row = board.tasks.get(task_id)
    event_ok, row_ok = len(events) > 0, row is not None and row.get("status") == "completed"
    return {"event_appended": event_ok, "row_flipped": row_ok,
            "verified": event_ok and row_ok}

def ensure_completed_after_worker_done(board, task_id, live_verify):
    v = verify_task_completed(board, task_id)
    if v["verified"]:
        return {"verified": True, "remediated": False, "verification": v}
    result = remediate(board, task_id, live_verify)
    return {"verified": result.ok, "remediated": True, "result": result.as_dict(),
            "verification": verify_task_completed(board, task_id)}
```

**3. `remediate` (the foreman's `append_board_task_completed`)** — four steps, each idempotent:

```python
def remediate(board, task_id, live_verify, stale=False):
    row = board.tasks.get(task_id)
    if row is None:
        return RemediationResult(task_id, False, "task_not_found", None, None)
    # 1) LIVE RE-VERIFY against the real commit (judge = source of truth)
    real = live_verify(task_id, row.get("commit"))
    cid = completion_id(task_id, real["commit"])
    if real.get("verdict") != "PASS":                    # never flip a failed re-verify
        board.events.append({"event": "task_reverify_failed", ...}, unique_key=f"reverify_failed:{cid}")
        return RemediationResult(task_id, False, "reverify_failed", ...)
    # 2) APPEND task_completed with real commit hash + judge verdict (deduped)
    appended = board.events.append({"event": "task_completed", "commit": real["commit"],
                                    "verdict": "PASS", "completion_id": cid, ...},
                                   unique_key=f"task_completed:{cid}")
    # 3) FLIP the row atomically (only pending rows flip)
    flipped, why = board.tasks.flip_to_completed(task_id, cid, real["commit"], "PASS")
    # 4) AUDIT event, deduped by completion_id
    board.events.append({"event": "task_completed_repaired" if not stale else "task_stale_repaired",
                         "event_appended_now": appended, "row_flipped_now": why == "flipped", ...},
                        unique_key=f"repaired:{cid}")
    return RemediationResult(task_id, True, "repaired", ...)
```

Plus a periodic `sweep_stale` that finds `pending` rows older than a threshold and remediates them — so stale rows self-heal even if the worker hook was never called. Durable IO details: event appends take a cross-process `flock`, write, then `fsync`; row rewrites go through temp file + `fsync` + `os.replace`; a torn tail line left by a crash is tolerated on read and a newline is forced before appends so the new event never merges into the fragment.

