const GOLDEN_SOURCE_TREE = 'Demo Project'; // seeded tree the goldens were captured against

test('tree picker golden capture', async ({ page }) => {
  await page.goto('/app');
  const chosen = await selectGoldenSourceTree(page, GOLDEN_SOURCE_TREE);
  expect(chosen).toBe(GOLDEN_SOURCE_TREE);
  await expect(page).toHaveScreenshot('tree-picker.png'); // golden untouched
});
```

The equivalent Python reference implementation (used for verification below):

```python
