// U-GAP-005 fix: spec 01-core §6.2 promised this route; it was never wired.
mux.Handle("GET /api/v1/pools/{appID}/status", sandbox.StatusHandler(mgr))

// Existing route: /execute runs GetOrCreatePool before Acquire.
