export function resolveEmbeddingConfig(cfg: EmbeddingConfig = {}): ResolvedEmbeddingConfig {
  if (cfg.provider != null && cfg.provider !== "") {
    if (!isKnownProvider(cfg.provider)) throw new Error(`unknown embedding provider "${cfg.provider}"`);
    return { mode: "explicit", providerId: cfg.provider };
  }
  return { mode: "auto" };   // old code did cfg.provider ?? "lmstudio" + explicit flag — the drift
}
