**Root cause (GAP-007):** `updateConfig()` used `getConfig()` — the env-applied *runtime view* — as its merge base, then serialized that view verbatim to disk. Any test running with `DUCKBRAIN_NAMESPACES_PATH=/tmp/...` persisted the scratch path into the production `duckbrain.config.json`, which the daemon then loaded on restart as the fleet memory backbone. Two compounding bugs: the wrong merge base, and `registerNamespace()` passing the whole env-applied config back into the write path.

**The pattern:** env-only fields are never persisted. Split reads (file vs file+env); writes always merge against the raw file; env is applied at read time only.

```typescript
// src/config.ts (fixed)
export interface DuckbrainConfig {
  namespacesPath: string;
  namespaceMappings: Record<string, string>;
}

/** Raw on-disk config. NO env overrides. The only valid merge base for writes. */
export function readFileConfig(): DuckbrainConfig {
  try {
    return JSON.parse(readFileSync(CONFIG_PATH, 'utf8')) as DuckbrainConfig;
  } catch {
    return defaultConfig(); // missing/corrupt file -> defaults
  }
}

/** File + env. Runtime callers' view; never a write base. */
export function getConfig(): DuckbrainConfig {
  const cfg = readFileConfig();
  if (process.env.DUCKBRAIN_NAMESPACES_PATH) {
    cfg.namespacesPath = process.env.DUCKBRAIN_NAMESPACES_PATH;
  }
  return cfg;
}

/** Persist a patch: merge against raw file, strip env-only fields, write. */
export function updateConfig(patch: Partial<DuckbrainConfig>): DuckbrainConfig {
  const persistable: Partial<DuckbrainConfig> = { ...patch };
  for (const field of envOverriddenFields()) delete persistable[field]; // /tmp path can never reach disk
  const merged = deepmerge(readFileConfig(), persistable);             // base = raw file, NOT getConfig()
  writeFileSync(CONFIG_PATH, JSON.stringify(merged, null, 2) + '\n', 'utf8');
  return getConfig();                                                  // runtime callers still see env
}

/** Pass ONLY the persistable field — never the whole env-applied config. */
export function registerNamespace(namespace: string, mapping: string): DuckbrainConfig {
  const base = readFileConfig();
  return updateConfig({
    namespaceMappings: { ...base.namespaceMappings, [namespace]: mapping },
  });
}
```

Key points vs. the old code:

| | Before (buggy) | After (fixed) |
|---|---|---|
| Merge base for writes | `getConfig()` (env applied) | `readFileConfig()` (raw) |
| `registerNamespace` patch | whole env-applied config | `{ namespaceMappings }` only |
| `getConfig()` return | env applied | env applied (unchanged for runtime callers) |
| Env field in a write patch | persisted verbatim | stripped before merge (`envOverriddenFields()`) |

`envOverriddenFields()` is computed **at call time**, not module load, so an env var set after import (exactly what tests do in `before`/`beforeEach`) is still stripped. CI guards the whole class of regression:

```yaml
# .github/workflows/ci.yml
- run: npm test
- name: Assert config file untouched by tests
  run: git diff --exit-code duckbrain.config.json
```

Two independent fixes, both reproduced and verified in `/tmp/repro-openapi` (Go 1.26, module `repro`).

### Fix 1 — Invocation: single-file form → package form

A goconst slice added `scripts/generate-openapi/constants.go`:

```go
package main

const (
	// StrSpecsOpenapiYaml is the generated OpenAPI output path.
	StrSpecsOpenapiYaml = "specs/openapi-generated.yaml"
	// StrSystem is the API base path used in the generated spec's server URL.
	StrSystem = "/system"
)
```

`main.go` references both constants. `go run scripts/generate-openapi/main.go` compiles **only** `main.go` (`command-line-arguments`), so `constants.go` (and any sibling like `collect.go`) is invisible and the build dies with `undefined: StrSpecsOpenapiYaml` / `undefined: StrSystem`. The fix is to run the whole package:

```bash
# BROKEN  — compiles main.go in isolation
go run scripts/generate-openapi/main.go

# FIXED   — compiles the entire scripts/generate-openapi package
go run ./scripts/generate-openapi [--generate-missing] [--validate]
```

`scripts/generate-openapi/generate.sh` (and any CI/Makefile/README invocation) must use the package form:

```bash
#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/../.."
go run ./scripts/generate-openapi "$@"
```

### Fix 2 — Generator regex must resolve `Str*` constants

The route scanner matches `r.Group(...)`, `r.GET(...)`, etc. A regex that only accepts string literals (`r\.Group\("..."`) silently drops registrations written with constants (`v1 := r.Group(StrV1X)`, `r.GET(StrSystem+"/ping")`) — the generated spec loses whole route trees and Spec Validation goes red.

The fix adds `loadStringConstants` (parses `const X = "..."`, `const X string = "..."`, and grouped `const ( ... )` blocks across the app tree) and resolves identifiers — bare and package-qualified (`consts.StrV1X`) — inside path expressions:

```go
// constLineRe:  const Name [string] = "value"
var constLineRe = regexp.MustCompile(`\bconst\s+([A-Za-z_][A-Za-z0-9_]*)\s*(?:string)?\s*=\s*"([^"]*)"`)
// constBlockRe: const ( ... )
var constBlockRe = regexp.MustCompile(`(?m)\bconst\s*\(([^)]*)\)`)

func loadStringConstants(dirs ...string) map[string]string {
	consts := map[string]string{}
	for _, dir := range dirs {
		_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
			if err != nil || d.IsDir() || !strings.HasSuffix(path, ".go") ||
				strings.HasSuffix(path, "_test.go") {
				return nil
			}
			src, _ := os.ReadFile(path)
			text := string(src)
			for _, m := range constBlockRe.FindAllStringSubmatch(text, -1) { // grouped first
				for _, e := range constEntryRe.FindAllStringSubmatch(m[1], -1) {
					consts[e[1]] = e[2]
				}
			}
			rest := constBlockRe.ReplaceAllString(text, "") // single-line outside blocks
			for _, m := range constLineRe.FindAllStringSubmatch(rest, -1) {
				consts[m[1]] = m[2]
			}
			return nil
		})
	}
	return consts
}

// resolveIdentifier: bare (StrV1X) or package-qualified (consts.StrV1X).
func resolveIdentifier(tok string, consts map[string]string) (string, bool) {
	if v, ok := consts[tok]; ok {
		return v, true
	}
	if i := strings.LastIndexByte(tok, '.'); i >= 0 {
		if v, ok := consts[tok[i+1:]]; ok {
			return v, true
		}
	}
	return "", false
}

// extractPath: "literal" | StrV1X | consts.StrV1X | StrSystem + "/ping"
// Unresolvable identifiers yield ok=false → the route is dropped with a
// verbose warning instead of being emitted with a wrong path.
func extractPath(expr string, consts map[string]string, resolve bool) (string, bool) {
	var b strings.Builder
	for _, part := range splitConcat(strings.TrimSpace(expr)) { // top-level '+'
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if len(part) >= 2 && (part[0] == '"' || part[0] == '\'') {
			b.WriteString(part[1 : len(part)-1])
			continue
		}
		if !resolve {
			return "", false // pre-fix regex behavior
		}
		if v, ok := resolveIdentifier(part, consts); ok {
			b.WriteString(v)
			continue
		}
		return "", false
	}
	return b.String(), true
}
```

`collectRoutes` then (1) resolves group prefixes first — `v1 := r.Group(consts.StrV1X)` registers `v1 → "/v1x"` — and (2) prefixes every `v1.GET("/users")` with its group. Comments are stripped before matching so commented-out examples never leak into the spec.

