**Root cause.** The downstream Go test called `/v1/cancel` with a session ID it never registered through `/v1/process`. The upstream SDK (pinned via `replace` in `go.mod`) shipped the OpenAPI contract change **GAP-DOG-002**: its harness handler now has a session-existence guard, so cancel/result on an unknown session returns **404** instead of the old **200**. The test asserted `200`, so it broke. It's not a flake — it fails solo because the harness state is created fresh per test and the session is simply never there.

**Fix.** Register the session through the real endpoint first (`POST /v1/process`), then cancel it — exactly mirroring the SDK's own updated test. This verifies the full path and matches the new contract. Optionally pin the 404 behavior in a second test so drift is caught at the contract boundary, not by surprise later.

```go
// harness handler (SDK side, local replace) — new session-existence guard per GAP-DOG-002
func (h *Harness) Cancel(id string) (int, error) {
	s, ok := h.sessions[id]
	if !ok {
		return http.StatusNotFound, fmt.Errorf("session %q not found", id) // was 200 before
	}
	s.Status = "canceled"
	return http.StatusOK, nil
}
```

```go
// downstream test — FIXED: register through the real endpoint first
func TestCancelSession(t *testing.T) {
	h := harness.New()

	// Fix: create the session via /v1/process before cancelling it.
	s := h.Process("session-abc123")

	status, err := h.Cancel(s.ID) // full path: register -> cancel
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if status != http.StatusOK {
		t.Fatalf("expected 200 for registered session cancel, got %d", status)
	}
}

// Pin the new contract so future drift surfaces here, not in unrelated tests.
func TestCancelUnknownSession404(t *testing.T) {
	h := harness.New()
	status, err := h.Cancel("session-never-registered")
	if err == nil {
		t.Fatal("expected error for unknown session")
	}
	if status != http.StatusNotFound {
		t.Fatalf("expected 404 for unknown session, got %d", status)
	}
}
```

**Root cause:** tick-137's dependency-free Swagger UI commit was destroyed in a history rewrite + force-push. The board task ("Swagger UI 404") has no memory of it, so the fix is a faithful re-implementation of the proven approach recovered from DuckBrain: **no npm dependency** (container `node_modules` are image-frozen, so `npm i swagger-ui-dist` would fail at deploy), inline HTML served from `routes.ts`, assets from `unpkg` CDN, and a **per-route CSP override** so the rest of the app keeps its strict policy.

**Fix — `src/routes.ts`** (the core deliverable):

```typescript
import { Router, type Request, type Response } from 'express';

const SWAGGER_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>API Docs</title>
  <link rel="stylesheet" href="https://unpkg.com/swagger-ui-dist@5/swagger-ui.css" />
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://unpkg.com/swagger-ui-dist@5/swagger-ui-bundle.js"></script>
  <script>
    window.onload = function () {
      window.ui = SwaggerUIBundle({
        url: '/openapi.json',
        dom_id: '#swagger-ui',
        deepLinking: true,
        presets: [SwaggerUIBundle.presets.apis],
        layout: 'BaseLayout',
      });
    };
  </script>
</body>
</html>`;

// Relaxed only for this route; the app-wide strict CSP stays untouched.
const SWAGGER_CSP = [
  "default-src 'self'",
  "script-src 'self' 'unsafe-inline' https://unpkg.com",
  "style-src 'self' 'unsafe-inline' https://unpkg.com",
  "img-src 'self' data: https://unpkg.com",
  "font-src 'self' data:",
  "connect-src 'self'",
].join('; ');

export function swaggerRoutes(openApiPath = '/openapi.json'): Router {
  const router = Router();

  // Both path forms: /swagger and /swagger/ (trailing slash)
  router.get(['/swagger', '/swagger/'], (_req: Request, res: Response) => {
    // Remove any app-level CSP set by earlier global middleware, then apply
    // the route-local policy so the two never bleed into each other.
    // NB: res.removeHeader() returns undefined — it cannot be chained.
    res.removeHeader('Content-Security-Policy');
    res
      .set('Content-Security-Policy', SWAGGER_CSP)
      .set('Content-Type', 'text/html; charset=utf-8')
      .set('Cache-Control', 'no-store')
      .send(SWAGGER_HTML.replace('"/openapi.json"', JSON.stringify(openApiPath)));
  });

  return router;
}
```

**Wiring — `src/app.ts`:** register the router after the global strict-CSP middleware so the route handler can override it per-request; keep the existing `/openapi.json` endpoint (the `url` the UI boots against):

```typescript
app.use((_req, res, next) => { res.set('Content-Security-Policy', STRICT_CSP); next(); });
app.use(swaggerRoutes());          // /swagger, /swagger/ → HTML; per-route CSP
app.get('/openapi.json', (_req, res) => res.json(openApiDocument));
```

