### 4. Authoritative parity verification (the core of the fix)

The `Export-parity-check.py` result is **known-faulty**: its regex misses `export async function …` (the `async` modifier between `export` and `function`), so it reports FAIL and shows only **5 of the 11** pre-split symbols. Manual symbol set-compare is authoritative. The robust implementation uses the TypeScript compiler API, where `async` is just a modifier and cannot corrupt the count:

```ts
// scripts/parity-check.ts — authoritative export-set compare (TS compiler API)
import ts from "typescript";
import { readFileSync } from "node:fs";

function exportedNames(file: string): Set<string> {
  const src = readFileSync(file, "utf8");
  const sf = ts.createSourceFile(file, src, ts.ScriptTarget.Latest, true);
  const out = new Set<string>();
  const isExported = (n: ts.Node) =>
    n.modifiers?.some(m => m.kind === ts.SyntaxKind.ExportKeyword) ?? false;

  function visit(n: ts.Node): void {
    if (ts.isExportDeclaration(n)) {
      const clause = n.exportClause;
      if (clause && ts.isNamedExports(clause))
        for (const spec of clause.elements) out.add(spec.name.text);
      // export * from "..." — passthrough, no new symbol here
    } else if (
      (ts.isFunctionDeclaration(n) || ts.isClassDeclaration(n) ||
       ts.isInterfaceDeclaration(n) || ts.isTypeAliasDeclaration(n) ||
       ts.isEnumDeclaration(n)) && isExported(n) && n.name
    ) {
      out.add(n.name.text);                 // `async` is a modifier — parsed fine
    } else if (ts.isVariableStatement(n) && isExported(n)) {
      for (const d of n.declarationList.declarations)
        if (ts.isIdentifier(d.name)) out.add(d.name.text);
    }
    ts.forEachChild(n, visit);
  }
  visit(sf);
  return out;
}

const pre  = exportedNames("artifacts/change-detection.pre-split.ts"); // captured snapshot
const post = exportedNames("src/change-detection/index.ts");
const missing = [...pre].filter(s => !post.has(s));   // symbol LOSS → FAIL
const leaked  = [...post].filter(s => !pre.has(s));   // symbol LEAK  → FAIL

if (missing.length || leaked.length) {
  console.error("PARITY FAIL", { pre: pre.size, post: post.size, missing, leaked });
  process.exit(1);
}
console.log(`PARITY PASS: ${pre.size}/${post.size} symbols (3 interfaces + 8 fns)`);
```

Expected output: `PARITY PASS: 11/11 symbols (3 interfaces + 8 fns)`. This **bidirectional** compare is the fix for the parser artifact: it catches both a dropped symbol and an accidental internal helper leaking into the public API.

