  ...clientReq.headers,
  authorization: `Bearer ${federationToken}`,
  'x-9r-client-authorization': clientReq.headers['authorization'],
}
```

# SOLUTION

**Root cause of the broken scaffold.** The old generator emitted a `package.json` like:

```json
{
  "scripts": { "test": "speclang validate && npm test" },
  "devDependencies": {}
}
```

Three compounding bugs: (1) `devDependencies` empty → `npm install` installs nothing; (2) no `bin` anywhere → `speclang` is not on PATH inside the project, so `speclang validate` → *command not found* (and you must not fix that by fetching npm's `speclang` — an unrelated registry package); (3) the test script re-invokes `npm test` after `speclang validate` succeeds → infinite recursion.

**The fix.** At scaffold time, compute the *tool repo root* from the scaffolder's own location and embed it as an absolute `file:` devDependency. `npm install` then symlinks the tool repo into `node_modules` and, because the repo's `package.json` declares `bin.speclang`, npm links `node_modules/.bin/speclang` — no registry lookup, no PATH tricks, no global install. The test script becomes a single non-recursive `speclang validate`.

**Tool repo side** — `package.json` must declare the bin entry (this is what gets linked):

```json
{
  "name": "speclang",
  "bin": { "speclang": "./bin/speclang.js" }
}
```

**Scaffolder side** (`src/scaffold.ts`, the actual fix — compiled output lives one directory below the repo root, i.e. `<repoRoot>/dist/`):

```ts
import * as fs from 'node:fs';
import * as path from 'node:path';

/** Compiled to <repoRoot>/dist/scaffold.js, so the repo root is exactly
 *  one directory above __dirname. path.resolve handles spaces + Windows
 *  separators; the invariant check makes a wrong layout fail loudly. */
export function resolveRepoRoot(moduleDir: string = __dirname): string {
  const root = path.resolve(moduleDir, '..');
  const pkg = JSON.parse(
    fs.readFileSync(path.join(root, 'package.json'), 'utf8'),
  ) as { name?: string };
  if (pkg.name !== 'speclang') {
    throw new Error(`speclang repo root not found at ${root}`);
  }
  return root;
}

export function renderPackageJson(projectName: string, repoRoot: string): string {
  return JSON.stringify({
    name: projectName,
    version: '0.1.0',
    private: true,
    scripts: {
      test: 'speclang validate',           // FIXED: was "speclang validate && npm test"
    },
