```ts
export async function createUniqueTree(page: Page, prefix = 'sync-e2e') {
  const name = `${prefix}-${Date.now()}-${randomUUID().slice(0, 8)}`;
  const res = await page.request.post('/api/trees', { data: { name } });
  if (!res.ok()) throw new Error(`createUniqueTree failed: ${res.status()} ${await res.text()}`);
  const { tree } = await res.json();
  if (!tree?.id) throw new Error(`no tree id: ${JSON.stringify(await res.json())}`);
  return tree;
}
```

