```ts
import { Router } from 'express';
import { asyncHandler, ApiError } from '../errors';
import { squashTool, getCompactionStatsTool } from '../../mcp/tools/squash';

export const compactionRouter = Router();

function assertOptionalString(value: unknown, field: string): void {
  if (value !== undefined && typeof value !== 'string') {
    throw ApiError.badRequest('VALIDATION_ERROR', `"${field}" must be a string`,
      { field, expected: 'string' });
  }
}
function assertOptionalPositiveInt(value: unknown, field: string): void {
  if (value !== undefined && (!Number.isInteger(value) || (value as number) < 1)) {
    throw ApiError.badRequest('VALIDATION_ERROR', `"${field}" must be a positive integer`,
      { field, expected: 'integer >= 1' });
  }
}

compactionRouter.post('/squash', asyncHandler(async (req, res) => {
  const body: unknown = req.body;
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw ApiError.badRequest('VALIDATION_ERROR', 'request body must be a JSON object');
  }
  const input = body as Record<string, unknown>;
  assertOptionalString(input.targetRepoId, 'targetRepoId');
  assertOptionalString(input.message, 'message');
  assertOptionalPositiveInt(input.keep, 'keep');
  const result = await squashTool.handler({
    targetRepoId: input.targetRepoId as string | undefined,
    message:     input.message as string | undefined,
    keep:        input.keep as number | undefined,
  });
  res.json({ data: result });
}));

compactionRouter.get('/stats', asyncHandler(async (req, res) => {
  const targetRepoId: unknown = req.query.targetRepoId; // string | string[] | undefined
  assertOptionalString(targetRepoId, 'targetRepoId');   // rejects ?a=1&a=2 arrays
  const result = await getCompactionStatsTool.handler({ targetRepoId: targetRepoId as string | undefined });
  res.json({ data: result });
}));
```

