export interface BatteryWindow { start: number; end: number }
export const FIXTURE_WINDOW: BatteryWindow = { start: 78, end: 83 };

export interface BatteryState { tick: number; lastFullRunTick: number | null }

export function shouldRunFullBattery(
  state: BatteryState,
  window: BatteryWindow = FIXTURE_WINDOW,
): boolean {
  const { tick, lastFullRunTick } = state;
  if (tick < window.start || tick > window.end) return false;   // outside fixture window
  // first tick of the window, or first tick after a container rebuild mid-window
