-- ON CONFLICT makes the seed idempotent: fresh DB inserts, existing DB no-ops.
INSERT INTO users (id, email, display_name, role, jwt_sub)
VALUES (
  '00000000-0000-0000-0000-00000000dead', -- dev JWT user id E2E tokens resolve to
  'dev@canopy.local',
  'Dev User',
  'admin',
  'dev-jwt-subject'
)
ON CONFLICT (jwt_sub) DO NOTHING;
```

Go bootstrap (pgx/v5), run after migrations, before serving:
