func seedDevUser(ctx context.Context, pool *pgxpool.Pool, cfg Config) error {
	_, err := pool.Exec(ctx, `
		INSERT INTO users (id, email, display_name, role, jwt_sub)
		VALUES ($1, $2, $3, $4, $5)
		ON CONFLICT (jwt_sub) DO NOTHING`,
