**2. First-run bootstrap token** (`iam/bootstrap.go`) — generates a 32-hex token only when `<data-dir>/iam/principals.yaml` is missing; subsequent runs load the persisted token and never regenerate (unless `--regenerate-token`):

```go
func EnsureBootstrap(dataDir string, force bool) (*Result, error) {
	iamDir := filepath.Join(dataDir, "iam")
	principalsPath := filepath.Join(iamDir, "principals.yaml")
	policiesPath := filepath.Join(iamDir, "policies.yaml")

	if !force {
		if tok, err := loadToken(principalsPath); err == nil {   // rerun: reuse, no regen
			return &Result{Token: tok, Created: false, IAMDir: iamDir}, nil
		}
	}
	tok, err := generateToken() // 16 random bytes → 32 lowercase hex chars
	...
