## The Fix

### 4a. New file `src/commands/consolidate.ts` (the command core)

```ts
import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';

export interface ConsolidateOptions {
  /** Target UTC day as 'YYYY-MM-DD'. Defaults to today in UTC. */
  target?: string;
  /** Root of the store: contains namespaces/<ns>/<domain>/<YYYY-MM>/current.jsonl */
  namespacesRoot?: string;
  /** Explicitly arm the write path. */
  writeDigest?: boolean;
  /** Tests only: force dry-run even if DUCKBRAIN_API_KEY is set. */
  forceDryRun?: boolean;
}

interface MemoryRow {
  embedding_text?: string;
  key?: string;
}

const PREVIEW_CAP = 5; // capped previews per namespace

function utcDayString(d: Date): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(
    d.getUTCDate(),
  ).padStart(2, '0')}`;
}

/** Pull the 'YYYY-MM-DD' prefix out of a row's timestamp (ISO/RFC/plain all OK). */
function rowDay(row: MemoryRow): string | null {
  const ts = (row as Record<string, unknown>)['timestamp'];
  return typeof ts === 'string' && ts.length >= 10 ? ts.slice(0, 10) : null;
}

function contentHash(row: MemoryRow): string {
  return crypto
    .createHash('sha256')
    .update(`${row.embedding_text ?? ''}\u0000${row.key ?? ''}`)
    .digest('hex');
}

async function listDirs(parent: string): Promise<string[]> {
  let entries: string[];
  try {
    entries = await fs.readdir(parent);
  } catch {
    return [];
  }
  const out: string[] = [];
  for (const e of entries) {
    try {
      if ((await fs.stat(path.join(parent, e))).isDirectory()) out.push(e);
    } catch {
      /* skip */
    }
  }
  return out.sort();
}

interface NsStats {
  ns: string;
  rows: number;
  unique: number;
  dups: number;
  preview: string[];
}

/** Scan everything for one namespace and return per-ns stats. */
async function scanNamespace(ns: string, root: string, target: string): Promise<NsStats> {
  const nsDir = path.join(root, ns);
  const seen = new Set<string>();
  const preview: string[] = [];
  let rows = 0;
  let dups = 0;

  for (const domain of await listDirs(nsDir)) {
    const domainDir = path.join(nsDir, domain);
    for (const ym of await listDirs(domainDir)) {
      if (!/^\d{4}-\d{2}$/.test(ym)) continue; // only month buckets
      const file = path.join(domainDir, ym, 'current.jsonl');
      let content: string;
      try {
        content = await fs.readFile(file, 'utf8');
      } catch {
        continue; // bucket without current.jsonl
      }
      for (const line of content.split('\n')) {
        if (!line.trim()) continue;
        const row: MemoryRow = JSON.parse(line);
        if (rowDay(row) !== target) continue; // filter to target UTC day
        rows++;
        const h = contentHash(row);
        if (seen.has(h)) {
          dups++; // collapse: first occurrence kept, later ones counted as dups
        } else {
          seen.add(h);
          if (preview.length < PREVIEW_CAP) {
            preview.push((row.embedding_text ?? '').slice(0, 120));
          }
        }
      }
    }
  }
  return { ns, rows, unique: seen.size, dups, preview };
}

/** Produce the digest block. Dry-run by default; armed write path is separate. */
export async function consolidate(opts: ConsolidateOptions = {}): Promise<string> {
  const target = opts.target ?? utcDayString(new Date());
  const root = path.resolve(opts.namespacesRoot ?? process.env['DUCKBRAIN_NAMESPACES_PATH'] ?? 'namespaces');

  let nsNames: string[];
  try {
    nsNames = await fs.readdir(root);
  } catch {
    throw new Error(`namespaces root not found: ${root}`);
  }
  nsNames.sort();

  const stats = new Map<string, NsStats>(); // insertion-ordered
  for (const ns of nsNames) {
    const st = await scanNamespace(ns, root, target);
    if (st.rows > 0) stats.set(ns, st);
  }

  const lines: string[] = [];
  lines.push('===== duckbrain consolidate =====');
  lines.push(`target    : ${target} (UTC)`);
  lines.push(`namespaces: ${stats.size}`);
  for (const st of stats.values()) {
    lines.push(`  ${st.ns.padEnd(12)} rows=${st.rows} unique=${st.unique} dups=${st.dups}`);
    for (const p of st.preview) lines.push(`      - ${p}`);
  }
  const totalRows = [...stats.values()].reduce((a, s) => a + s.rows, 0);
  const totalUnique = [...stats.values()].reduce((a, s) => a + s.unique, 0);
  const totalDups = [...stats.values()].reduce((a, s) => a + s.dups, 0);
  lines.push('===== digest =====');
  lines.push(`total rows=${totalRows} unique=${totalUnique} dups=${totalDups} (UTC ${target})`);
  return lines.join('\n');
}
```

### 4b. Write-path arming (dry-run default) and the API POST with 201 + read-back

New file `src/commands/consolidate-write.ts` (kept separate so tests can mock the module):

```ts
export const API_NAMESPACE = 'duckbrain';

export function shouldWrite(opts: { writeDigest?: boolean; forceDryRun?: boolean }): boolean {
  if (opts.forceDryRun) return false;          // tests always disable the write path
  if (opts.writeDigest) return true;           // explicit CLI flag
  return Boolean(process.env['DUCKBRAIN_API_KEY']); // armed by ambient env
}

/**
 * POST the digest to /api/memories?namespace=duckbrain with X-API-Key.
 * Requires a 201, then performs a read-back GET to verify persistence.
 */
export async function writeDigest(
  digest: string,
  apiKey = process.env['DUCKBRAIN_API_KEY'] ?? '',
  baseUrl = process.env['DUCKBRAIN_API_ENDPOINT'] ?? 'http://localhost:8787',
): Promise<void> {
  if (!apiKey) throw new Error('writeDigest requires DUCKBRAIN_API_KEY');

  const post = await fetch(`${baseUrl}/api/memories?namespace=${API_NAMESPACE}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': apiKey },
    body: JSON.stringify({ digest }),
  });
  if (post.status !== 201) {
    throw new Error(`digest write failed: HTTP ${post.status} ${await post.text()}`);
  }

  // read-back verification
  const rb = await fetch(`${baseUrl}/api/memories?namespace=${API_NAMESPACE}`, {
    headers: { 'X-API-Key': apiKey },
  });
  if (rb.status !== 200) throw new Error(`digest read-back failed: HTTP ${rb.status}`);
  const body = (await rb.json()) as { digest?: string };
  if (body.digest !== digest) {
    throw new Error('digest read-back mismatch: stored value differs from payload');
  }
}
```

