# Fixing `serialized-function-body-loses-module-scope`

**Symptom:** `ReferenceError: shq is not defined` raised 22 ms before the end of a 12-minute pipeline run, while the whole-file TypeScript check passed and the process still exited `0` (silent loss).

**Applies to:** `hermes-dagger` @ `5ed7bae` — Go DAG engine + QuickJS + TypeScript node DSL, where every registered callback is serialized with `Function.prototype.toString()` and re-evaluated in a fresh sandbox.

## 1. Root cause

The engine collects registrations from QuickJS, stores each node's function **source text** on the node struct, and later runs:

```js
(async () => JSON.stringify(await ((<fnSource>))(prev)))()
```

in a **fresh sandbox runtime**.

At registration time the body executes inside the original ES module, so it can close over module-scope bindings (`shq`, `loadTool`, …). At execution time the only scope is the fresh sandbox, which is populated with **engine globals only**. The module scope is gone.

```
registration (module scope)          re-evaluation (fresh sandbox)
┌───────────────────────────┐        ┌───────────────────────────┐
│ function shq(...) {...}   │        │ engine globals from .d.ts │
│ node("quote", (prev)=>{   │  ───▶  │ shq?          ← MISSING   │
│   ... shq(prev) ...       │        │ node("quote", (prev)=>{   │
│ })                        │        │   ... shq(prev) ...       │
└───────────────────────────┘        └───────────────────────────┘
```

Key facts that make this hard to catch:

- A whole-file `tsc` **passes**, because `shq` resolves in the original module.
- The failure is a **runtime** `ReferenceError`, so static checking misses it.
- The wrapper is invoked in an `await` chain, so the throw can be swallowed and the pipeline can still exit `0`.
- One affected helper had been committed 11 days earlier and had **never been exercised** by the code path that runs it — latent, not crashing.

**Rule:** module scope exists for *top-level registration code only*. It never exists for the re-evaluated body. A serialized body must be **self-contained**.

A second, subtler consequence: cached/stateful helpers (`let toolCache`) cannot survive serialization at all, because their state lives outside the body.

## 2. Detection gate (the fix that actually works)

Add `src/typescript/coding_hermes_free_identifiers_test.go`.

It type-checks each captured body **standalone** against the ambient engine `.d.ts`. Engine globals resolve from the `.d.ts`; module-scope helpers do not, so an unresolved name (`TS2304` / `TS2552`, *"Cannot find name"*) is exactly the dangling reference. Other diagnostic codes are ignored — standalone checking produces unrelated artifacts (e.g. generic-parameter narrowing quirks) that false-positive correct bodies.

**Cost control:** extract all bodies of a file once and run **one `tsc` invocation per file**, not per body (~0.32 s/file vs ~1.2 s/body).

```go
// coding_hermes_free_identifiers_test.go
package typescript

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strconv"
	"strings"
	"testing"
)

func repoRoot(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot resolve caller path")
	}
	root := filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
	if _, err := os.Stat(filepath.Join(root, "go.mod")); err != nil {
		t.Fatalf("repo root %q has no go.mod: %v", root, err)
	}
	return root
}

// extractBodyArgs returns the second argument (the callback source) of every
// top-level node(...) call found in src. If the engine already exposes captured
// bodies (the node struct's stored fnSource), feed those in instead.
func extractBodyArgs(src string) []string {
	var bodies []string
	for i := 0; i+5 <= len(src); i++ {
		if src[i:i+5] != "node(" {
			continue
		}
		if i > 0 && isIdentChar(src[i-1]) {
			continue
		}
		args, ok := splitArgs(src, i+4) // src[i+4] == '('
		if !ok || len(args) < 2 {
			continue
		}
		bodies = append(bodies, strings.TrimSpace(args[1]))
	}
	return bodies
}

func isIdentChar(b byte) bool {
	return b == '_' || b == '$' || (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9')
}

// splitArgs parses a balanced parenthesized argument list, understanding
// (), [], {}, string/template literals, and line/block comments.
func splitArgs(s string, openIdx int) ([]string, bool) {
	if openIdx >= len(s) || s[openIdx] != '(' {
		return nil, false
	}
	var args []string
	start := openIdx + 1
	depth := 0
	for i := openIdx; i < len(s); i++ {
		c := s[i]
		switch c {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			depth--
			if depth == 0 && c == ')' {
				args = append(args, s[start:i])
				return args, true
			}
		case ',':
			if depth == 1 {
				args = append(args, s[start:i])
				start = i + 1
			}
		case '\'', '"', '`':
			i = skipString(s, i)
		case '/':
			if i+1 < len(s) && s[i+1] == '/' {
				if nl := strings.IndexByte(s[i:], '\n'); nl >= 0 {
					i += nl
				} else {
					i = len(s)
				}
			} else if i+1 < len(s) && s[i+1] == '*' {
				if end := strings.Index(s[i+2:], "*/"); end >= 0 {
					i += 2 + end + 1
				} else {
					i = len(s)
				}
			}
		}
	}
	return nil, false
}

func skipString(s string, i int) int {
	q := s[i]
	for j := i + 1; j < len(s); j++ {
		if s[j] == '\\' {
			j++
			continue
		}
		if s[j] == q {
			return j
		}
	}
	return len(s)
}

var diagRe = regexp.MustCompile(`^(.+?)\((\d+),(\d+)\): error TS(\d+): (.*)$`)
var diagRe2 = regexp.MustCompile(`^(.+?):(\d+):(\d+)[ :]+error TS(\d+): (.*)$`)

func TestFreeIdentifiers(t *testing.T) {
	root := repoRoot(t)
	tsc := filepath.Join(root, "node_modules", ".bin", "tsc")
	if _, err := os.Stat(tsc); err != nil {
		t.Fatalf("tsc not found at %s (run npm install): %v", tsc, err)
	}
	ambient := filepath.Join(root, "ambient.d.ts")

	files, err := filepath.Glob(filepath.Join(root, "examples", "*.ts"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 {
		t.Fatalf("no example files found under %s", filepath.Join(root, "examples"))
	}
	if only := os.Getenv("GATE_FILE"); only != "" {
		files = []string{only}
	}

	for _, file := range files {
		file := file
		t.Run(filepath.Base(file), func(t *testing.T) {
			src, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			bodies := extractBodyArgs(string(src))
			if len(bodies) == 0 {
				t.Skip("no node(...) registrations")
			}

			work, err := os.MkdirTemp("", "free-ident-*")
			if err != nil {
				t.Fatal(err)
			}
			defer os.RemoveAll(work)

			// One body per synthetic file, but a single tsc invocation per source file.
			args := []string{"--noEmit", "--strict", "--target", "ES2020", "--skipLibCheck"}
			for i, body := range bodies {
				name := fmt.Sprintf("body_%s_%d.ts", strings.TrimSuffix(filepath.Base(file), ".ts"), i)
				path := filepath.Join(work, name)
				content := "export const __registered_body = " + body + ";\n"
				if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
					t.Fatal(err)
				}
				args = append(args, path)
			}
			args = append(args, ambient)

			cmd := exec.Command(tsc, args...)
			cmd.Dir = root
			out, _ := cmd.CombinedOutput() // tsc exits non-zero on any diagnostic; parse it.

			type finding struct {
				Body  string `json:"body"`
				Ident string `json:"identifier"`
			}
			var findings []finding
			other := 0
			for _, line := range strings.Split(string(out), "\n") {
				m := diagRe.FindStringSubmatch(strings.TrimRight(line, "\r"))
				if m == nil {
					m = diagRe2.FindStringSubmatch(strings.TrimRight(line, "\r"))
				}
				if m == nil {
					continue
				}
				code, _ := strconv.Atoi(m[4])
				switch code {
				case 2304, 2552: // Cannot find name
					ident := ""
					if q := regexp.MustCompile(`Cannot find name '([^']+)'`).FindStringSubmatch(m[5]); q != nil {
						ident = q[1]
					}
					b := "?"
					if idx := regexp.MustCompile(`_(\d+)\.ts$`).FindStringSubmatch(m[1]); idx != nil {
						b = idx[1]
					}
					findings = append(findings, finding{Body: b, Ident: ident})
				default:
					other++ // deliberately ignored
				}
			}

			if len(findings) > 0 {
				j, _ := json.Marshal(findings)
				t.Fatalf("serialized callback bodies reference names that are not available in the fresh sandbox:\n"+
					"  file:    %s\n  details: %s\n"+
					"  fix: inline the helper into each body (and move any cache/state into the body) or make it an engine global",
					file, j)
			}
			t.Logf("%s: %d registered bodies clean (%d unrelated diagnostics ignored)",
				filepath.Base(file), len(bodies), other)
		})
	}
}
```

> If the engine's registration collection already yields the captured `fnSource` strings (the node struct field), replace `extractBodyArgs` with that list — the rest of the gate is unchanged and the batching guarantee still holds.

## 3. The fix: inline the helper into each body

For every flagged body, declare the helper **inside** the callback body and delete the now-dead module-scope declaration.

**Before** (`examples/write_node.ts`, pre-fix):

```ts
function shq(s: string): string {
  return "'" + s.replace(/'/g, "'\\''") + "'";
}

let toolCache: Record<string, string> | undefined = undefined;
function loadTool(name: string): string {
  if (!toolCache) {
    toolCache = {};
    for (const n of name.split(",")) {
      toolCache[n] = readFile("/tools/" + n);
    }
  }
  return toolCache[name];
}

node("quote", (prev: any) => {
  return { cmd: "echo " + shq(String(prev)) };
});

node("run", (prev: any) => {
  const bin = loadTool("grep");
  return { bin, args: String(prev) };
});
```

**After** (post-fix):

```ts
node("quote", (prev: any) => {
  const shq = (s: string): string => "'" + s.replace(/'/g, "'\\''") + "'";
  return { cmd: "echo " + shq(String(prev)) };
});

node("run", (prev: any) => {
  // Cache moves inside the body. The body runs once per invocation, so a fresh
  // cache each time is semantically identical. There is no const+lazy-init
  // idiom, so use an explicit `let loaded = false` flag.
  let loaded = false;
  let toolCache: Record<string, string> = {};
  const loadTool = (name: string): string => {
    if (!loaded) {
      loaded = true;
      for (const n of name.split(",")) {
        toolCache[n] = readFile("/tools/" + n);
      }
    }
    return toolCache[name];
  };

  const bin = loadTool("grep");
  return { bin, args: String(prev) };
});
```

The same pattern applies to flat-expression bodies:

```ts
// before: function fmt(x: number) { ... } at module scope
node("total", (prev: any) => {
  const fmt = (x: number): string => x.toFixed(2);
  return { total: fmt(Number(prev)) };
});
```

**Do not** paper over a flagged name by adding it to `ambient.d.ts` unless the engine actually injects it into the sandbox. That only silences the gate and re-creates the runtime `ReferenceError`.

### One-shot fix procedure

```bash
