go test ./src/typescript/ -run TestFreeIdentifiers -count=1 -v   # lists file+body+identifier
# for each flagged body: inline the helper, delete the module-scope declaration
go test ./src/typescript/ -run TestFreeIdentifiers -count=1 -v   # must pass
```

