### What the simulator asserts

For every seed and every node, with 2–6 nodes, backwards NTP steps, random partitions, ~30% packet drop with retransmission, ~20% duplication, and reordering:

1. **Exactly-once delivery** — `delivered.size === deliveries.length` and no duplicate ids in the delivery stream.
2. **Per-node emitted-timestamp monotonicity** — every `issue()`/`observe()` return is strictly greater than the node's previous return.
3. **Causal readiness** — at the moment any message is delivered, every id in its `deps` is already in that node's `delivered` set.
4. **Reliability + liveness** — every node eventually delivers every message and the buffer drains to zero (proves the clamp/global-minimum deadlock is gone).
5. **No duplicate message ids** were ever generated.

### Regression that motivated fix E

Before the `_flush` fix, seed 17 failed with:

```
seed 17: n1 dep n2:39 ts !< n1:37 ts
```

i.e. a drift-clamped dependency carried a larger packed timestamp than its dependent. The original "wait for the globally smallest buffered message" loop blocked on the smaller-ts, not-yet-ready dependent and never delivered the larger-ts, ready dependency. Switching to "smallest among the ready set" resolves it while preserving both causality and deterministic flush order.

### Usage

```js
const { CausalNode } = require('./causal');

const a = new CausalNode('a', { maxDrift: 60_000n });
const b = new CausalNode('b', { maxDrift: 60_000n });

const m1 = a.broadcast({ hello: 'world' });
a.receive(m1);            // self-delivery
b.receive(m1);            // delivers immediately (no deps)

const m2 = a.broadcast({ reply: 'hi' });   // deps = {m1}
a.receive(m2);
b.receive(m2);            // delivers after m2's deps are present

const { serialize, deserialize } = require('./hlc');
const wire = serialize(m1.ts);            // 16-char hex
console.log(wire, deserialize(wire) === m1.ts);
```

# Fix: DuckBrain literal-`null` credential sentinel (DAGGER-160)

**Files changed**
- `examples/coding-hermes/duckbrain-sync.ts` — hardened credential resolution
- `src/typescript/duckbrain_credentials_test.go` — source-level regression tests

---

## 1. Root cause

DuckBrain's auth registry is **hash-only**: after hardening, `auth.json` keeps `keyHash` but no longer stores the plaintext `key`. The plaintext token was split into a sidecar (`auth.tokens.json`, keyed by `keyHash`).

The sync example read credentials with optional-field/`jq`-style readers, so a **missing** field did not become missing — it became the literal string `"null"`:

```bash
jq -r '.key' auth.json          # prints "null" when .key is absent
```

The old fallback sites then did a naive truthiness/`-n` test:

```ts
// BUG: "null" is non-empty and truthy, so it passes the guard
const token = sidecar[entry.keyHash] || entry.key || entry.token || envValue || "";
if (!token) throw new Error("missing credential");   // never trips on "null"
```

`"null"` is non-empty, so it was sent as the `Authorization` header. DuckBrain correctly rejected it with a generic **HTTP 401**, which looked like a bad/expired credential instead of a missing one. The bug was duplicated at **every** credential fallback site, so a fix in one place would silently leave the other broken.

## 2. Fix — `examples/coding-hermes/duckbrain-sync.ts`

Replace every duplicated fallback with one resolver that (1) prefers the sidecar, (2) keeps the legacy `auth.json` plaintext fallback, (3) trims candidates, and (4) rejects blank and case-insensitive `null` sentinels.

```ts
// ===========================================================================
// DuckBrain credential resolution (hardened, DAGGER-160)
// auth.json is hash-only: keyHash is kept, plaintext key may be absent.
// Optional-field readers (jq '.key', `?? null`) fabricate the literal string
// "null", which is non-empty and passes naive truthiness/-n checks -> HTTP 401.
// ===========================================================================

export type CredentialCandidate = unknown;

/** Case-insensitive sentinels an optional-field reader can fabricate. */
export const NULL_CREDENTIAL_SENTINELS = ["null", "undefined", "nil"] as const;

/** Usable = a string that is non-blank after trimming and is not a null sentinel. */
export function isUsableCredential(value: CredentialCandidate): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (trimmed.length === 0) return false;
  return !NULL_CREDENTIAL_SENTINELS.includes(
    trimmed.toLowerCase() as (typeof NULL_CREDENTIAL_SENTINELS)[number],
  );
}

/** First usable (trimmed) credential, else "". */
export function firstUsableCredential(...candidates: CredentialCandidate[]): string {
  for (const candidate of candidates) {
    if (isUsableCredential(candidate)) return candidate.trim();
  }
  return "";
}

export interface DuckBrainAuthEntry {
  id?: string;
  name?: string;
  keyHash?: string;
  key?: string;    // legacy plaintext (may be absent after hardening)
  token?: string;  // alternate legacy plaintext
}
export interface DuckBrainAuthRegistry {
  entries?: DuckBrainAuthEntry[];
  keys?: DuckBrainAuthEntry[];
}

/**
 * Precedence: plaintext sidecar (matched by keyHash) -> legacy auth.json
 * plaintext -> explicit env override. Every raw value goes through the guard.
 */
export function resolveDuckBrainCredential(
  registry: DuckBrainAuthRegistry,
  sidecar: Record<string, string>,
  envValue: CredentialCandidate,
  entryId: string,
): string {
  const entries = registry.entries ?? registry.keys ?? [];
  const entry =
    entries.find((c) => c.id === entryId || c.name === entryId) ?? {};
  const sidecarToken = entry.keyHash ? sidecar[entry.keyHash] : undefined;
  return firstUsableCredential(sidecarToken, entry.key, entry.token, envValue);
}
```

Both previously duplicated fallback sites now delegate to the resolver (this is what makes the fix hold *at every site*):

```ts
export function duckBrainSyncToken(runtime, registry, sidecar) {
  return resolveDuckBrainCredential(
    registry, sidecar, runtime.env("DEEPSEEK_DUCKBRAIN_SYNC_API_KEY"), "sync");
}

export function duckBrainQueryToken(runtime, registry, sidecar) {
  return resolveDuckBrainCredential(
    registry, sidecar, runtime.env("DEEPSEEK_PAYG_DUCKBRAIN_KEY"), "query");
}
```

**Defense in depth for any shell reader** — never emit the sentinel in the first place:

```bash
# reject absent/null/empty at the source
jq -r '.key // empty | select(. != "null")' auth.json
```

## 3. Regression tests — `src/typescript/duckbrain_credentials_test.go`

Source-level tests, so a *future duplicate* fallback site is caught even if it is never executed. Full file:

```go
package typescript

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const duckbrainSyncExampleRel = "examples/coding-hermes/duckbrain-sync.ts"

func duckbrainTestRepoRoot(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd: %v", err)
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, duckbrainSyncExampleRel)); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatalf("could not locate %s from %s", duckbrainSyncExampleRel, dir)
		}
		dir = parent
	}
}

func readDuckBrainSync(t *testing.T) string {
	t.Helper()
	path := filepath.Join(duckbrainTestRepoRoot(t), duckbrainSyncExampleRel)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return string(raw)
}

// Rejection contract: missing (non-string), blank, and literal-null -> rejected.
func TestDuckBrainCredentialGuardRejectsSentinel(t *testing.T) {
	src := readDuckBrainSync(t)
	required := []struct{ name, need string }{
		{"guard function", "function isUsableCredential"},
		{"trims candidates", ".trim()"},
		{"case-insensitive compare", ".toLowerCase()"},
		{"literal-null sentinel", `"null"`},
		{"undefined sentinel", `"undefined"`},
		{"nil sentinel", `"nil"`},
		{"blank rejection", "trimmed.length === 0"},
		{"non-string rejection", `typeof value !== "string"`},
		{"single hardened entrypoint", "function firstUsableCredential"},
		{"trimmed return", "candidate.trim()"},
	}
	for _, r := range required {
		if !strings.Contains(src, r.need) {
			t.Errorf("missing %s: duckbrain-sync.ts must contain %q", r.name, r.need)
		}
	}
}

// Sidecar precedence: sidecar (by keyHash) -> legacy auth.json plaintext -> env.
func TestDuckBrainSidecarPrecedesLegacyFallback(t *testing.T) {
	src := readDuckBrainSync(t)
	resolver := duckbrainFunctionBody(t, src, "resolveDuckBrainCredential")
	call := duckbrainLastCall(t, resolver, "firstUsableCredential")

	last := -1
	for _, token := range []string{"sidecarToken", "entry.key", "entry.token", "envValue"} {
		idx := strings.Index(call, token)
		if idx < 0 {
			t.Fatalf("resolver must pass %q to firstUsableCredential; body:\n%s", token, call)
		}
		if idx <= last {
			t.Fatalf("precedence wrong: %q must come after the previous candidate:\n%s", token, call)
		}
		last = idx
	}
	if !strings.Contains(resolver, "sidecar[entry.keyHash]") {
		t.Errorf("sidecar lookup must be keyed by entry.keyHash; body:\n%s", resolver)
	}
}

// Every fallback site uses the hardened resolver; no naive ||/?? checks remain.
func TestDuckBrainEveryFallbackSiteUsesResolver(t *testing.T) {
	src := readDuckBrainSync(t)
	if got, want := strings.Count(src, "resolveDuckBrainCredential("), 3; got != want {
		t.Errorf("expected %d occurrences (definition + 2 fallback sites), got %d", want, got)
	}
	for i, line := range strings.Split(src, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "//") || strings.HasPrefix(trimmed, "*") {
			continue
		}
		if strings.Contains(line, "entry.key") || strings.Contains(line, "entry.token") || strings.Contains(line, "sidecarToken") {
			if !strings.Contains(line, "firstUsableCredential") && !strings.Contains(line, "keyHash") {
				t.Errorf("line %d bypasses the hardened helper: %q", i+1, line)
			}
		}
		if (strings.Contains(line, "entry.key") || strings.Contains(line, "sidecar[")) &&
			(strings.Contains(line, "||") || strings.Contains(line, "??") || strings.Contains(line, "-n")) {
			t.Errorf("line %d uses a naive fallback/emptiness check: %q", i+1, line)
		}
	}
}

func duckbrainFunctionBody(t *testing.T, src, name string) string {
	t.Helper()
	start := strings.Index(src, "function "+name)
	if start < 0 {
		t.Fatalf("function %s not found", name)
	}
	rest := src[start:]
	end := strings.Index(rest, "\n}\n")
	if end < 0 {
		t.Fatalf("could not find end of function %s", name)
	}
	return rest[:end+3]
}

func duckbrainLastCall(t *testing.T, src, callee string) string {
	t.Helper()
	idx := strings.LastIndex(src, callee+"(")
	if idx < 0 {
		t.Fatalf("call to %s not found", callee)
	}
	rest := src[idx:]
	end := strings.Index(rest, ");")
	if end < 0 {
		t.Fatalf("could not find end of %s call", callee)
	}
	return rest[:end+2]
}
```

