}

func (r *Runner) child(runID string) *Runner {
    return &Runner{RunID: runID, Engine: r.Engine, Store: r.Store}
}

func iterationRunID(parentRunID, foreachStep, itemKey string) string {
    return fmt.Sprintf("%s@%s@%s", parentRunID, foreachStep, itemKey)
}

func (r *Runner) runStep(localIndex int, s Step) Result {
    engineRunID := fmt.Sprintf("%s@%d", r.RunID, localIndex)
    res := r.Engine.Run(engineRunID, s.Name)
    r.Store.Record(engineRunID, s.Name, res)
    return res
}

func (r *Runner) Run(p Pipeline) []Result {
    out := make([]Result, 0, len(p.Steps))
    for i, s := range p.Steps {
        if s.ForEach != nil {
            out = append(out, r.runForEachScoped(i+1, s)...)
            continue
        }
        out = append(out, r.runStep(i+1, s))
    }
    return out
}

func (r *Runner) runForEachScoped(index int, s Step) []Result {
    var out []Result
    for _, item := range s.ForEach.Items {
        scope := iterationRunID(r.RunID, s.Name, item.Key)
        child := r.child(scope) // dedicated child Runner
        for j, local := range s.ForEach.Template {
            out = append(out, child.runStep(j+1, local))
        }
    }
    return out
}

func (r *Runner) RunUnscoped(p Pipeline) []Result {
    out := make([]Result, 0, len(p.Steps))
    for i, s := range p.Steps {
        if s.ForEach != nil {
            out = append(out, r.runForEachUnscoped(s)...)
            continue
        }
        out = append(out, r.runStep(i+1, s))
    }
    return out
}

func (r *Runner) runForEachUnscoped(s Step) []Result {
    var out []Result
    for _, item := range s.ForEach.Items {
        _ = item
        for j, local := range s.ForEach.Template {
            out = append(out, r.runStep(j+1, local)) // BUG: parent RunID, step 1
        }
    }
    return out
}
