```

`scripts/health-check.js`:

```js
#!/usr/bin/env node
'use strict';

const http = require('http');

const args = process.argv.slice(2);
function opt(name, dflt) {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : dflt;
}
const port = Number(opt('--port', '3000'));
const host = opt('--url', `http://127.0.0.1:${port}/health`);
const timeoutMs = Number(opt('--timeout-ms', '5000'));

const req = http.get(host, { timeout: timeoutMs }, (res) => {
  res.resume();
  // 200 = healthy; 503 = degraded but ALIVE (dependency-health contract).
  if (res.statusCode === 200 || res.statusCode === 503) {
    console.log(`health: alive status=${res.statusCode}`);
    process.exit(0);
  }
  console.error(`health: DARK status=${res.statusCode}`);
  process.exit(1);
});

req.on('timeout', () => { req.destroy(new Error(`timeout after ${timeoutMs}ms`)); });
req.on('error', (e) => {
  console.error(`health: DARK connection failure: ${e.message}`);
  process.exit(1);
});
```

