## 2. The fix

### 2.1 Accountant (`lib/flow-control.js`)

The critical fix — a connection/stream branch instead of treating `this` as a stream:

```js
onWindowUpdate(streamId, increment) {
  if (!Number.isInteger(increment) || increment < 0 || increment > MAX_WINDOW) {
    throw new FlowControlError(`invalid WINDOW_UPDATE increment ${increment}`);
  }
  if (increment === 0) {
    if (this.rejectZeroIncrement) throw new FlowControlError('WINDOW_UPDATE with increment 0');
    return false; // tolerant no-op
  }

  let target;
  let isConnection = false;
  if (streamId === 0) {
    isConnection = true;
    target = this;
  } else {
    target = this.streams.get(streamId);
    if (!target) throw new FlowControlError(`WINDOW_UPDATE for unknown stream ${streamId}`);
  }

  const current = isConnection ? this.connectionWindow : target.window; // <-- the fix
  if (current + increment > MAX_WINDOW) {
    throw new FlowControlError(
      `window overflow on ${isConnection ? 'connection' : `stream ${streamId}`}: ` +
      `${current} + ${increment} > ${MAX_WINDOW}`
    );
  }
  if (isConnection) this.connectionWindow += increment;
  else target.window += increment;
  return true;
}
```

Retroactive SETTINGS delta (negative windows allowed):

```js
onSettingsInitialWindowSize(newSize) {
  if (!Number.isInteger(newSize) || newSize < 0 || newSize > MAX_WINDOW) {
    throw new FlowControlError(`invalid SETTINGS_INITIAL_WINDOW_SIZE ${newSize}`);
  }
  const delta = newSize - this.initialWindowSize;
  this.initialWindowSize = newSize;
  for (const s of this.streams.values()) s.window += delta; // may go negative; legal
  return delta;
}
```

Guarded debit + clamped availability:

```js
available(streamId) {
  const s = this.streams.get(streamId);
  if (!s || s.closed) return 0;
  return Math.max(0, Math.min(this.connectionWindow, s.window));
}

consume(streamId, bytes) {
  const s = this.streams.get(streamId);
  if (!s) throw new FlowControlError(`consume for unknown stream ${streamId}`);
  if (bytes > this.connectionWindow) throw new FlowControlError('connection flow-control window exceeded');
  if (bytes > s.window) throw new FlowControlError(`stream ${streamId} flow-control window exceeded`);
  this.connectionWindow -= bytes;
  s.window -= bytes;
  s.bytesEmitted += bytes;
  return bytes;
}
```

### 2.2 Eligibility-aware weighted round-robin scheduler

The key line is `if (available <= 0) break;` inside the per-stream inner loop: it breaks **that stream's turn**, not the whole pump. The outer fairness round keeps visiting remaining streams. The outer `while (progress)` repeats only when a frame was emitted — the forward-progress guarantee and a termination proof (windows only shrink during a pump).

```js
pump(opts = {}) {
  const maxFrames = opts.maxFrames ?? Infinity;
  const frames = [];
  let progress = true;

  while (progress && frames.length < maxFrames) {
    progress = false;
    for (const s of this.fc.streams.values()) {     // one fairness round
      if (s.closed) continue;
      let budget = s.weight * this.quantum;          // weight controls share per round
      while (budget > 0 && s.pending > 0) {
        const available = this.fc.available(s.id);
        if (available <= 0) break;                   // skip blocked stream, don't stall
        const length = Math.min(budget, s.pending, available, this.maxFrameSize);
        if (length <= 0) break;
        this.fc.consume(s.id, length);               // guarded debit
        s.pending -= length;
        s.framesEmitted += 1;
        budget -= length;
        frames.push({ streamId: s.id, length, connWindow: this.fc.connectionWindow, streamWindow: s.window });
        progress = true;
        if (frames.length >= maxFrames) return frames;
      }
    }
  }
  return frames;
}
```

Properties: forward progress; no starvation; flat-RR fallback (`1,2,3,1,2,3…`); coalescing; deterministic (insertion-ordered `Map`, no randomness).

