  const healthyFn = vi.fn(async () => {
    if (healthy instanceof Error) throw healthy;
    return healthy;
  });
  const embedFn = vi.fn(async () => {
    if (embed instanceof Error) throw embed;
    if (typeof embed === 'function') return embed();
