## 2. Exact fix (three-file commit scope)

### File 1 — `packages/shared/src/ndjson/event-log.ts`

```ts
import { appendFileSync, readFileSync, existsSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

export interface NdjsonEvent { type: string; [k: string]: unknown }

// FIX: no fixed, process-wide path. Each process/run gets its own directory,
// and tests override it per file via EDUOS_NDJSON_PATH.
let logPath: string | undefined;

function freshPath(): string {
  return join(mkdtempSync(join(tmpdir(), 'eduos-ndjson-')), 'events.ndjson');
}

function resolvePath(): string {
  logPath ??= process.env.EDUOS_NDJSON_PATH ?? freshPath();
  return logPath;
}

export function getLogPath(): string {
  return resolvePath();
}

export function resetEventLog(nextPath?: string): void {
  logPath = nextPath ?? process.env.EDUOS_NDJSON_PATH ?? freshPath();
}

export function appendEvent(event: NdjsonEvent): void {
  // Single O_APPEND write: no long-lived WriteStream to flush across files.
  appendFileSync(resolvePath(), JSON.stringify(event) + '\n', 'utf8');
}

export function readEvents(): NdjsonEvent[] {
  const p = resolvePath();
  if (!existsSync(p)) return [];
  return readFileSync(p, 'utf8')
    .split('\n')
    .filter((l) => l.length > 0)
    .map((l) => JSON.parse(l)); // defense-in-depth: see note below
}
```

> Defense-in-depth (optional, same file): ignore only the last unterminated line, e.g.
> `.filter((l, i, a) => l.length > 0 && (i < a.length - 1 || l.endsWith('}')))`.
> Do this in addition to, never instead of, the isolation fix.

### File 2 (new) — `test-setup/ndjson-isolation.ts`

```ts
