# DAGGER-117 — Replace the agent tool loop on the DuckBrain write boundary with deterministic sandbox fetch calls

**Task:** `DAGGER-117` · **Repo:** `Hermes-DAGger/hermes-dagger` · **Commit:** `0ab7e001321bcdea60e9f3532de625dafa9e25fd` · **Verdict:** `ff8fd17c PASS`

## Symptom

Per-tick `event` and `status` records were not persisted to DuckBrain for roughly two days, producing a measured gap in the namespace. The foreman node threw `agent loop reached max_turns (20) with no final response; DuckBrain POST never occurred`, so the downstream report step was skipped and the failure was effectively silent at the record level.

Stack at time of failure:

```
duckbrain_write
  -> agent(writePrompt, { max_turns: 20 })
     -> direct_llm.go turn exhaustion
        -> node throw
           -> downstream report skipped
```

## Root-cause analysis

The `duckbrain_write` node — a **mechanical persistence boundary** — was implemented as an LLM tool loop (`agent(writePrompt, {max_turns:20})`). It therefore depended on a non-deterministic, provider-mediated path to perform two fixed HTTP writes:

1. Provider/transport errors, malformed tool calls, or simple turn exhaustion could occur **before** the first HTTP request was ever issued.
2. When `max_turns` was reached there was no final response and the node threw, so the writes silently never happened.
3. Because the node is a write boundary, the loss was recorded only as an absent namespace entry — a gap — not as a loud, attributable failure.

The fix is structural: a mechanical write must not traverse an LLM. Replace the loop with **exactly four deterministic HTTP operations** executed through the sandbox's injected synchronous `fetch` bridge, and fail loudly on any deviation.

## Exact fix

### 1. Add the deterministic writer (`examples/coding-hermes/foreman.ts`)

Replace the body that called `agent(...)` with the function below. It performs exactly two authenticated `POST /api/memories?namespace=<encoded>` calls, validates a strict 2xx + JSON envelope + non-empty write id for each, then two exact-key `GET` read-backs, and only sets `written = true` after all four pass. Dry-run performs **zero** network I/O.

```ts
export interface DuckBrainWriteInput {
  namespace: string;
  eventKey: string;
  statusKey: string;
  event: unknown;
  status: unknown;
  dryRun?: boolean;
}

export interface DuckBrainWriteOutput {
  written: boolean;
  namespace: string;
  eventKey: string;
  statusKey: string;
  eventId?: string;
  statusId?: string;
}

export interface HttpResponse {
  ok?: boolean;
  status?: number;
  body?: string;
  text?: () => string;
}

export type SyncFetch = (
  url: string,
  init: { method: string; headers: Record<string, string>; body?: string },
) => HttpResponse;

const WRITE_ERROR = "duckbrain_write";

function httpStatus(res: HttpResponse): number {
  return typeof res.status === "number" ? res.status : 0;
}

function is2xx(res: HttpResponse): boolean {
  const status = httpStatus(res);
  if (typeof res.ok === "boolean") return res.ok && status >= 200 && status < 300;
  return status >= 200 && status < 300;
}

function readBody(res: HttpResponse): string {
  if (typeof res.text === "function") return String(res.text());
  return res.body === undefined ? "" : String(res.body);
}

function parseEnvelope(res: HttpResponse, op: string, key: string): Record<string, unknown> {
  const status = httpStatus(res);
  let text: string;
  try {
    text = readBody(res);
  } catch (e) {
    throw new Error(
      `${WRITE_ERROR}: ${op} key=${JSON.stringify(key)} unreadable body status=${status}: ${String(e)}`,
    );
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new Error(
      `${WRITE_ERROR}: ${op} key=${JSON.stringify(key)} malformed JSON envelope status=${status}`,
    );
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error(
      `${WRITE_ERROR}: ${op} key=${JSON.stringify(key)} malformed JSON envelope status=${status}`,
    );
  }
  return parsed as Record<string, unknown>;
}

function extractWriteId(env: Record<string, unknown>): string | undefined {
  const id = env.id ?? env.writeId ?? env.write_id;
  return typeof id === "string" && id.length > 0 ? id : undefined;
}

function extractReadBackKey(env: Record<string, unknown>): unknown {
  if (typeof env.key === "string") return env.key;
  const memory = env.memory;
  if (memory !== null && typeof memory === "object" && !Array.isArray(memory)) {
    return (memory as Record<string, unknown>).key;
  }
  return undefined;
}

interface RecordSpec {
  label: "event" | "status";
  key: string;
  value: unknown;
}

export function duckbrainWrite(
  fetchFn: SyncFetch,
  token: string,
  input: DuckBrainWriteInput,
): DuckBrainWriteOutput {
  const namespace = String(input.namespace);
  const eventKey = String(input.eventKey);
  const statusKey = String(input.statusKey);

  const out: DuckBrainWriteOutput = { written: false, namespace, eventKey, statusKey };

  // Dry-run must remain completely side-effect free: never touch the network.
  if (input.dryRun === true) return out;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${token}`,
  };
  const nsQuery = encodeURIComponent(namespace);
  const records: RecordSpec[] = [
    { label: "event", key: eventKey, value: input.event },
    { label: "status", key: statusKey, value: input.status },
  ];

  // Phase 1 - exactly two authenticated POSTs, each must return a write id.
  for (const rec of records) {
    const url = `/api/memories?namespace=${nsQuery}`;
    let res: HttpResponse;
    try {
      res = fetchFn(url, {
        method: "POST",
        headers,
        body: JSON.stringify({ key: rec.key, value: rec.value }),
      });
    } catch (e) {
      throw new Error(
        `${WRITE_ERROR}: POST ${rec.label} key=${JSON.stringify(rec.key)} transport error: ${String(e)}`,
      );
    }
    const status = httpStatus(res);
    if (!is2xx(res)) {
      throw new Error(
        `${WRITE_ERROR}: POST ${rec.label} key=${JSON.stringify(rec.key)} non-2xx status=${status}`,
      );
    }
    const envelope = parseEnvelope(res, `POST ${rec.label}`, rec.key);
    const id = extractWriteId(envelope);
    if (id === undefined) {
      throw new Error(
        `${WRITE_ERROR}: POST ${rec.label} key=${JSON.stringify(rec.key)} missing write id status=${status}`,
      );
    }
    if (rec.label === "event") out.eventId = id;
    else out.statusId = id;
  }

  // Phase 2 - exactly two exact-key GET read-backs.
  for (const rec of records) {
    const url = `/api/memories?namespace=${nsQuery}&key=${encodeURIComponent(rec.key)}`;
    let res: HttpResponse;
    try {
      res = fetchFn(url, { method: "GET", headers });
    } catch (e) {
      throw new Error(
        `${WRITE_ERROR}: GET ${rec.label} key=${JSON.stringify(rec.key)} transport error: ${String(e)}`,
      );
    }
    const status = httpStatus(res);
    if (!is2xx(res)) {
      throw new Error(
        `${WRITE_ERROR}: GET ${rec.label} key=${JSON.stringify(rec.key)} non-2xx status=${status}`,
      );
    }
    const envelope = parseEnvelope(res, `GET ${rec.label}`, rec.key);
    if (extractReadBackKey(envelope) !== rec.key) {
      throw new Error(
        `${WRITE_ERROR}: GET ${rec.label} key=${JSON.stringify(rec.key)} missing read-back key status=${status}`,
      );
    }
  }

  out.written = true;
  return out;
}
```

### 2. Wire the node (preserve the output contract)

```ts
