  it('fixed: every helper is an explicit function expression', () => {
    for (const fn of Object.values(fixedHelpers)) {
      expect(fn.toString().trimStart().startsWith('function')).toBe(true);
    }
  });

  it('fixed: sibling calls resolve through `this` inside the iframe', async () => {
    const results = await runInSrcDoc(
      `${serializeFixed()}\n[helpers.greet('ada'), helpers.withRetries('ada')]`,
    );
    expect(results).toEqual(['demo:ada', 'demo:ada (max 3)']);
