// toolExecutorModel returns (provider, model, error).
func toolExecutorModel(tool string, cfg Config) (GatewayProvider, string, error) {
	if tool == "" {
		return "", "", routeErr("tool name is required")
	}
	if cfg.ToolProvider == "" {
		return "", "", routeErr("tool %q: no explicit provider configured", tool)
	}
	if cfg.ToolModel == "" {
		return "", "", routeErr("tool %q: no explicit model configured", tool)
	}
	r := GatewayRoute{Provider: cfg.ToolProvider, Model: cfg.ToolModel}
	if err := r.Validate(); err != nil {
