});

console.log('\n== Positive proofs (signed zone) ==');
const zone = buildZone();

test('secure NXDOMAIN accepted', () => {
  const r = expectStatus(zone, { qname: 'nope.example', qtype: V.TYPE.A }, 'secure-nxdomain', 'NXDOMAIN');
  assert.strictEqual(r.closestEncloser, 'example');
  assert.strictEqual(r.nextCloser, 'nope.example');
});

test('secure NODATA accepted for existing name', () => {
