console.log('\n== Adversarial forgeries ==');
test('omitted next-closer NSEC3 -> NSEC3_MISSING_NEXT_CLOSER', () => {
  const qname = 'nope.example';
  const h = V.nsec3Hash(qname, zone.nsec3param.salt, zone.nsec3param.iterations);
  const cover = zone.nsec3Rrsets.find((rr) => V.hashCovers(V.nsec3RdataToRecord(rr), h));
  assert.ok(cover, 'test setup: expected a covering record');
