Pin the whole decision surface with the six-cell table:

```go
func TestDuckBrainEnrichDegradationRetryPrecedenceTable(t *testing.T) {
	valid := `{"v":1,"changed":"one line","health":"GREEN"}`
	cases := []struct {
		name         string
		first, retry agentStubReply
		wantOK       bool
		wantReason   string // substring; "" means ok
	}{
		{"throw/throw",     {Throw: "first"},  {Throw: "second"}, false, "first"},
		{"throw/invalid",   {Throw: "first"},  {Text: "prose"},   false, "parse"},
		{"throw/valid",     {Throw: "first"},  {Text: valid},     true,  ""},
		{"invalid/throw",   {Text: "prose"},   {Throw: "second"}, false, "second"},
		{"invalid/invalid", {Text: "prose"},   {Text: "prose"},   false, "parse"},
		{"invalid/valid",   {Text: "prose"},   {Text: valid},     true,  ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := runDuckBrainEnrichNode(t, []agentStubReply{tc.first, tc.retry})
			if res.InsightsOK != tc.wantOK {
				t.Fatalf("insights_ok = %v, want %v (reason=%q)", res.InsightsOK, tc.wantOK, res.Reason)
			}
			if tc.wantReason != "" && !strings.Contains(res.Reason, tc.wantReason) {
				t.Fatalf("reason = %q, want substring %q", res.Reason, tc.wantReason)
			}
			if res.AgentCalls != 2 {
				t.Fatalf("agent calls = %d, want 2", res.AgentCalls)
			}
		})
	}
}
