  limit: parseLimit(req.query.limit),
  offset: parseOffset(req.query.offset),   // ← validated (400 on negative/NaN)
  // …
};

const result = await recallTool({
  keyPrefix: params.prefix,
  limit: params.limit! > 0 ? params.limit! + 1 : 0, // keep the hasMore probe
  offset: params.offset || 0,                       // ← forwarded into the query
  // …
});
```

```ts
const hasMore = params.limit! > 0 && filteredMemories.length > params.limit!;
if (hasMore) filteredMemories.pop();

const offset = params.offset || 0;

const response: MemoryListResponse = {
  // Defensive slice only — rows are already [offset, offset+limit).
  items: filteredMemories.slice(0, params.limit!),
  total: result.total ?? filteredMemories.length,
  offset,
  limit: params.limit!,
  hasMore,
  nextOffset: hasMore ? offset + params.limit! : null,
};
```

### 2.3 Recall tool — `src/mcp/tools/recall.ts`

```ts
offset: z.number().int().min(0).optional().default(0)
  .describe("Row offset for paging (non-negative integer)"),

function pageWindow<T>(items: T[], offset: number, limit: number): T[] {
  return items.slice(offset, offset + limit);
}
```

- **List path:** forward `offset: validated.offset` into `queryMemories` (SQL window).
- **Keyword path:** `const keywordLimit = Math.min(validated.offset + validated.limit, MAX_CANDIDATES);` fetch through the page end, then `pageWindow(keywordResult.memories, offset, limit)`.
- **Hybrid / semantic paths:** replace every `ranked.slice(0, limit)` with `pageWindow(ranked, validated.offset, validated.limit)`.
- **As-of path:** pass `offset: validated.offset`.

Ranked paths page over a bounded candidate pool (`2 × FUSION_TOP_K`, `MAX_CANDIDATES`); an offset past the pool deliberately degrades to an empty page rather than returning unordered rows.

### 2.4 As-of in-memory mirror — `src/git/asof.ts`

```ts
export interface AsOfFilters {
  limit?: number;
  offset?: number;   // rows [offset, offset+limit) of the newest-first ordering
}

const offset = filters.offset ?? 0;
const memories =
  filters.limit !== undefined
    ? sorted.slice(offset, offset + filters.limit)
    : sorted.slice(offset);
return { memories, total: sorted.length };
```

