const key = await tool("read_file", { path: "/secure/duckbrain.token" });
```

### 4. Optional Go-side guard (if you own the writer service)

Mirror Go's own rule so a poisoned header fails with a precise message before `net/http` turns it into a 502:

```go
// validHeaderValue mirrors internal/httpguts.ValidHeaderFieldValue:
// HTAB is allowed; every other C0 control and DEL is not.
func validHeaderValue(v string) bool {
	for i := 0; i < len(v); i++ {
		b := v[i]
		if b == '\t' {
			continue
		}
		if b < 0x20 || b == 0x7f {
			return false
		}
	}
	return true
}

func duckbrainKey() (string, error) {
	k := os.Getenv("DUCKBRAIN_KEY")
	if k == "" {
		return "", errors.New("DUCKBRAIN_KEY is not set")
	}
	if !validHeaderValue(k) {
		return "", errors.New("DUCKBRAIN_KEY contains control bytes")
	}
	return k, nil
}
```

Also ensure the key is **redacted** everywhere it could be logged (`X-Api-Key: ***`), and keep it out of DAG node inputs/outputs, event logs, and checkpoints.

