	t0 := time.Unix(1_700_000_000, 0)
	c := NewCircuit(3, 300*time.Second)
	now := t0
	c.now = func() time.Time { return now }

	for i := 0; i < 3; i++ {
		c.recordFailure("api")
	}
	if c.Allow("api") {
		t.Fatal("expected circuit open after 3 failures")
	}

	now = t0.Add(301 * time.Second) // cooldown elapsed -> probe allowed
	if !c.Allow("api") {
		t.Fatal("expected probe to be allowed after cooldown")
	}

	c.recordFailure("api") // probe fails
	if c.Allow("api") {
		t.Fatal("circuit did not re-open after failed probe")
