type PostChatOptions = { omitStreamId?: boolean };

export function postChat(
  app: Express,
  body: { message: string; streamId?: string },
  { omitStreamId = false }: PostChatOptions = {},
) {
  const streamId = body.streamId ?? randomUUID();
  return request(app)
    .post('/api/chat')
    .set('Authorization', `Bearer ${testToken}`)   // match existing auth helper
    .send(omitStreamId ? { message: body.message } : { ...body, streamId });
}
```

Every existing suite that relied on the fallback now goes through this helper and is automatically fixed. Update direct call sites to use the helper (or add the uuid inline).

### 4. `apps/api/tests/evacuation/hold-seat-identifier.test.ts` — pass a pre-allocated uuid

```diff
-const res = await authenticatedPost('/api/chat', { message: 'hold-seat' });
+const streamId = randomUUID();
+const res = await authenticatedPost('/api/chat', { message: 'hold-seat', streamId });
+expect(res.body.streamId).toBe(streamId);
+expect(res.body.websocketTopic).toBe(`request:${streamId}`);
```

### 5. `apps/api/tests/chat/chat-streamid-required.test.ts` — new route-level suite

Assert on a **substring** of the serialized issues, never an exact validator message string (message wording differs across zod versions/locales).

