  ws.on('message', (raw) => frames.push(JSON.parse(raw.toString())));
  await opts.subscribe(sessionId);
  await opts.run(sessionId);

  // Wait well past the expected job duration without assuming a close.
  await new Promise((r) => setTimeout(r, 1500));
  ws.close();
  await server.close();
