// --- 2. minimal reproducing request ends in exactly that halt ------------

it('minimal request ends in exactly one halt frame at the expected count', async () => {
  const frames = await probeMissingField();
  const halts = frames.filter((f) => f.type === 'awaiting_input');
  expect(halts).toHaveLength(1);
  expect(frames).toHaveLength(2); // progress + single halt (count unchanged)
  expect(frames.at(-1)).toMatchObject({ terminal: true, type: 'awaiting_input' });
});

// --- 3. negative control: happy path is not over-marked ------------------

it('happy path emits no false terminal marker', async () => {
  const frames = await probeFullySpecified();
  expect(frames.some((f) => f.terminal === true)).toBe(false);
  expect(frames.every((f) => f.type !== 'awaiting_input')).toBe(true);
  expect(frames.at(-1)?.type).toBe('surface_complete'); // pre-existing completion
});

// --- 4. emit -> broadcast spread preserves terminal fields on the wire ----

it('terminal fields survive emit -> stream-manager broadcast to a raw client', async () => {
  const sm = new StreamManager();
  const app = createApp({ streamManager: sm });
  const http = app.listen(0);
  const { port } = http.address() as AddressInfo;

  const ws = new WebSocket(`ws://127.0.0.1:${port}/stream`);
  const received: any[] = [];
  await new Promise<void>((res) => ws.on('open', res));
  ws.on('message', (r) => received.push(JSON.parse(r.toString())));

  // Exercise the REAL emit path used by the halt branch.
  sm.broadcast('session-1', {
    phase: 'control',
    controlState: 'awaiting_clarification',
    type: 'awaiting_input',
    terminal: true,
    list: ['customerId'],
    resume: { method: 'POST', path: '/api/sessions/session-1/messages',
              body: { sessionId: 'session-1', message: '' } },
  });
  await new Promise((r) => setTimeout(r, 200));

  expect(received).toHaveLength(1);
  expect(received[0]).toMatchObject({
    type: 'awaiting_input',
    terminal: true,
    list: ['customerId'],
    resume: expect.objectContaining({ method: 'POST' }),
  });

  ws.close();
  await new Promise((r) => http.close(r));
});
```

