```bash
# 1. Reproduce the blocking behavior: rm alone fails while a gvfsd-fuse mount exists.
rm -rf /run/user/1002          # -> Device or resource busy

# 2. Lazy unmount clears it.
mount | awk '/\/run\/user\/1002/ {print $3}' | while read -r m; do umount -l "$m"; done
