# Fix: docs/api.md request example rejected by its own schema

**Problem class:** `documented-api-example-rejected-by-own-schema`
**Project:** heading — `POST /api/chat`
**Files:** `docs/api.md`, `packages/core/src/schemas.ts`, `apps/api/src/server.ts`

## Root cause

`docs/api.md` shipped a hand-written request body containing `"rankingLens": "preference_compliance"`, a value absent from `packages/core/src/schemas.ts`:

```ts
rankingLensSchema = z.enum([
  "client_fit", "earliest_arrival", "earliest_departure",
  "lowest_operational_risk", "direct_routing", "margin_within_compliant",
]);
```

The schema is the single source of truth, but nothing tied the doc to it. The enum is never printed where a reader compares it, and the prose reads as authoritative, so the drift was invisible by inspection. The documented body returned `400 INVALID_BODY` with `invalid_value` at `[structuredOverrides, rankingLens]`; the same body with `client_fit` returned `202`.

**Generalisable cause:** strict-schema APIs with hand-written example bodies drift silently. A one-line doc edit fixes the symptom; only a test coupling the doc to the exported schema prevents regression.

## The fix

### 1. Correct the doc

```diff
-    "rankingLens": "preference_compliance"
+    "rankingLens": "client_fit"
```

### 2. Add `tests/docsExamples.ts` — parse fenced JSON blocks with route/role context

```ts
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

export interface DocJsonBlock {
  raw: string;                 // verbatim text inside the fence
  value: unknown;              // parsed JSON
  heading: string | null;
  route: { method: string; path: string } | null;
  label: string | null;        // nearest non-empty line above the fence
  role: "request" | "response";
  line: number;
}

const ROUTE_RE = /\b(GET|POST|PUT|PATCH|DELETE)\s+(\/\S+)/;

export function extractJsonBlocks(markdown: string): DocJsonBlock[] {
  const lines = markdown.split(/\r?\n/);
  const blocks: DocJsonBlock[] = [];
  let currentHeading: string | null = null;
  let currentRoute: { method: string; path: string } | null = null;

  for (let i = 0; i < lines.length; i++) {
    const headingMatch = /^#{1,6}\s+(.*)$/.exec(lines[i]);
    if (headingMatch) {
      currentHeading = headingMatch[1].trim();
      const r = ROUTE_RE.exec(currentHeading);
      currentRoute = r ? { method: r[1], path: r[2] } : null;
      continue;
    }
    if (/^```json\s*$/.test(lines[i])) {
      const startLine = i + 1;
      const body: string[] = [];
      i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i])) body.push(lines[i++]);
      const raw = body.join("\n");
      let value: unknown;
      try { value = JSON.parse(raw); } catch { value = undefined; }

      let label: string | null = null;
      for (let j = startLine - 2; j >= 0; j--) {
        if (lines[j].trim() !== "") { label = lines[j].trim(); break; }
      }
      const role: "request" | "response" =
        /response|error|reply/i.test(label ?? "") ? "response" : "request";

      blocks.push({ raw, value, heading: currentHeading, route: currentRoute, label, role, line: startLine });
    }
  }
  return blocks;
}

export function extractDocumentedRankingLenses(markdown: string): string[] | null {
  const line = markdown.split(/\r?\n/).find((l) => /rankingLens[\s`]*values/i.test(l));
  if (!line) return null;
  const afterColon = line.slice(line.indexOf(":") + 1);
  const values = [...afterColon.matchAll(/`([^`]+)`/g)].map((m) => m[1]);
  return values.length > 0 ? values : null;
}

export const DOCS_API_MD = resolve(process.cwd(), "docs/api.md");
export function readApiDoc() { return readFileSync(DOCS_API_MD, "utf8"); }
```

