describe("docs/api.md request examples match the exported schema", () => {
  it("contains at least one POST /api/chat json example", () => {
    expect(chatRequestBlocks.length).toBeGreaterThan(0);
  });

  it("every example parses as valid JSON", () => {
    for (const b of chatRequestBlocks) expect(b.value, `docs/api.md:${b.line}`).toBeDefined();
  });

  it("every example validates against chatRequestSchema", () => {
    const failures: string[] = [];
    for (const b of chatRequestBlocks) {
      const parsed = chatRequestSchema.safeParse(b.value);
      if (!parsed.success) failures.push(`docs/api.md:${b.line} -> ${JSON.stringify(parsed.error.issues)}`);
    }
    expect(failures).toEqual([]);
  });

