    const documented = extractDocumentedRankingLenses(doc);
    expect(documented, "docs must document the rankingLens enum").not.toBeNull();
    expect(documented).toEqual([...rankingLensSchema.options]);
  });
});

describe("verbatim doc block is accepted by the live API", () => {
  let server: Server;
  let baseUrl: string;

  beforeAll(async () => {
    await new Promise<void>((resolve) => {
      server = createApp().listen(0, () => {
        const addr = server.address();
        const port = typeof addr === "object" && addr ? addr.port : 0;
        baseUrl = `http://127.0.0.1:${port}`;
        resolve();
      });
    });
  });
  afterAll(async () => {
    await new Promise<void>((res, rej) => server.close((e) => (e ? rej(e) : res())));
  });

  it("returns 202 for the exact fenced body", async () => {
    const block = chatRequestBlocks[0];
    expect(block).toBeDefined();
    const res = await fetch(`${baseUrl}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: block!.raw,
    });
    expect(res.status).toBe(202);
  });

  it("returns 400 INVALID_BODY for the old bad value (drift is observable)", async () => {
    const res = await fetch(`${baseUrl}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ message: "x", structuredOverrides: { rankingLens: "preference_compliance" } }),
    });
    expect(res.status).toBe(400);
    expect(((await res.json()) as { error: string }).error).toBe("INVALID_BODY");
