### 4.2 Spawn E2E of the **real** launcher — two-arm observer

The host may already own the expected port, so the test is valid in both worlds and must prove **our child** bound the port. The stub writes `started` and `bound` markers; both arms assert the same claim: *the launcher resolved to exactly the expected port*.

```js
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const REPO_ROOT = path.resolve(import.meta.dirname, '../..');

const SERVER_STUB = `
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
const port = Number(process.env.PORT);
const dir = process.env.MARKER_DIR;
fs.writeFileSync(path.join(dir, 'started'), String(port));
const server = http.createServer((_req, res) => res.end('ok'));
server.listen(port, '127.0.0.1', () => {
  fs.writeFileSync(path.join(dir, 'bound'), String(port));
});
setInterval(() => {}, 1000);
process.on('SIGTERM', () => { server.close(); process.exit(0); });
`;

const STUB = (body) => `#!/bin/sh\n${body}\nexit 0\n`;

function makeHarness() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), '9router-port-'));
  const appDir = path.join(root, 'app');
  const binDir = path.join(root, 'bin');
  const markerDir = path.join(root, 'markers');
  fs.mkdirSync(appDir, { recursive: true });
  fs.mkdirSync(binDir, { recursive: true });
  fs.mkdirSync(markerDir, { recursive: true });

  fs.cpSync(path.join(REPO_ROOT, 'cli'), path.join(root, 'cli'), { recursive: true });
  fs.writeFileSync(path.join(appDir, 'server.js'), SERVER_STUB);

  for (const name of ['ps', 'lsof', 'npm']) {
    fs.writeFileSync(path.join(binDir, name), STUB('exit 1'), { mode: 0o755 });
  }
  return { root, binDir, markerDir };
}

function runLauncher({ root, binDir, markerDir }, port, extraArgs = []) {
  const child = spawn(
    process.execPath,
    ['cli/cli.js', '--skip-update', '--no-browser', ...extraArgs],
    {
      cwd: root,
      env: {
        ...process.env,
        PATH: `${binDir}:${process.env.PATH}`,
        PORT: String(port),
        MARKER_DIR: markerDir,
      },
      stdio: ['ignore', 'pipe', 'pipe'],
    },
  );
  const out = [];
  child.stdout.on('data', (d) => out.push(d));
  child.stderr.on('data', (d) => out.push(d));
  return { child, output: () => Buffer.concat(out).toString('utf8') };
}

async function assertResolvedPort(port, extraArgs = []) {
  const h = makeHarness();
  const { child, output } = runLauncher(h, port, extraArgs);
  try {
    await new Promise((resolve) => {
      const deadline = setTimeout(resolve, 8000);
      const check = setInterval(() => {
        if (fs.existsSync(path.join(h.markerDir, 'bound')) || child.exitCode !== null) {
          clearTimeout(deadline); clearInterval(check); resolve();
        }
      }, 50);
    });

    const text = output();
    const boundFile = path.join(h.markerDir, 'bound');

    if (fs.existsSync(boundFile)) {
      // Arm A: our child bound the port; the URL names it.
      assert.equal(fs.readFileSync(boundFile, 'utf8').trim(), String(port),
        'marker proves OUR child bound the expected port');
      assert.match(text, new RegExp(`(localhost|127\\.0\\.0\\.1):${port}\\b`));
    } else {
      // Arm B: refusal names exactly the same port.
      assert.match(text, /EADDRINUSE|already in use/,
        'launcher either started on the expected port or refused loudly');
      assert.match(text, new RegExp(`(?:port\\s+|PORT=)${port}\\b`),
        'refusal names exactly the expected port');
    }
  } finally {
    child.kill('SIGTERM');
    fs.rmSync(h.root, { recursive: true, force: true });
  }
}

test('E2E: PORT env honoured', async () => { await assertResolvedPort(20129); });
test('E2E: --port beats PORT', async () => { await assertResolvedPort(20131, ['--port', '20131']); });
```

