### 2.2 `polybool.js`

```javascript
'use strict';
/*
 * Robust 2D polygon boolean operations built on the integer, plane-sweep
 * Clipper engine (Angus Johnson's Clipper, js port "clipper-lib").
 *
 * Public representation (canonical):
 *   MultiPolygon = Array<Polygon>
 *   Polygon      = Array<Ring>          // ring[0] is the outer ring, ring[1..] holes
 *   Ring         = Array<[x, y]>        // closed implicitly, no repeated last point
 *
 * Guarantees on every returned MultiPolygon:
 *   - outer rings are CCW (positive signed area), holes are CW
 *   - holes are nested inside the immediately enclosing outer ring
 *   - no duplicate consecutive points, no zero-length edges, no collinear
 *     "spike" vertices, no rings with < 3 points
 *   - can be fed straight back in as input
 *
 * The engine needs integers; we scale the floating inputs by a power of ten
 * chosen from the inputs' decimal representation so the scaling is (for all
 * practical, finite-decimal inputs) exact and the area invariants hold to
 * machine precision.
 */

const ClipperLib = require('clipper-lib');
const Clipper = ClipperLib.Clipper;
const ClipType = ClipperLib.ClipType;
const PolyType = ClipperLib.PolyType;
const PolyFillType = ClipperLib.PolyFillType;
const PolyTree = ClipperLib.PolyTree;

const MAX_DECIMALS = 9;
// The JS port of Clipper guarantees exact integer coordinates up to about
// sqrt(2^106-1)/2 ~ 4.5e15.  We stay well inside that so the Int128 path
// (BigInteger) is used for the exact slope/collinearity predicates.
const SAFE_INT = 1e15;

/* ------------------------------------------------------------------ *
 * signed area / orientation / point tests
 * ------------------------------------------------------------------ */

function ringSignedArea(ring) {
  let a = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    a += ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
  }
  return a / 2;
}

function multiPolygonArea(mp) {
  let a = 0;
  for (const poly of mp) {
    for (let r = 0; r < poly.length; r++) {
      const ar = Math.abs(ringSignedArea(poly[r]));
      a += r === 0 ? ar : -ar; // outer adds, holes subtract
    }
  }
  return a;
}

/** even-odd ray crossing over every ring of the multipolygon */
function pointInRingEvenOdd(x, y, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    if ((yi > y) !== (yj > y)) {
      const xint = xj + ((y - yj) * (xi - xj)) / (yi - yj);
      if (x < xint) inside = !inside;
    }
  }
  return inside;
}

function pointInMultiPolygon(mp, pt) {
  // even-odd across all rings gives correct inside/outside for nested outers+holes
  let inside = false;
  for (const poly of mp) {
    for (const ring of poly) {
      if (pointInRingEvenOdd(pt[0], pt[1], ring)) inside = !inside;
    }
  }
  return inside;
}

/* ------------------------------------------------------------------ *
 * input normalisation
 * ------------------------------------------------------------------ */

function isPoint(p) {
  return Array.isArray(p) && p.length >= 2 &&
    typeof p[0] === 'number' && typeof p[1] === 'number';
}

/** Accept either a MultiPolygon, a single Polygon, or a single Ring. */
function toMultiPolygon(input) {
  if (!Array.isArray(input) || input.length === 0) return [];
  if (isPoint(input[0])) return [[input]];      // single ring
  if (isPoint(input[0][0])) return [input];     // single polygon (array of rings)
  return input;                                 // already a MultiPolygon
}

/* ------------------------------------------------------------------ *
 * choose an integer scale from the decimal representation of the input
 * ------------------------------------------------------------------ */

function decimalsOf(v) {
  if (!isFinite(v)) throw new Error('non-finite coordinate');
  for (let d = 0; d <= MAX_DECIMALS; d++) {
    const s = Math.pow(10, d);
    const scaled = v * s;
    if (Math.abs(scaled - Math.round(scaled)) < 1e-7) return d;
  }
  return MAX_DECIMALS;
}

function chooseScale(multipolygons) {
  let maxD = 0;
  let maxAbs = 0;
  for (const mp of multipolygons) {
    for (const poly of mp) for (const ring of poly) for (const p of ring) {
      maxD = Math.max(maxD, decimalsOf(p[0]), decimalsOf(p[1]));
      maxAbs = Math.max(maxAbs, Math.abs(p[0]), Math.abs(p[1]));
    }
  }
  // base scale represents every input coordinate exactly
  const base = Math.pow(10, maxD);
  // Target a working magnitude of ~2e12 for the largest scaled coordinate.
  // Too small -> intersection vertices are rounded too coarsely (area slivers);
  // too large -> double-precision cancellation inside IntersectPoint produces
  // wrong rounded vertices.  ~2e12 empirically puts both errors below 1e-9
  // for coordinates of ordinary magnitude while staying far inside Clipper's
  // safe integer range.
  const TARGET_MAG = 2e12;
  const target = Math.floor(Math.min(TARGET_MAG, SAFE_INT) / Math.max(1, maxAbs));
  let scale = base;
  while (scale <= target / 10) scale *= 10;
  return scale;
}

/* ------------------------------------------------------------------ *
 * clipper <-> canonical conversion
 * ------------------------------------------------------------------ */

function toClipperPath(mp, scale) {
  const paths = [];
  for (const poly of mp) {
    for (let r = 0; r < poly.length; r++) {
      const ring = poly[r];
      if (ring.length < 3) continue;
      const a = ringSignedArea(ring);
      if (a === 0) continue; // zero-area ring contributes nothing
      const path = ring.map((p) => ({
        X: Math.round(p[0] * scale), Y: Math.round(p[1] * scale),
      }));
      // canonical orientation: outer CCW, holes CW (opposite of outer)
      const wantCCW = r === 0;
      if (wantCCW ? a < 0 : a > 0) path.reverse();
      paths.push(path);
    }
  }
  return paths;
}

/** remove consecutive duplicates, collinear (incl. spikes), degenerate rings */
function cleanRing(ring) {
  const pts = [];
  for (const p of ring) {
    const last = pts[pts.length - 1];
    if (!last || last.X !== p.X || last.Y !== p.Y) pts.push({ X: p.X, Y: p.Y });
  }
  while (pts.length > 1 && pts[0].X === pts[pts.length - 1].X && pts[0].Y === pts[pts.length - 1].Y) {
    pts.pop();
  }
  if (pts.length < 3) return [];
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[(i - 1 + pts.length) % pts.length];
    const b = pts[i];
    const c = pts[(i + 1) % pts.length];
    const cross = (b.X - a.X) * (c.Y - b.Y) - (b.Y - a.Y) * (c.X - b.X);
    if (cross !== 0) out.push(b);
  }
  return out.length >= 3 ? out : [];
}

function polyTreeToMultiPolygon(tree, scale) {
  const result = [];
  function buildOuter(node, poly) {
    const ring = cleanRing(node.Contour().map((p) => ({ X: p.X, Y: p.Y })));
    if (ring.length < 3) return;
    let contour = ring.map((p) => [p.X / scale, p.Y / scale]);
    if (ringSignedArea(contour) < 0) contour.reverse(); // outer CCW
    poly.push(contour);
    // children of an outer node are holes
    for (const child of node.Childs()) buildHole(child, poly);
  }
  function buildHole(node, poly) {
    const ring = cleanRing(node.Contour().map((p) => ({ X: p.X, Y: p.Y })));
    if (ring.length >= 3) {
      let contour = ring.map((p) => [p.X / scale, p.Y / scale]);
      if (ringSignedArea(contour) > 0) contour.reverse(); // hole CW
      poly.push(contour);
    }
    // children of a hole are islands (new outers)
    for (const child of node.Childs()) {
      const poly2 = [];
      buildOuter(child, poly2);
      if (poly2.length) result.push(poly2);
    }
  }
  for (const child of tree.Childs()) {
    const poly = [];
    buildOuter(child, poly);
    if (poly.length) result.push(poly);
  }
  return result;
}

/* ------------------------------------------------------------------ *
 * public API
 * ------------------------------------------------------------------ */

function execute(subjectInput, clipInput, clipType) {
  const subject = toMultiPolygon(subjectInput);
  const clip = toMultiPolygon(clipInput);
  const scale = chooseScale([subject, clip]);

  const subjPaths = toClipperPath(subject, scale);
  const clipPaths = toClipperPath(clip, scale);
  if (subjPaths.length === 0 && clipPaths.length === 0) return [];

  const c = new Clipper(0);
  c.StrictlySimple = true;
  c.PreserveCollinear = true;
  if (subjPaths.length) c.AddPaths(subjPaths, PolyType.ptSubject, true);
  if (clipPaths.length) c.AddPaths(clipPaths, PolyType.ptClip, true);

  const tree = new PolyTree();
  const ok = c.Execute(clipType, tree, PolyFillType.pftNonZero, PolyFillType.pftNonZero);
  if (!ok && tree.Childs().length === 0) return [];
  if (!ok) throw new Error('clipper execute failed');
  return polyTreeToMultiPolygon(tree, scale);
}

function union(a, b) { return execute(a, b, ClipType.ctUnion); }
function intersection(a, b) { return execute(a, b, ClipType.ctIntersection); }
function difference(a, b) { return execute(a, b, ClipType.ctDifference); }
function xor(a, b) { return execute(a, b, ClipType.ctXor); }

module.exports = {
  union, intersection, difference, xor,
  pointInMultiPolygon, multiPolygonArea, ringSignedArea,
  toMultiPolygon,
};
```

### 2.3 API and representation

```text
MultiPolygon = Array<Polygon>
Polygon      = Array<Ring>          // ring[0] = outer, ring[1..] = holes
Ring         = Array<[x, y]>        // implicitly closed, last point NOT repeated
```

```javascript
const { union, intersection, difference, xor } = require('./polybool');

const A = [[[ [0,0],[10,0],[10,10],[0,10] ]]];                 // square
const B = [[[ [10,10],[20,10],[20,20],[10,20] ]]];             // touches A at one vertex

union(A, B);        // -> two squares
intersection(A, B); // -> []         (intersection is a single point -> zero area)
difference(A, B);   // -> A
xor(A, B);          // -> A ∪ B
```

`toMultiPolygon` also accepts a single polygon (`[ring, hole, ...]`) or a single
`ring`, so callers do not have to wrap trivial inputs. Every returned ring is
canonical and can be passed straight back into any operation.

`pointInMultiPolygon(mp, [x,y])`, `multiPolygonArea(mp)` and
`ringSignedArea(ring)` are exported for testing/consumer use.

