  for (const poly of mp) {
    for (let r = 0; r < poly.length; r++) {
      const ring = poly[r];
      if (ring.length < 3) return fail(`${label}: ring < 3 pts`);
      const a = P.ringSignedArea(ring);
      if (r === 0 && !(a > 0)) return fail(`${label}: outer not CCW`);
      if (r > 0 && !(a < 0)) return fail(`${label}: hole not CW`);
      for (let i = 0; i < ring.length; i++) {
        const p = ring[i], q = ring[(i + 1) % ring.length], b = ring[(i - 1 + ring.length) % ring.length];
        if (p[0] === q[0] && p[1] === q[1]) return fail(`${label}: zero-length edge`);
        const cr = (p[0] - b[0]) * (q[1] - p[1]) - (p[1] - b[1]) * (q[0] - p[0]);
        if (Math.abs(cr) < 1e-12) return fail(`${label}: collinear/spike vertex`);
