	ID            string `json:"id"`
	Object        string `json:"object"`
	Created       int64  `json:"created"`
	OwnedBy       string `json:"owned_by"`
	Window        int    `json:"window"`         // absent -> 0
	ContextLength int    `json:"context_length"` // absent -> 0
}
```

