package agent

import (
	"context"
	"errors"
	"log"
	"os"
	"strings"
	"sync"
	"testing"
	"time"
)

// ---- seams -----------------------------------------------------------------

type call struct {
	name string
	args []string
}

type fakeRunner struct {
	mu    sync.Mutex
	calls []call
	err   error
}

func (f *fakeRunner) Run(_ context.Context, name string, args ...string) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.calls = append(f.calls, call{name: name, args: append([]string(nil), args...)})
	return f.err
}

func (f *fakeRunner) snapshot() []call {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]call(nil), f.calls...)
}

type probeStep struct {
	owner uint32
	err   error
}

// fakeProbe returns scripted results in order. After the script is exhausted it
// repeats the last step, which models a stable (converged or permanently bad)
// filesystem.
type fakeProbe struct {
	mu    sync.Mutex
	steps []probeStep
	n     int
}

func (p *fakeProbe) Owner(string) (uint32, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.steps) == 0 {
		return 0, errors.New("fakeProbe: no steps scripted")
	}
	i := p.n
	if i >= len(p.steps) {
		i = len(p.steps) - 1
	}
	p.n++
	return p.steps[i].owner, p.steps[i].err
}

// newTestEnsurer builds an ensurer with the retry delay short-circuited so the
// suite runs instantly. It records warnings into a buffer we can assert on.
func newTestEnsurer(t *testing.T, r systemRunner, p ownerProbe, attempts int) (*runtimeDirEnsurer, *strings.Builder) {
	t.Helper()
	e := newRuntimeDirEnsurer(r, p)
	e.attempts = attempts
	e.retryDelay = time.Millisecond
	var logBuf strings.Builder
	e.logger = log.New(&logBuf, "", 0)
	e.sleep = func(ctx context.Context, _ time.Duration) error {
		return ctx.Err() // tests never want to wait
	}
	return e, &logBuf
}

// ---- tests -----------------------------------------------------------------

// Transient race: the probe first sees uid 0 (logind recreated it after our
// chown), then uid 1004 on the next attempt. The converged mismatch must be
// ABSORBED (nil error) and logged.
func TestEnsureRuntimeDirOwnership_TransientConverge(t *testing.T) {
	r := &fakeRunner{}
	p := &fakeProbe{steps: []probeStep{
		{owner: 0},    // attempt 1 probe: lost race
		{owner: 1004}, // attempt 2 probe: converged
	}}
	e, logBuf := newTestEnsurer(t, r, p, defaultRuntimeDirAttempts)

	err := e.ensureRuntimeDirOwnership(context.Background(), "/run/user/1004", 1004)
	if err != nil {
		t.Fatalf("transient race must be absorbed, got error: %v", err)
	}

	// Ownership must have been re-asserted twice: mkdir+chown per attempt.
	got := r.snapshot()
	if len(got) != 4 {
		t.Fatalf("expected 4 runner calls (2 x mkdir+chown), got %d: %+v", len(got), got)
	}
	if !strings.Contains(logBuf.String(), "converged on attempt 2") {
		t.Fatalf("expected convergence warning, log=%q", logBuf.String())
	}
}

// Persistent foreign owner that is also a mount point: exhaustion must fail
// with the exact production fragment and a mount attribution naming
// fstype/source.
func TestEnsureRuntimeDirOwnership_PersistentFailWithMountAttribution(t *testing.T) {
	r := &fakeRunner{}
	p := &fakeProbe{steps: []probeStep{{owner: 0}}}
	e, _ := newTestEnsurer(t, r, p, defaultRuntimeDirAttempts)

	fixture := strings.Join([]string{
		`25 30 0:23 / /proc rw,nosuid,nodev,noexec,relatime - proc proc rw`,
		`36 25 0:31 / /run/user/1004 rw,nosuid,nodev,relatime shared:9 - tmpfs tmpfs rw,size=102400k,mode=755`,
		`37 25 0:32 / /run/user/1005 rw,nosuid,nodev,relatime shared:10 - tmpfs tmpfs rw,size=102400k,mode=755`,
	}, "\n")
