# src/checkoutservice/main.go  →  protos/demo.proto  (service_contract)  [grpc_proto conf=1.00]   exit 0

hilo graph impact docs/readme.md
# error: ... 'docs/readme.md' is not an indexable source file (26 AST languages) — impact/related cannot answer for it   exit 1
