## 3. Verification

### 3.1 The helper is exhaustively unit-tested

`cmd/dagger/main_test.go` (drop-in, `package main`):

```go
func TestStructuredOutputFailure(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool // true => expect a non-nil error
	}{
		{"typed failure envelope", `{"ok":false,"format":"json_schema","error":"field \"summary\" expected array but got string","attempts":3}`, true},
		{"failure with whitespace", "  {\n  \"ok\": false  \n}\n", true},
		{"success envelope", `{"ok":true,"data":{"summary":["a"]},"attempts":1}`, false},
		{"empty output", ``, false},
		{"whitespace only", "  \n\t ", false},
		{"prose", `Here is your summary: - a - b`, false},
		{"bare scalar", `42`, false},
		{"json string", `"hello"`, false},
		{"json array", `[1,2,3]`, false},
		{"json null", `null`, false},
		{"object without ok key", `{"data":1,"format":"json_schema"}`, false},
		{"malformed json", `{"ok": false`, false},
		{"ok wrong type", `{"ok":"false"}`, false},
		{"nested ok only", `{"data":{"ok":false}}`, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := structuredOutputFailure(tc.in) != nil; got != tc.want {
				t.Fatalf("structuredOutputFailure(%q) err=%v, want err=%v", tc.in, got, tc.want)
			}
		})
	}
}
```

