## 4. Reference implementation (verified, compilable)

`rollback.go`:

```go
package rollback

import (
	"context"
	"time"
)

// Command is one host command to run during compensation.
type Command struct {
	Name     string
	Args     []string
	OwnGroup bool // installer: own process group so cancel kills the subtree
}

// Runner is the seam that every host command must go through. Tests implement
// it to observe the exact context each command receives; production uses
// ExecRunner. A shell/PATH stub cannot observe a context, which is why the
// command execution has to be injectable.
type Runner interface {
	Run(ctx context.Context, cmd Command) error
}

// Budget: see §2.
type Budget struct {
	base   context.Context
	anchor time.Time
	floor  time.Duration
	now    func() time.Time
}

func NewBudget(base context.Context, total, floor time.Duration) *Budget {
	if base == nil {
		base = context.Background()
	}
	if floor <= 0 {
		floor = 5 * time.Second
	}
	return &Budget{base: base, anchor: time.Now().Add(total), floor: floor, now: time.Now}
}

func (b *Budget) Context(stepTimeout time.Duration) (context.Context, context.CancelFunc) {
	parent := context.WithoutCancel(b.base)
	remaining := b.anchor.Sub(b.now())
	if remaining < b.floor {
		remaining = b.floor
	}
	if stepTimeout > 0 && stepTimeout < remaining {
		remaining = stepTimeout
	}
	return context.WithTimeout(parent, remaining)
}

// Step is one compensating action. Critical steps (userdel, process reaping)
// must always be attempted and their real outcome recorded.
type Step struct {
	Name     string
	Critical bool
	Timeout  time.Duration
	Run      func(ctx context.Context) error
}

// StepResult captures what actually happened.
type StepResult struct {
	Name       string
	Err        error
	ContextErr error // non-nil with Err == nil => refused before it ran
}

type Compensator struct {
	Runner Runner
	Budget *Budget
	onStep func(name string, ctx context.Context) // test hook
}

func (c *Compensator) Run(steps ...Step) []StepResult {
	results := make([]StepResult, 0, len(steps))
	for _, s := range steps {
		ctx, cancel := c.Budget.Context(s.Timeout)
		if c.onStep != nil {
			c.onStep(s.Name, ctx)
		}
		err := s.Run(ctx)
		results = append(results, StepResult{Name: s.Name, Err: err, ContextErr: ctx.Err()})
		cancel()
	}
	return results
}
```

`compensations.go` (fixes b, c, d, e):

```go
package rollback

import (
	"context"
	"fmt"
	"os/exec"
	"syscall"
	"time"
)

// ExecRunner is the production runner.
type ExecRunner struct{}

func (ExecRunner) Run(ctx context.Context, c Command) error {
	return (ExecRunner{}).buildCommand(ctx, c).Run()
}

// buildCommand applies the process-group policy. Factored out for testing.
func (ExecRunner) buildCommand(ctx context.Context, c Command) *exec.Cmd {
	cmd := exec.CommandContext(ctx, c.Name, c.Args...)
	if c.OwnGroup {
		cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
		// Go's default cancel kills only cmd.Process; override it so
		// cancellation takes the ENTIRE group (su -> installer ->
		// curl/rootlesskit), keeping the home free for userdel -r.
		cmd.Cancel = func() error {
			if cmd.Process == nil {
				return nil
			}
			return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
		}
		cmd.WaitDelay = 5 * time.Second
	}
	return cmd
}

// InstallCommand: own process group so a cancelled request is not orphaned.
func InstallCommand(user, script string, uid int) Command {
	return Command{Name: "su", Args: []string{"-l", user, "-c", script}, OwnGroup: true}
}

type UserRollback struct {
	Runner Runner
	User   string
	UID    int
	Now    func() time.Time
}

func (u UserRollback) run(ctx context.Context, name string, args ...string) error {
	return u.Runner.Run(ctx, Command{Name: name, Args: args})
}

func (u UserRollback) Steps() []Step {
	slice := fmt.Sprintf("user-%d.slice", u.UID)
	dropin := fmt.Sprintf("/etc/systemd/system/%s.d", slice)
	unit := fmt.Sprintf("user@%d.service", u.UID)

	return []Step{
		// (e) reset the recycled uid's slice state
		{Name: "stop-slice", Timeout: 20 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "systemctl", "stop", slice)
		}},
		{Name: "remove-slice-dropin", Timeout: 10 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "rm", "-rf", dropin)
		}},
		{Name: "disable-linger", Timeout: 15 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "loginctl", "disable-linger", u.User)
		}},
		// the step that historically burned the shared budget
		{Name: "stop-manager", Timeout: 20 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "systemctl", "stop", unit)
		}},
		{Name: "terminate-user", Timeout: 20 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "loginctl", "terminate-user", u.User)
		}},
		// (b) reap orphaned installer subtree BEFORE userdel
		{Name: "reap-user-processes", Critical: true, Timeout: 20 * time.Second, Run: func(ctx context.Context) error {
			_ = u.run(ctx, "loginctl", "terminate-user", u.User)
			return u.run(ctx, "pkill", "-KILL", "-u", u.User)
		}},
		// (a) critical: attempted even if the anchor is exhausted
		{Name: "userdel", Critical: true, Timeout: 30 * time.Second, Run: func(ctx context.Context) error {
			return u.run(ctx, "userdel", "-r", u.User)
		}},
		// (d) return the outcome, do not discard it
		{Name: "isolation-teardown", Timeout: 20 * time.Second, Run: func(ctx context.Context) error {
			return teardownIsolation(ctx)
		}},
	}
}
```

### Wiring into `internal/agent/spawn_failure.go` / `manager_spawn.go`

Replace the old single-`ctx` closure with:

```go
budget := rollback.NewBudget(reqCtx, 60*time.Second, 10*time.Second)

// On cancellation / any stage failure:
results := (&rollback.Compensator{
	Runner: execRunner, // injectable: tests pass a recording runner
	Budget: budget,
}).Run(userRollback.Steps()...)

// (d) persist each real outcome; never pre-assert success.
for _, r := range results {
	switch {
	case r.ContextErr != nil && r.Err != nil:
		log.Error("rollback step refused: context already done", "step", r.Name, "err", r.Err)
	case r.Err != nil:
		log.Error("rollback step failed", "step", r.Name, "err", r.Err)
	default:
		log.Info("rollback step ok", "step", r.Name)
	}
}
```

Key mapping:
- `execRunner` is the seam: `internal/agent` receives a `rollback.Runner` instead of calling `exec.CommandContext` directly.
- The breadcrumb is written **from `results`**, not from a predetermined "success" string.
- Installer launch uses `rollback.InstallCommand(...)` (own process group).
- Pre-reuse UID path calls the slice-reset steps.

