type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}
func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

type call struct {
	cmd         Command
	ctx         context.Context
	liveAtStart bool // ctx.Err() == nil at runner entry
	refused     bool // exec would return ctx.Err() without exec'ing
	err         error
}

type recordingRunner struct {
	mu        sync.Mutex
	calls     []call
	blockName string
	entered   chan struct{}
	release   chan struct{}
	once      sync.Once
}

func (r *recordingRunner) Run(ctx context.Context, c Command) error {
	startErr := ctx.Err()
	if startErr != nil {
		r.record(call{cmd: c, ctx: ctx, refused: true, err: startErr})
		return startErr
	}
	r.record(call{cmd: c, ctx: ctx, liveAtStart: true})
	if c.Name == r.blockName {
		r.once.Do(func() { close(r.entered) })
		select {
		case <-r.release:
			return nil
		case <-ctx.Done():
			err := ctx.Err()
			r.mu.Lock()
			r.calls[len(r.calls)-1].err = err
			r.mu.Unlock()
			return err
		}
	}
	return nil
}

func (r *recordingRunner) record(c call) {
	r.mu.Lock()
	r.calls = append(r.calls, c)
	r.mu.Unlock()
}

func (r *recordingRunner) find(name string) (call, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, c := range r.calls {
		if c.cmd.Name == name {
			return c, true
		}
	}
	return call{}, false
}

func newRecordingRunner(block string) *recordingRunner {
	return &recordingRunner{blockName: block, entered: make(chan struct{}), release: make(chan struct{})}
