	if err := ec.Start(); err != nil {
		t.Fatalf("start: %v", err)
	}
	pgid := ec.Process.Pid
	if !pollGroupAlive(pgid, true, 2*time.Second) {
		t.Fatal("subtree not alive before cancel")
	}
	cancel()
	_ = ec.Wait()
	if !pollGroupAlive(pgid, false, 5*time.Second) {
		t.Fatalf("process group %d survived cancellation", pgid)
	}
}

func pollGroupAlive(pgid int, wantAlive bool, within time.Duration) bool {
	deadline := time.Now().Add(within)
	for {
		err := syscall.Kill(-pgid, 0)
		alive := err == nil || errors.Is(err, syscall.EPERM)
		if alive == wantAlive {
			return true
		}
		if time.Now().After(deadline) {
			return false
		}
		time.Sleep(10 * time.Millisecond)
	}
}
