func TestEveryRegistryKeyAddressable(t *testing.T) {
	// Inventory comes from the CODE, not the spec.
	inventory := defaultResolveKeys(t) // calls resolveConfig(nil,nil) and returns keys

	// The ONLY keys allowed to be unreachable by a flag, each with a reason.
	exempt := map[string]string{
		// table keys whose value must be a declaration (not a scalar flag)
		"routing.table": "value must be a declaration, not a scalar --flag",
		// extra keys added per release; keep NAMED, never silent
		"limits.table": "value must be a declaration, not a scalar --flag",
		// flag name trips the mandatory argv secret scan
		"auth.api_key": "flag name trips the mandatory argv secret scan",
	}

	for _, key := range inventory {
		if reason, ok := exempt[key]; ok {
			t.Logf("exempt %s: %s", key, reason)
			continue
		}

		flagToken := "--" + keyToFlag(key)

		da, err := splitDaemonArgs([]string{flagToken + "=x"})
		if err != nil {
			t.Fatalf("%s: split rejected its own flag token %q: %v", key, flagToken, err)
		}
		if len(da.Forward) != 1 || da.Forward[0] != flagToken+"=x" {
			t.Fatalf("%s: token not forwarded verbatim: %#v", key, da.Forward)
		}

		cfg, err := resolveConfig("", da.Forward)
		if err != nil {
			t.Fatalf("%s: resolver rejected documented flag %q: %v", key, flagToken, err)
		}
		if got := cfg.Source(key); got != "flag" {
			t.Errorf("%s: source=%q, want \"flag\" (flag token %q unreachable)",
				key, got, flagToken)
		}
	}
}

// A brand-new key that is neither addressable nor named in exempt must fail.
func TestNewUnaddressableKeyFails(t *testing.T) {
	if _, err := resolveConfig("", []string{"--definitely-new-key=x"}); err == nil {
		t.Fatal("resolver accepted an unknown key; whitelist is not authoritative")
	}
}

func TestOneDashOwnShortFlags(t *testing.T) {
	for _, ok := range []string{"-v", "-h"} {
		da, err := splitDaemonArgs([]string{ok})
		if err != nil || (!da.Version && !da.Help) {
			t.Fatalf("%s: not recognised as an own short flag: %v", ok, err)
		}
	}
	// A one-dash key token is a loud error, not a silent drop.
	if _, err := splitDaemonArgs([]string{"-state_root=1"}); err == nil {
		t.Fatal("-state_root was silently accepted; it must be rejected")
	}
}

func TestUnknownKeyIsLoudRefusal(t *testing.T) {
	da, _ := splitDaemonArgs([]string{"--not_a_key=1"})
	_, err := resolveConfig("", da.Forward)
	var ref *RefusalError
	if !errors.As(err, &ref) || ref.ExitCode != 13 {
		t.Fatalf("want TROUBLE-LIFECYCLE-001/exit 13, got %v", err)
	}
}
```

`defaultResolveKeys` is the anchor: because it comes from a default resolve, adding a registry key and forgetting both the flag spelling and an exemption turns the test red.

## Verification

Run from the repo root:

```bash
