func TestRangeSetAddMergeSubtract(t *testing.T) {
	var s RangeSet
	for _, n := range []uint64{1, 2, 3, 5, 4} {
		s.Add(n)
	}
	if got, want := s.Ascending(), []Range{{1, 5}}; !reflect.DeepEqual(got, want) {
		t.Fatalf("after adds: got %v want %v", got, want)
	}
	s.Subtract(3)
	if got, want := s.Ascending(), []Range{{1, 2}, {4, 5}}; !reflect.DeepEqual(got, want) {
		t.Fatalf("after subtract: got %v want %v", got, want)
	}
	if !s.Contains(2) || s.Contains(3) || !s.Contains(4) {
		t.Fatalf("contains wrong: %v", s.Ascending())
	}
	if s.Len() != 4 {
		t.Fatalf("len=%d want 4", s.Len())
	}
	if min, _ := s.Min(); min != 1 {
		t.Fatalf("min=%d", min)
	}
	if max, _ := s.Max(); max != 5 {
		t.Fatalf("max=%d", max)
	}
	if got, want := s.Descending(), []Range{{4, 5}, {1, 2}}; !reflect.DeepEqual(got, want) {
		t.Fatalf("descending: got %v want %v", got, want)
	}
}

func TestRangeSetOutOfOrder(t *testing.T) {
	var s RangeSet
	for _, n := range []uint64{9, 3, 1, 7, 8, 2, 5} {
		s.Add(n)
	}
	if got, want := s.Ascending(), []Range{{1, 3}, {5, 5}, {7, 9}}; !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v want %v", got, want)
	}
}

func TestACKFrameRoundTrip(t *testing.T) {
	var s RangeSet
	for _, n := range []uint64{0, 1, 2, 5, 8, 9} {
		s.Add(n)
	}
	f, ok := NewAckFrame(&s, 1234)
	if !ok {
		t.Fatal("no frame")
	}
	f.ECN = true
	f.ECT0, f.ECT1, f.ECNCE = 10, 20, 7
	wire := f.Encode()
	got, n, err := DecodeAckFrame(wire)
	if err != nil {
		t.Fatalf("decode: %v", err)
	}
	if n != len(wire) {
		t.Fatalf("consumed %d of %d", n, len(wire))
	}
	if got.LargestAcked != 9 || got.AckDelay != 1234 || !got.ECN {
		t.Fatalf("header mismatch: %+v", got)
	}
	if !reflect.DeepEqual(got.SetFromAck().Ascending(), s.Ascending()) {
		t.Fatalf("ranges mismatch: %v vs %v", got.SetFromAck().Ascending(), s.Ascending())
	}
	if got.ECT0 != 10 || got.ECT1 != 20 || got.ECNCE != 7 {
		t.Fatalf("ecn mismatch: %+v", got)
	}
}

func TestPTOExponentialBackoff(t *testing.T) {
	m := NewManager(DefaultConfig())
	m.SendPacket(Application, true, 1200)
	// No RTT sample: PTO = 3*initialRTT + max_ack_delay = 325000us.
	steps := []struct {
		at    int64
		probe int
	}{
		{324_999, 0},
		{325_000, 1},   // first probe
		{974_999, 1},   // 325000 + 2*325000
		{975_000, 2},   // second probe
		{2_274_999, 2}, // 975000 + 4*325000
		{2_275_000, 3}, // third probe
	}
	for _, st := range steps {
		m.AdvanceTo(st.at)
		if m.Probes() != st.probe {
			t.Fatalf("at %d probes=%d want %d", st.at, m.Probes(), st.probe)
		}
	}
}

func TestPTOArmedOnlyByFirstAckElicitingPacket(t *testing.T) {
	m := NewManager(DefaultConfig())
	m.SendPacket(Application, false, 40) // ACK-only
	if _, armed := m.PTOTime(Application); armed {
		t.Fatal("ACK-only packet armed a PTO")
	}
	m.SendPacket(Application, true, 1200)
	t1, armed := m.PTOTime(Application)
	if !armed {
		t.Fatal("first ack-eliciting packet did not arm PTO")
	}
	m.AdvanceTo(1000)
	m.SendPacket(Application, true, 1200)
	if t2, _ := m.PTOTime(Application); t2 != t1 {
		t.Fatalf("PTO deadline moved from %d to %d while packets were in flight", t1, t2)
	}
}

func TestNewRenoHalvesOnLoss(t *testing.T) {
	c := NewNewReno(1200)
	if c.Window() != 12000 {
		t.Fatalf("initial window=%d", c.Window())
	}
	c.OnPacketLost(100, 0, 1200)
	if c.Window() != 6000 {
		t.Fatalf("window after loss=%d want 6000", c.Window())
	}
	// Exit recovery by acking something sent after recovery started.
	c.OnPacketAcked(200, 150, 1200, 50000)
	if c.inRecovery {
		t.Fatal("still in recovery")
	}
}

func TestNewRenoECNOncePerRTT(t *testing.T) {
	c := NewNewReno(1200)
	c.OnECNCongestion(1000, 50000)
	if c.Window() != 6000 {
		t.Fatalf("window after CE=%d want 6000", c.Window())
	}
	// Second CE inside the same RTT must be ignored.
	c.OnECNCongestion(2000, 50000)
	if c.Window() != 6000 {
		t.Fatalf("window changed within RTT: %d", c.Window())
	}
}

func TestDeliveryRateControllerReacts(t *testing.T) {
	c := NewDeliveryRate(1200)
	c.OnPacketSent(0, 0, 1200)
	c.OnPacketAcked(10_000, 0, 1200, 10_000)
	c.OnPacketAcked(20_000, 10_000, 1200, 10_000)
	if c.Window() <= 0 {
		t.Fatal("window not grown")
	}
	before := c.Window()
	c.OnPacketLost(30_000, 20_000, 1200)
	if c.Window() >= before {
		t.Fatalf("loss did not reduce window: %d -> %d", before, c.Window())
	}
}

func TestPluggableCongestionController(t *testing.T) {
	cfg := DefaultConfig()
	cfg.CC = NewDeliveryRate(1200)
	m := NewManager(cfg)
	r := RunTrace(traceTailLoss(), m)
	if !r.OK() {
		t.Fatalf("violations with delivery-rate controller: %v", r.Violations)
	}
	if got := cfg.CC.Name(); got != "delivery-rate" {
		t.Fatalf("controller name=%q", got)
	}
	if m.Window() <= 0 {
		t.Fatal("window should be positive")
	}
}
