# -> http://localhost:4331/trip/<64hex>
curl -s -o /dev/null -w '%{http_code}\n' http://localhost:4331/trip/<64hex>   # -> 200 (itinerary title)
curl -s -o /dev/null -w '%{http_code}\n' http://localhost:3101/trip/<64hex>   # -> 404 (web origin)
curl -s -o /dev/null -w '%{http_code}\n' http://localhost:4331/trip/<64hex>   # -> 200 (API origin)
