# Event-Time Session Windows with Late-Merge Retractions, Allowed Lateness, and Idle-Source Watermarks

## 1. Root-cause analysis

A streaming session-window operator fails in four characteristic ways:

**1.1 Firing is easy — un-firing is the hard part.** The naive operator emits `(window, sum)` when the watermark passes `end = maxTs + gap` and then discards the window. A later element that bridges two emitted windows can no longer reach them, so it creates an orphan window and the downstream `SUM` permanently contains the two old sums *plus* the new one. Fix: retain fired sessions through the allowed-lateness period; when a late element absorbs them, emit `-emittedSum` retractions followed by one merged `+mergedSum` replacement. Since downstream is a signed sum, `-a - b + (a+b+late) = late`.

**1.2 Merging is transitive and N-ary.** Collect *every* live session the element's gap-expanded interval touches — not just the nearest — then retract all fired ones and emit a single replacement. Hard-coding "merge two neighbours" breaks for 3+ sessions or on a later re-merge.

**1.3 Drop and purge must share one horizon.** Purge a fired session when `watermark > end + gap + allowedLateness`; drop an unattached element when `watermark > time + gap + allowedLateness`. Any element that can merge a live session satisfies `time <= session.end`, so a purged session implies the element is already past its drop horizon — the decisions are consistent by construction.

**1.4 Idle sources.** Removing an idle partition from the watermark min lets the watermark run past data it may still produce. Instead, an idle partition contributes its `endOfInput` to the min, so the combined watermark advances *up to* that horizon but never *past* it. `endOfInput = Infinity` means no cap.

## 2. The fix

`session-window.js`:

```js
'use strict';

class WatermarkTracker {
  constructor({ onWatermark = () => {} } = {}) {
    this.onWatermark = onWatermark;
    this.partitions = new Map();
    this.watermark = -Infinity;
  }
  register(id, { endOfInput = Infinity } = {}) {
    if (this.partitions.has(id)) throw new Error(`partition ${id} already registered`);
    this.partitions.set(id, { id, watermark: -Infinity, idle: false, endOfInput });
    this._recompute(); return this;
  }
  report(id, watermark) {
    const p = this._get(id);
    if (!Number.isFinite(watermark)) throw new Error('watermark must be finite');
    if (watermark > p.watermark) p.watermark = watermark;
    p.idle = false; this._recompute(); return this;
  }
  setIdle(id, idle = true) { this._get(id).idle = !!idle; this._recompute(); return this; }
  setEndOfInput(id, endOfInput) {
    const p = this._get(id);
    if (!Number.isFinite(endOfInput)) throw new Error('endOfInput must be finite');
    if (endOfInput < p.watermark) throw new Error(`endOfInput ${endOfInput} below watermark ${p.watermark}`);
    p.endOfInput = endOfInput; p.idle = true; this._recompute(); return this;
  }
  _get(id) { const p = this.partitions.get(id); if (!p) throw new Error(`unknown partition ${id}`); return p; }
  _effective(p) { return p.idle ? p.endOfInput : p.watermark; }
  _recompute() {
    let min = Infinity;
    for (const p of this.partitions.values()) min = Math.min(min, this._effective(p));
    if (min > this.watermark) { this.watermark = min; this.onWatermark(min); }
  }
}

class SessionWindowOperator {
  constructor({ gap, allowedLateness = 0, onEmit = () => {}, onSideOutput = () => {} } = {}) {
    if (!Number.isFinite(gap) || gap < 0) throw new Error('gap must be a finite non-negative number');
    if (!Number.isFinite(allowedLateness) || allowedLateness < 0) throw new Error('allowedLateness must be finite and >= 0');
    this.gap = gap; this.allowedLateness = allowedLateness;
    this.onEmit = onEmit; this.onSideOutput = onSideOutput;
    this.watermark = -Infinity;
    this.sessions = new Map(); // key -> Session[]
    this.emitted = new Map();  // sessionId -> currently reflected window
    this.seq = 0;
  }
  _newSession(key, start, maxTs, sum) {
    return { id: `${key}:${++this.seq}`, key, start, maxTs, end: maxTs + this.gap,
             sum, fired: false, emittedSum: 0 };
  }
  _mergeable(s, time) { return time <= s.maxTs + this.gap && time >= s.start - this.gap; }
  _emit(e) {
    if (e.type === 'fire') this.emitted.set(e.sessionId,
      { key: e.key, start: e.start, maxTs: e.maxTs, end: e.end, sum: e.delta });
    else if (e.type === 'retract') this.emitted.delete(e.retracts);
    this.onEmit(e);
  }
  receive(event) {
    const { key, time, value } = event;
    if (typeof key === 'undefined') throw new Error('event.key is required');
    if (!Number.isFinite(time)) throw new Error('event.time must be finite');
    if (!Number.isFinite(value)) throw new Error('event.value must be finite');

    const list = this.sessions.get(key) || [];
    const merging = [], keep = [];
    for (const s of list) { if (this._mergeable(s, time)) merging.push(s); else keep.push(s); }

    if (merging.length === 0 && Number.isFinite(this.watermark) &&
        this.watermark > time + this.gap + this.allowedLateness) {
      this.onSideOutput({ ...event, reason: 'allowed-lateness-expired' }, 'too-late');
      return false;
    }

    let start = time, maxTs = time, sum = value;
    for (const s of merging) {
      if (s.start < start) start = s.start;
      if (s.maxTs > maxTs) maxTs = s.maxTs;
      sum += s.sum;
    }
    const merged = this._newSession(key, start, maxTs, sum);
    const firedMerged = merging.filter((s) => s.fired);

    if (firedMerged.length > 0) {
      for (const s of firedMerged) {
        this._emit({ type: 'retract', reason: 'late-merge', key, sessionId: s.id,
                     start: s.start, maxTs: s.maxTs, end: s.end,
                     delta: -s.emittedSum, retracts: s.id });
      }
      merged.fired = true; merged.emittedSum = merged.sum;
      this._emit({ type: 'fire', reason: 'late-merge-replacement', key, sessionId: merged.id,
                   start: merged.start, maxTs: merged.maxTs, end: merged.end,
                   delta: merged.sum, mergedFrom: merging.map((s) => s.id) });
    } else if (Number.isFinite(this.watermark) && this.watermark >= merged.end) {
      merged.fired = true; merged.emittedSum = merged.sum;
      this._emit({ type: 'fire', reason: 'watermark', key, sessionId: merged.id,
                   start: merged.start, maxTs: merged.maxTs, end: merged.end, delta: merged.sum });
    }
    keep.push(merged);
    this.sessions.set(key, keep);
    return true;
  }
  advanceWatermark(watermark) {
    if (watermark !== Infinity && !Number.isFinite(watermark)) throw new Error('watermark must be finite or Infinity');
    if (watermark <= this.watermark) return;
    this.watermark = watermark;
    for (const [key, list] of [...this.sessions.entries()]) {
      const keep = [];
      for (const s of list) {
        if (!s.fired && this.watermark >= s.end) {
          s.fired = true; s.emittedSum = s.sum;
          this._emit({ type: 'fire', reason: 'watermark', key, sessionId: s.id,
                       start: s.start, maxTs: s.maxTs, end: s.end, delta: s.sum });
        }
        if (s.fired && this.watermark > s.end + this.gap + this.allowedLateness) continue;
        keep.push(s);
      }
      if (keep.length) this.sessions.set(key, keep); else this.sessions.delete(key);
    }
  }
  snapshot() {
    const out = [];
    for (const list of this.sessions.values()) for (const s of list) out.push({ ...s });
    return out;
  }
  currentWindows() { return [...this.emitted.values()].map((w) => ({ ...w })); }
  seedFiredSession(key, { start, maxTs, sum }, { emit = false } = {}) {
    const s = this._newSession(key, start, maxTs, sum);
    s.fired = true; s.emittedSum = sum;
    const list = this.sessions.get(key) || []; list.push(s); this.sessions.set(key, list);
    if (emit) this._emit({ type: 'fire', reason: 'seed', key, sessionId: s.id,
                           start: s.start, maxTs: s.maxTs, end: s.end, delta: s.sum });
    return s;
  }
}

module.exports = { SessionWindowOperator, WatermarkTracker };
```

## 3. Verification

Batch reference (sort by time, greedily group where `diff <= gap`):

```js
function batchSessions(events, gap) {
  const byKey = new Map();
  for (const e of events) { if (!byKey.has(e.key)) byKey.set(e.key, []); byKey.get(e.key).push(e); }
  const result = [];
  for (const [key, list] of byKey) {
    list.sort((a, b) => a.time - b.time || a.arrival - b.arrival);
    let cur = null;
    for (const e of list) {
      if (cur === null || e.time - cur.maxTs > gap) {
        cur = { key, start: e.time, maxTs: e.time, sum: e.value }; result.push(cur);
      } else { cur.maxTs = e.time; cur.sum += e.value; }
    }
  }
  return result;
}
```

