```

### 3.2 `predicates.go` — the crux

```go
package main

import "math/big"

// Point is an integer-coordinate point. Coordinates are assumed to fit in
// [-2^53, 2^53] so that conversion to float64 is exact; the exact fallback
// paths remain correct regardless (they only require |coord| < 2^62 so that
// coordinate differences do not overflow int64).
type Point struct {
	X, Y int64
}

// epsilon is the double rounding unit 2^-53.
const epsilon = 1.1102230246251565e-16

// orient2d returns the sign of the signed area (cross product) of the
// triangle (a,b,c): +1 if a,b,c are counter-clockwise, -1 if clockwise,
// 0 if collinear. Exact.
func orient2d(a, b, c Point) int {
	if !filterSafe(a.X, a.Y, b.X, b.Y, c.X, c.Y) {
		return orient2dExact(a, b, c)
	}
	// Floating-point filter (Shewchuk, "Adaptive Precision Floating-Point
	// Arithmetic and Fast Robust Geometric Predicates", orient2d filter).
	ax, ay := float64(a.X), float64(a.Y)
	bx, by := float64(b.X), float64(b.Y)
	cx, cy := float64(c.X), float64(c.Y)

	detleft := (ax - cx) * (by - cy)
	detright := (ay - cy) * (bx - cx)
	det := detleft - detright

	// errbound = (3 + 16*eps) * eps
	const errboundOrient = (3.0 + 16.0*epsilon) * epsilon
	if det > errboundOrient*(absf(detleft)+absf(detright)) {
		return 1
	}
	if -det > errboundOrient*(absf(detleft)+absf(detright)) {
		return -1
	}
	return orient2dExact(a, b, c)
}

func orient2dExact(a, b, c Point) int {
	bax := new(big.Int).Sub(big.NewInt(b.X), big.NewInt(a.X))
	bay := new(big.Int).Sub(big.NewInt(b.Y), big.NewInt(a.Y))
	cax := new(big.Int).Sub(big.NewInt(c.X), big.NewInt(a.X))
	cay := new(big.Int).Sub(big.NewInt(c.Y), big.NewInt(a.Y))

	det := new(big.Int).Mul(bax, cay)
	det.Sub(det, new(big.Int).Mul(bay, cax))
	return det.Sign()
}

// incircle returns +1 if d lies strictly inside the circle through a,b,c,
// -1 if strictly outside, 0 if cocircular. a,b,c may be given in any
// orientation; the result is normalized internally. Exact.
func incircle(a, b, c, d Point) int {
	if orient2d(a, b, c) < 0 {
		a, b = b, a
	}
	return incircleRaw(a, b, c, d)
}

func incircleRaw(a, b, c, d Point) int {
	if !filterSafe(a.X, a.Y, b.X, b.Y, c.X, c.Y, d.X, d.Y) {
		return incircleExact(a, b, c, d)
	}
	ax, ay := float64(a.X), float64(a.Y)
	bx, by := float64(b.X), float64(b.Y)
	cx, cy := float64(c.X), float64(c.Y)
	dx, dy := float64(d.X), float64(d.Y)

	adx, ady := ax-dx, ay-dy
	bdx, bdy := bx-dx, by-dy
	cdx, cdy := cx-dx, cy-dy

	bdxcdy := bdx * cdy
	cdxbdy := cdx * bdy
	cdxady := cdx * ady
	adxcdy := adx * cdy
	adxbdy := adx * bdy
	bdxady := bdx * ady

	alift := adx*adx + ady*ady
	blift := bdx*bdx + bdy*bdy
	clift := cdx*cdx + cdy*cdy

	det := alift*(bdxcdy-cdxbdy) +
		blift*(cdxady-adxcdy) +
		clift*(adxbdy-bdxady)

	permanent := (absf(bdxcdy)+absf(cdxbdy))*alift +
		(absf(cdxady)+absf(adxcdy))*blift +
		(absf(adxbdy)+absf(bdxady))*clift

	// errbound = (10 + 96*eps) * eps  (Shewchuk iccerrboundA)
	const errboundIncircle = (10.0 + 96.0*epsilon) * epsilon
	if det > errboundIncircle*permanent {
		return 1
	}
	if -det > errboundIncircle*permanent {
		return -1
	}
	return incircleExact(a, b, c, d)
}

func incircleExact(a, b, c, d Point) int {
	adx := new(big.Int).Sub(big.NewInt(a.X), big.NewInt(d.X))
	ady := new(big.Int).Sub(big.NewInt(a.Y), big.NewInt(d.Y))
	bdx := new(big.Int).Sub(big.NewInt(b.X), big.NewInt(d.X))
	bdy := new(big.Int).Sub(big.NewInt(b.Y), big.NewInt(d.Y))
	cdx := new(big.Int).Sub(big.NewInt(c.X), big.NewInt(d.X))
	cdy := new(big.Int).Sub(big.NewInt(c.Y), big.NewInt(d.Y))

	bdxcdy := new(big.Int).Mul(bdx, cdy)
	cdxbdy := new(big.Int).Mul(cdx, bdy)
	cdxady := new(big.Int).Mul(cdx, ady)
	adxcdy := new(big.Int).Mul(adx, cdy)
	adxbdy := new(big.Int).Mul(adx, bdy)
	bdxady := new(big.Int).Mul(bdx, ady)

	alift := new(big.Int).Add(new(big.Int).Mul(adx, adx), new(big.Int).Mul(ady, ady))
	blift := new(big.Int).Add(new(big.Int).Mul(bdx, bdx), new(big.Int).Mul(bdy, bdy))
	clift := new(big.Int).Add(new(big.Int).Mul(cdx, cdx), new(big.Int).Mul(cdy, cdy))

	det := new(big.Int).Mul(alift, new(big.Int).Sub(bdxcdy, cdxbdy))
	det.Add(det, new(big.Int).Mul(blift, new(big.Int).Sub(cdxady, adxcdy)))
	det.Add(det, new(big.Int).Mul(clift, new(big.Int).Sub(adxbdy, bdxady)))
	return det.Sign()
}

// ---- naive float64-only predicates (deliberately unguarded) ----

func orient2dNaive(a, b, c Point) int {
	ax, ay := float64(a.X), float64(a.Y)
	bx, by := float64(b.X), float64(b.Y)
	cx, cy := float64(c.X), float64(c.Y)
	det := (ax-cx)*(by-cy) - (ay-cy)*(bx-cx)
	switch {
	case det > 0:
		return 1
	case det < 0:
		return -1
	default:
		return 0
	}
}

func incircleNaive(a, b, c, d Point) int {
	if orient2dNaive(a, b, c) < 0 {
		a, b = b, a
	}
	ax, ay := float64(a.X), float64(a.Y)
	bx, by := float64(b.X), float64(b.Y)
	cx, cy := float64(c.X), float64(c.Y)
	dx, dy := float64(d.X), float64(d.Y)
	adx, ady := ax-dx, ay-dy
	bdx, bdy := bx-dx, by-dy
	cdx, cdy := cx-dx, cy-dy
	det := (adx*adx+ady*ady)*(bdx*cdy-cdx*bdy) +
		(bdx*bdx+bdy*bdy)*(cdx*ady-adx*cdy) +
		(cdx*cdx+cdy*cdy)*(adx*bdy-bdx*ady)
	switch {
	case det > 0:
		return 1
	case det < 0:
		return -1
	default:
		return 0
	}
}

func absf(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

// exactFloatMax is the largest magnitude for which every int64 maps exactly
// to a float64. Above it the filter's error analysis is invalid and we must
// use the exact fallback.
const exactFloatMax = int64(1) << 53

func filterSafe(vals ...int64) bool {
	for _, v := range vals {
		if v > exactFloatMax || v < -exactFloatMax {
			return false
		}
	}
	return true
}

// Predicates bundles the two geometric tests so the same triangulator can be
// driven by either the exact or the naive implementation.
type Predicates struct {
	Orient2D func(a, b, c Point) int
	InCircle func(a, b, c, d Point) int
}

var ExactPredicates = Predicates{Orient2D: orient2d, InCircle: incircle}
var NaivePredicates = Predicates{Orient2D: orient2dNaive, InCircle: incircleNaive}
```

### 3.3 `triangulate.go` — Bowyer–Watson with walking + cavity BFS

```go
package main

type triangle struct {
	v     [3]int // vertex ids, CCW
	n     [3]int // neighbour opposite v[i]
	alive bool
}

func (t *triangle) edge(i int) (int, int) {
	return t.v[(i+1)%3], t.v[(i+2)%3]
}

type Delaunay struct {
	pts   []Point
	tris  []triangle
	pred  Predicates
	last  int
	dup   map[Point]int
	free  []int
	super [3]int
	// diagnostics
	WalkSteps int
	// operation budget (0 = unlimited); bounds the broken naive run.
	maxOps int
	ops    int
}

func (d *Delaunay) tick() {
	if d.maxOps <= 0 {
		return
	}
	d.ops++
	if d.ops > d.maxOps {
		panic("operation budget exceeded (non-termination / blow-up)")
	}
}

// NewDelaunay creates the enclosing super-triangle for the given points.
func NewDelaunay(points []Point, pred Predicates) *Delaunay {
	d := &Delaunay{pred: pred, dup: map[Point]int{}, last: -1}
	d.buildSuper(points)
	return d
}

func (d *Delaunay) SetMaxOps(n int) { d.maxOps = n }

func (d *Delaunay) buildSuper(points []Point) {
	if len(points) == 0 {
		points = []Point{{0, 0}}
	}
	minx, miny := points[0].X, points[0].Y
	maxx, maxy := points[0].X, points[0].Y
	for _, p := range points[1:] {
		if p.X < minx { minx = p.X }
		if p.X > maxx { maxx = p.X }
		if p.Y < miny { miny = p.Y }
		if p.Y > maxy { maxy = p.Y }
	}
	dx, dy := maxx-minx, maxy-miny
	dd := dx
	if dy > dd { dd = dy }
	if dd == 0 { dd = 1 }

	// Generous padding: obtuse hull triangles can have circumradii ~100x the
	// bounding box. Clamp to avoid int64 overflow; the predicates fall back to
	// big.Int for any coordinate beyond 2^53.
	const coordLimit = int64(1) << 62
	pad := dd
	if pad > coordLimit/(1<<20) {
		pad = coordLimit
	} else {
		pad *= 1 << 20
	}
	if pad < 1<<30 { pad = 1 << 30 }
	if minx-pad < -coordLimit { pad = minx + coordLimit }
	if maxx+pad > coordLimit {
		if p := coordLimit - maxx; p < pad { pad = p }
	}
	if pad < 1 { pad = 1 }

	s0 := Point{minx - pad, miny - pad}
	s1 := Point{maxx + pad, miny - pad}
	s2 := Point{(minx + maxx) / 2, maxy + pad}

	d.pts = append(d.pts, s0, s1, s2)
	d.super = [3]int{0, 1, 2}
	d.tris = append(d.tris, triangle{v: [3]int{0, 1, 2}, n: [3]int{-1, -1, -1}, alive: true})
	d.last = 0
}

func (d *Delaunay) newTri(v [3]int) int {
	t := triangle{v: v, n: [3]int{-1, -1, -1}, alive: true}
	if len(d.free) > 0 {
		i := d.free[len(d.free)-1]
		d.free = d.free[:len(d.free)-1]
		d.tris[i] = t
		return i
	}
	d.tris = append(d.tris, t)
	return len(d.tris) - 1
}

func (d *Delaunay) findEdge(t, a, b int) int {
	tr := &d.tris[t]
	for i := 0; i < 3; i++ {
		x, y := tr.edge(i)
		if (x == a && y == b) || (x == b && y == a) {
			return i
		}
	}
	return -1
}

// Insert adds a single real point, ignoring duplicates.
func (d *Delaunay) Insert(p Point) {
	d.tick()
	if _, ok := d.dup[p]; ok {
		return
	}
	idx := len(d.pts)
	d.pts = append(d.pts, p)
	d.dup[p] = idx

	t := d.locate(p)
	if t < 0 {
		panic("point not located inside super-triangle")
	}
	bad := d.collectBad(t, p)
	d.retriangulate(bad, idx)
}

// locate: visibility walk, with an exhaustive fallback to guarantee
// termination on pathological (naive) input.
func (d *Delaunay) locate(p Point) int {
	t := d.last
	if t < 0 || !d.tris[t].alive {
		t = d.firstAlive()
	}
	maxSteps := 8*len(d.tris) + 64
	for steps := 0; steps < maxSteps; steps++ {
		d.tick()
		d.WalkSteps++
		tr := &d.tris[t]
		c0 := d.pred.Orient2D(d.pts[tr.v[1]], d.pts[tr.v[2]], p)
		c1 := d.pred.Orient2D(d.pts[tr.v[2]], d.pts[tr.v[0]], p)
		c2 := d.pred.Orient2D(d.pts[tr.v[0]], d.pts[tr.v[1]], p)
		if c0 >= 0 && c1 >= 0 && c2 >= 0 {
			d.last = t
			return t
		}
		moved := false
		if c0 < 0 && tr.n[0] >= 0 {
			t = tr.n[0]; moved = true
		} else if c1 < 0 && tr.n[1] >= 0 {
			t = tr.n[1]; moved = true
		} else if c2 < 0 && tr.n[2] >= 0 {
			t = tr.n[2]; moved = true
		}
		if !moved { break }
	}
	return d.locateBrute(p)
}

func (d *Delaunay) firstAlive() int {
	for i := range d.tris {
		if d.tris[i].alive { return i }
	}
	return -1
}

func (d *Delaunay) locateBrute(p Point) int {
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		tr := &d.tris[i]
		c0 := d.pred.Orient2D(d.pts[tr.v[1]], d.pts[tr.v[2]], p)
		c1 := d.pred.Orient2D(d.pts[tr.v[2]], d.pts[tr.v[0]], p)
		c2 := d.pred.Orient2D(d.pts[tr.v[0]], d.pts[tr.v[1]], p)
		if c0 >= 0 && c1 >= 0 && c2 >= 0 {
			d.last = i
			return i
		}
	}
	return -1
}

// collectBad returns every triangle whose circumcircle strictly contains p,
// reachable from the containing triangle.
func (d *Delaunay) collectBad(start int, p Point) []int {
	bad := make([]bool, len(d.tris))
	stack := []int{start}
	var out []int
	for len(stack) > 0 {
		d.tick()
		t := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if t < 0 || bad[t] || !d.tris[t].alive { continue }
		tr := &d.tris[t]
		if d.pred.InCircle(d.pts[tr.v[0]], d.pts[tr.v[1]], d.pts[tr.v[2]], p) > 0 {
			bad[t] = true
			out = append(out, t)
			for i := 0; i < 3; i++ {
				if tr.n[i] >= 0 { stack = append(stack, tr.n[i]) }
			}
		}
	}
	return out
}

type boundaryEdge struct {
	a, b int // directed edge of the bad triangle: interior on the left
	good int // adjacent non-bad triangle, or -1
}

// retriangulate removes the bad triangles and reconnects the cavity to p.
func (d *Delaunay) retriangulate(bad []int, idx int) {
	badSet := make(map[int]bool, len(bad))
	for _, t := range bad { badSet[t] = true }

	var bedges []boundaryEdge
	for _, t := range bad {
		tr := &d.tris[t]
		for i := 0; i < 3; i++ {
			n := tr.n[i]
			if n >= 0 && badSet[n] { continue }
			a, b := tr.edge(i)
			bedges = append(bedges, boundaryEdge{a: a, b: b, good: n})
		}
	}

	for _, t := range bad {
		d.tris[t].alive = false
		d.free = append(d.free, t)
	}

	type loc struct{ t, e int }
	edgeMap := make(map[[2]int]loc, len(bedges)*2)
	var newTris []int
	for _, be := range bedges {
		v := [3]int{be.a, be.b, idx}
		if d.pred.Orient2D(d.pts[be.a], d.pts[be.b], d.pts[idx]) < 0 {
			v = [3]int{be.b, be.a, idx}
		}
		ti := d.newTri(v)
		newTris = append(newTris, ti)

		if be.good >= 0 {
			d.tris[ti].n[2] = be.good
			e := d.findEdge(be.good, be.a, be.b)
			if e >= 0 { d.tris[be.good].n[e] = ti }
		}
	}

	for _, ti := range newTris {
		tr := &d.tris[ti]
		for e := 0; e < 2; e++ { // edges 0 and 1 touch idx
			a, b := tr.edge(e)
			key := [2]int{a, b}
			if a > b { key = [2]int{b, a} }
			if other, ok := edgeMap[key]; ok {
				tr.n[e] = other.t
				d.tris[other.t].n[other.e] = ti
			} else {
				edgeMap[key] = loc{t: ti, e: e}
			}
		}
	}
	if len(newTris) > 0 { d.last = newTris[0] }
}

// RemoveSuper marks every triangle incident to a super vertex as dead.
func (d *Delaunay) RemoveSuper() {
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		tr := &d.tris[i]
		if tr.v[0] < 3 || tr.v[1] < 3 || tr.v[2] < 3 {
			d.tris[i].alive = false
		}
	}
}

func (d *Delaunay) Triangles() [][3]Point {
	var out [][3]Point
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		tr := &d.tris[i]
		out = append(out, [3]Point{d.pts[tr.v[0]], d.pts[tr.v[1]], d.pts[tr.v[2]]})
	}
	return out
}

func (d *Delaunay) TriangleIDs() [][3]int {
	var out [][3]int
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		out = append(out, d.tris[i].v)
	}
	return out
}
