### 3.4 `oracle.go` — brute-force verifier

```go
package main

import (
	"fmt"
	"math/big"
	"sort"
)

type OracleResult struct {
	Triangles         int
	CircumcircleTris  int
	CircumcircleFull  bool
	EmptyCircumcircle bool
	LocalDelaunay     bool
	EdgeOptimality    bool
	ValidCoverage     bool
	StructuralValid   bool
	FirstFailure      string
}

func (r OracleResult) Pass() bool {
	return r.EmptyCircumcircle && r.LocalDelaunay && r.EdgeOptimality &&
		r.ValidCoverage && r.StructuralValid
}

// Full brute force: every triangle vs every point.
func VerifyTriangulation(d *Delaunay, points []Point) OracleResult {
	return verify(d, points, 0, true)
}

// Sampled empty-circle sweep + full O(E) local edge check; for huge inputs.
func VerifyTriangulationSampled(d *Delaunay, points []Point, triSample int, bruteFlips bool) OracleResult {
	return verify(d, points, triSample, bruteFlips)
}

func verify(d *Delaunay, points []Point, triSample int, bruteFlips bool) OracleResult {
	res := OracleResult{true, true, true, true, true, true, true, true, true, ""}
	// (field order above is illustrative; real initializer below)
	res = OracleResult{EmptyCircumcircle: true, LocalDelaunay: true, EdgeOptimality: true,
		ValidCoverage: true, StructuralValid: true}
	fail := func(msg string) {
		if res.FirstFailure == "" { res.FirstFailure = msg }
	}

	var alive []int
	for i := range d.tris {
		if d.tris[i].alive { alive = append(alive, i) }
	}
	res.Triangles = len(alive)

	// 1. Structural: strictly CCW, no duplicate triangles.
	seen := map[[3]int]bool{}
	for _, ti := range alive {
		v := d.tris[ti].v
		a, b, c := d.pts[v[0]], d.pts[v[1]], d.pts[v[2]]
		if orient2d(a, b, c) <= 0 {
			res.StructuralValid = false
			fail(fmt.Sprintf("triangle %v is not strictly CCW", v))
		}
		key := v
		if key[0] > key[1] { key[0], key[1] = key[1], key[0] }
		if key[1] > key[2] { key[1], key[2] = key[2], key[1] }
		if key[0] > key[1] { key[0], key[1] = key[1], key[0] }
		if seen[key] {
			res.StructuralValid = false
			fail(fmt.Sprintf("duplicate triangle %v", v))
		}
		seen[key] = true
	}

	// 2. Local Delaunay for every internal edge (O(E)).
	for _, ti := range alive {
		tr := &d.tris[ti]
		for e := 0; e < 3; e++ {
			n := tr.n[e]
			if n < 0 || !d.tris[n].alive || n < ti { continue }
			a, b := tr.edge(e)
			opp1 := tr.v[e]
			var opp2 int
			for k := 0; k < 3; k++ {
				if d.tris[n].v[k] != a && d.tris[n].v[k] != b {
					opp2 = d.tris[n].v[k]; break
				}
			}
			pa, pb := d.pts[a], d.pts[b]
			if incircle(pa, pb, d.pts[opp1], d.pts[opp2]) > 0 {
				res.LocalDelaunay = false
				fail(fmt.Sprintf("edge %v-%v not locally Delaunay (opposite %v inside)", pa, pb, d.pts[opp2]))
			}
			if incircle(pa, pb, d.pts[opp2], d.pts[opp1]) > 0 {
				res.LocalDelaunay = false
				fail(fmt.Sprintf("edge %v-%v not locally Delaunay (opposite %v inside)", pa, pb, d.pts[opp1]))
			}
		}
	}
	res.EdgeOptimality = res.LocalDelaunay

	// 3. Empty circumcircle (full, or sampled for very large inputs).
	sample := alive
	if triSample > 0 && triSample < len(alive) {
		step := len(alive) / triSample
		if step < 1 { step = 1 }
		sample = nil
		for i := 0; i < len(alive) && len(sample) < triSample; i += step {
			sample = append(sample, alive[i])
		}
	}
	res.CircumcircleTris = len(sample)
	res.CircumcircleFull = len(sample) == len(alive)
	for _, ti := range sample {
		v := d.tris[ti].v
		a, b, c := d.pts[v[0]], d.pts[v[1]], d.pts[v[2]]
		for _, p := range points {
			if p == a || p == b || p == c { continue }
			if incircle(a, b, c, p) > 0 {
				res.EmptyCircumcircle = false
				fail(fmt.Sprintf("point %v strictly inside circumcircle of %v %v %v", p, a, b, c))
				break
			}
		}
		if !res.EmptyCircumcircle { break }
	}

	// 4. Optional full flip search over all candidate point pairs (small n).
	if bruteFlips && len(points) <= 400 {
		edgeSet := map[[2]int]bool{}
		for _, ti := range alive {
			tr := &d.tris[ti]
			for e := 0; e < 3; e++ {
				a, b := tr.edge(e)
				if a > b { a, b = b, a }
				edgeSet[[2]int{a, b}] = true
			}
		}
		for key := range edgeSet {
			pa, pb := d.pts[key[0]], d.pts[key[1]]
			for ci := range points {
				c := points[ci]
				if c == pa || c == pb { continue }
				sc := orient2d(pa, pb, c)
				if sc == 0 { continue }
				for di := range points {
					e := points[di]
					if e == pa || e == pb || e == c { continue }
					se := orient2d(pa, pb, e)
					if se == 0 || se == sc { continue }
					if incircle(pa, pb, c, e) > 0 {
						res.EdgeOptimality = false
						fail(fmt.Sprintf("flippable pair: edge %v-%v, %v inside circumcircle(%v,%v,%v)", pa, pb, e, pa, pb, c))
						break
					}
				}
				if !res.EdgeOptimality { break }
			}
			if !res.EdgeOptimality { break }
		}
	}

	// 5. Exact coverage: sum of triangle areas == convex hull area.
	hullArea := convexHullArea2(points)
	sumArea := big.NewInt(0)
	for _, ti := range alive {
		v := d.tris[ti].v
		sumArea.Add(sumArea, triArea2(d.pts[v[0]], d.pts[v[1]], d.pts[v[2]]))
	}
	if hullArea.Cmp(sumArea) != 0 {
		res.ValidCoverage = false
		fail(fmt.Sprintf("area mismatch: hull=%s triangulated=%s", hullArea.String(), sumArea.String()))
	}
	return res
}

func triArea2(a, b, c Point) *big.Int {
	bax := new(big.Int).Sub(big.NewInt(b.X), big.NewInt(a.X))
	bay := new(big.Int).Sub(big.NewInt(b.Y), big.NewInt(a.Y))
	cax := new(big.Int).Sub(big.NewInt(c.X), big.NewInt(a.X))
	cay := new(big.Int).Sub(big.NewInt(c.Y), big.NewInt(a.Y))
	return new(big.Int).Sub(new(big.Int).Mul(bax, cay), new(big.Int).Mul(bay, cax))
}

func convexHullArea2(points []Point) *big.Int {
	h := convexHull(points)
	if len(h) < 3 { return big.NewInt(0) }
	s := big.NewInt(0)
	for i := range h {
		a := points[h[i]]
		b := points[h[(i+1)%len(h)]]
		s.Add(s, new(big.Int).Sub(
			new(big.Int).Mul(big.NewInt(a.X), big.NewInt(b.Y)),
			new(big.Int).Mul(big.NewInt(b.X), big.NewInt(a.Y))))
	}
	if s.Sign() < 0 { s.Neg(s) }
	return s
}

func convexHull(points []Point) []int {
	n := len(points)
	if n < 3 {
		out := make([]int, n)
		for i := range out { out[i] = i }
		return out
	}
	idx := make([]int, n)
	for i := range idx { idx[i] = i }
	sort.Slice(idx, func(i, j int) bool {
		a, b := points[idx[i]], points[idx[j]]
		if a.X != b.X { return a.X < b.X }
		return a.Y < b.Y
	})
	cross := func(o, a, b int) int { return orient2d(points[o], points[a], points[b]) }
	var lower []int
	for _, i := range idx {
		for len(lower) >= 2 && cross(lower[len(lower)-2], lower[len(lower)-1], i) <= 0 {
			lower = lower[:len(lower)-1]
		}
		lower = append(lower, i)
	}
	var upper []int
	for k := len(idx) - 1; k >= 0; k-- {
		i := idx[k]
		for len(upper) >= 2 && cross(upper[len(upper)-2], upper[len(upper)-1], i) <= 0 {
			upper = upper[:len(upper)-1]
		}
		upper = append(upper, i)
	}
	lower = lower[:len(lower)-1]
	upper = upper[:len(upper)-1]
	return append(lower, upper...)
}
