// TestUnsoundEdgeDetectorRegression pins the case that defeats a naive
// "did the traceback touch the band edge?" detector: the banded optimum can
// stay strictly inside the band while the true optimum leaves it. The exact
// certificate must still report clipping.
func TestUnsoundEdgeDetectorRegression(t *testing.T) {
	cfg := DefaultConfig()
	a := "TACTGAGTATCACTAGCTTAA"
	b := "CGCACTGGGCCAGTCGTAATGGGTC"
	cfg.Band = 5 // full optimum reaches |i-j| = 6

	full, err := AlignFull(a, b, cfg)
	if err != nil {
		t.Fatal(err)
	}
	if md := MaxDiag(full.Path); md != 6 {
		t.Fatalf("construction changed: full excursion = %d, want 6", md)
	}

	if _, err := AlignBanded(a, b, cfg); !errors.Is(err, ErrClipped) {
		t.Fatalf("band=5 silently returned a wrong answer: %v", err)
	}

	// With a band that contains the optimum, we get the exact answer.
	cfg.Band = 6
	res, err := AlignBanded(a, b, cfg)
	if err != nil {
		t.Fatalf("band=6 should contain the optimum: %v", err)
	}
	if res.Score != full.Score || res.CIGAR != full.CIGAR {
		t.Fatalf("band=6 mismatch: got %d/%s want %d/%s", res.Score, res.CIGAR, full.Score, full.CIGAR)
	}
}

