### 2.2 Core algorithm — `arborescence.go`

The implementation extends the standard iterative contraction. Crucially, `mres[component]` accumulates `in[v]` every round, which telescopes to the *true* minimum incoming weight of each component at the moment it is resolved (because the stored weights carry a per-node offset). Supernode components become the laminar `z`-sets with `z = mres`; vertex potentials are `π_v = Σ mres` along the component chain.

```go
// Package arb implements the Chu-Liu/Edmonds minimum spanning arborescence
// algorithm for int64-weighted directed graphs, together with an exact
// LP-duality certificate.
//
// The certificate is the dual of Edmonds' branching polytope:
//
//	primal:  min  sum_e w_e x_e
//	         s.t. sum_{e in delta^-(v)} x_e = 1        for every v != root
//	              x(E(S)) <= |S|-1                    for every nonempty S
//	              x_e >= 0
//
//	dual:    max  sum_{v != root} pi_v - sum_S (|S|-1) z_S
//	         s.t. w_e >= pi_v - sum_{S superset of e} z_S   for every e=(u,v)
//	              z_S >= 0,  pi_v free
//
// The sets S with z_S>0 can be chosen laminar; the algorithm below produces
// exactly the contraction supernodes.  A pure vertex-potential certificate is
// impossible in general (a cycle forces a positive z on its set), so the
// certificate carries the laminar family of z-sets plus the induced vertex
// potentials pi_v.
package arb

const infWeight = int64(1) << 62

// Edge is a directed weighted edge.  U and V are vertex indices in the
// original numbering.
type Edge struct {
	U, V int
	W    int64
}

// Certificate is the LP-duality certificate produced by MinArborescence.
type Certificate struct {
	// Pi[v] is the free dual potential of vertex v (v != root).
	Pi []int64
	// VertexSet[v] is the index of the smallest z-set containing v, or -1.
	VertexSet []int
	// SetParent[s] is the index of the smallest z-set strictly containing set
	// s, or -1 for a top level set.
	SetParent []int
	// SetZ[s] >= 0 is the dual value of set s.
	SetZ []int64
}

// Result is the output of MinArborescence.
type Result struct {
	Weight   int64 // weight of the minimum arborescence
	Rounds   int   // number of contraction rounds performed
	Parent   []int // Parent[v] = parent vertex of v, -1 for root / unreachable
	TreeEdge []int // TreeEdge[v] = original edge index entering v, -1 otherwise
	Cert     *Certificate
	Reach    []bool // reachability from the root
}

type curEdge struct {
	u, v int
	w    int64
	id   int // original edge index
}

// MinArborescence computes a minimum weight spanning arborescence rooted at
// root.  All vertices reachable from root are spanned; unreachable vertices
// are ignored (no arborescence can span them).  Self loops and edges entering
// the root are ignored.  It returns nil if the root is out of range.
func MinArborescence(n, root int, edges []Edge) *Result {
	if root < 0 || root >= n {
		return nil
	}

	// ---- reachability from the root --------------------------------
	adj := make([][]int, n)
	for _, e := range edges {
		if e.U >= 0 && e.U < n && e.V >= 0 && e.V < n {
			adj[e.U] = append(adj[e.U], e.V)
		}
	}
	reach := make([]bool, n)
	reach[root] = true
	stack := []int{root}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, v := range adj[u] {
			if !reach[v] {
				reach[v] = true
				stack = append(stack, v)
			}
		}
	}

	// ---- relabel reachable vertices to 0..nn-1 ---------------------
	idx := make([]int, n)
	for i := range idx {
		idx[i] = -1
	}
	var verts []int
	for v := 0; v < n; v++ {
		if reach[v] {
			idx[v] = len(verts)
			verts = append(verts, v)
		}
	}
	nn := len(verts)
	if nn == 0 { // cannot happen: root reachable
		return nil
	}
	rootC := idx[root]

	// ---- relabelled edge list (drop self loops and edges into root) ----
	edgeHead := make([]int, len(edges)) // original edge -> relabelled head
	edgeTail := make([]int, len(edges)) // original edge -> relabelled tail
	for i := range edgeHead {
		edgeHead[i] = -1
		edgeTail[i] = -1
	}
	var cur []curEdge
	for i, e := range edges {
		if e.U < 0 || e.U >= n || e.V < 0 || e.V >= n {
			continue
		}
		if !reach[e.U] || !reach[e.V] {
			continue
		}
		u := idx[e.U]
		v := idx[e.V]
		if u == v { // self loop
			continue
		}
		if v == rootC { // edge into the root, never used
			continue
		}
		edgeHead[i] = v
		edgeTail[i] = u
		cur = append(cur, curEdge{u, v, e.W, i})
	}

	// ---- contraction state -----------------------------------------
	ncur := nn
	comp := make([]int, ncur) // current node -> component id
	for i := range comp {
		comp[i] = i
	}
	numComp := nn
	mres := make([]int64, numComp)     // accumulated true min-in weight per component
	parentComp := make([]int, numComp) // component -> containing supernode
	for i := range parentComp {
		parentComp[i] = -1
	}
	isSuper := make([]bool, numComp)
	members := make([][]int, numComp)     // supernode -> member components
	memberEdges := make([][]int, numComp) // supernode -> chosen edge per member
	baseEdge := make([]int, numComp)      // final component -> chosen entering edge
	for i := range baseEdge {
		baseEdge[i] = -1
	}

	var ans int64
	rounds := 0

	// reusable per-round buffers (sized to the original reachable count)
	inBuf := make([]int64, nn)
	preBuf := make([]int, nn)
	preEdgeBuf := make([]int, nn)
	idBuf := make([]int, nn)
	visBuf := make([]int, nn)

	for {
		in := inBuf[:ncur]
		pre := preBuf[:ncur]
		preEdge := preEdgeBuf[:ncur]
		for i := range in {
			in[i] = infWeight
			pre[i] = -1
			preEdge[i] = -1
		}
		for _, e := range cur {
			if e.w < in[e.v] {
				in[e.v] = e.w
				pre[e.v] = e.u
				preEdge[e.v] = e.id
			}
		}
		for v := 0; v < ncur; v++ {
			if v != rootC && in[v] == infWeight {
				// a reachable vertex lost all incoming edges: cannot happen
				return nil
			}
		}
		in[rootC] = 0

		// accumulate true minimum incoming values and the answer
		for v := 0; v < ncur; v++ {
			mres[comp[v]] += in[v]
			ans += in[v]
		}

		// ---- detect cycles in the functional graph pre[] ----------
		id := idBuf[:ncur]
		vis := visBuf[:ncur]
		for i := range id {
			id[i] = -1
			vis[i] = -1
		}
		numCycles := 0
		var cycles [][]int
		for i := 0; i < ncur; i++ {
			if i == rootC {
				continue
			}
			v := i
			for vis[v] != i && id[v] == -1 && v != rootC {
				vis[v] = i
				v = pre[v]
			}
			if v != rootC && id[v] == -1 {
				cyc := []int{}
				u := pre[v]
				for u != v {
					id[u] = numCycles
					cyc = append(cyc, u)
					u = pre[u]
				}
				id[v] = numCycles
				cyc = append(cyc, v)
				cycles = append(cycles, cyc)
				numCycles++
			}
		}

		if numCycles == 0 {
			for v := 0; v < ncur; v++ {
				if v != rootC {
					baseEdge[comp[v]] = preEdge[v]
				}
			}
			break
		}

		// assign compact ids: cycles 0..numCycles-1, others after
		next := numCycles
		for i := 0; i < ncur; i++ {
			if id[i] == -1 {
				id[i] = next
				next++
			}
		}
		newN := next
		rounds++

		// create one supernode per cycle
		superComp := make([]int, numCycles)
		for c := 0; c < numCycles; c++ {
			nc := numComp
			numComp++
			isSuper = append(isSuper, true)
			mres = append(mres, 0)
			parentComp = append(parentComp, -1)
			members = append(members, nil)
			memberEdges = append(memberEdges, nil)
			baseEdge = append(baseEdge, -1)
			superComp[c] = nc
		}

		newCompOfId := make([]int, newN)
		for i := 0; i < ncur; i++ {
			if id[i] < numCycles {
				newCompOfId[id[i]] = superComp[id[i]]
				parentComp[comp[i]] = superComp[id[i]]
			} else {
				newCompOfId[id[i]] = comp[i]
			}
		}
		for c := 0; c < numCycles; c++ {
			for _, node := range cycles[c] {
				members[superComp[c]] = append(members[superComp[c]], comp[node])
				memberEdges[superComp[c]] = append(memberEdges[superComp[c]], preEdge[node])
			}
		}

		// adjust and relabel edges, compacting in place
		wr := 0
		for i := 0; i < len(cur); i++ {
			e := cur[i]
			uu := id[e.u]
			vv := id[e.v]
			if uu == vv {
				continue
			}
			cur[wr] = curEdge{uu, vv, e.w - in[e.v], e.id}
			wr++
		}
		cur = cur[:wr]
		newComp := make([]int, newN)
		copy(newComp, newCompOfId)
		comp = newComp
		ncur = newN
		rootC = id[rootC]
	}

	// ---- build component potentials P[c] = mres[c] + P[parent] -------
	P := make([]int64, numComp)
	for c := numComp - 1; c >= 0; c-- {
		if parentComp[c] != -1 {
			P[c] = mres[c] + P[parentComp[c]]
		} else {
			P[c] = mres[c]
		}
	}

	// ---- compact list of z-sets (supernodes) --------------------------
	setIndex := make([]int, numComp)
	for i := range setIndex {
		setIndex[i] = -1
	}
	var setList []int
	for c := 0; c < numComp; c++ {
		if isSuper[c] {
			setIndex[c] = len(setList)
			setList = append(setList, c)
		}
	}
	m := len(setList)
	cert := &Certificate{
		Pi:        make([]int64, n),
		VertexSet: make([]int, n),
		SetParent: make([]int, m),
		SetZ:      make([]int64, m),
	}
	for i := range cert.VertexSet {
		cert.VertexSet[i] = -1
	}
	for v := 0; v < nn; v++ {
		cert.Pi[verts[v]] = P[v]
	}
	for si, c := range setList {
		cert.SetZ[si] = mres[c]
		if parentComp[c] != -1 {
			cert.SetParent[si] = setIndex[parentComp[c]]
		} else {
			cert.SetParent[si] = -1
		}
	}
	for v := 0; v < nn; v++ {
		if parentComp[v] != -1 {
			cert.VertexSet[verts[v]] = setIndex[parentComp[v]]
		}
	}

	// ---- reconstruct the arborescence --------------------------------
	parentRel := make([]int, nn)
	for i := range parentRel {
		parentRel[i] = -1
	}
	var expand func(X, edgeID int)
	expand = func(X, edgeID int) {
		if edgeID < 0 {
			return
		}
		if !isSuper[X] {
			// singleton component: X is the relabelled vertex
			parentRel[X] = edgeTail[edgeID]
			return
		}
		head := edgeHead[edgeID]
		c := head
		for parentComp[c] != X {
			c = parentComp[c]
			if c == -1 {
				// certificate/construction inconsistency
				return
			}
		}
		mem := members[X]
		me := memberEdges[X]
		for i := 0; i < len(mem); i++ {
			if mem[i] == c {
				expand(mem[i], edgeID)
			} else {
				expand(mem[i], me[i])
			}
		}
	}
	for c := 0; c < numComp; c++ {
		if parentComp[c] == -1 && baseEdge[c] != -1 {
			expand(c, baseEdge[c])
		}
	}

	res := &Result{
		Weight:   ans,
		Rounds:   rounds,
		Parent:   make([]int, n),
		TreeEdge: make([]int, n),
		Cert:     cert,
		Reach:    reach,
	}
	for i := range res.Parent {
		res.Parent[i] = -1
		res.TreeEdge[i] = -1
	}
	for v := 0; v < nn; v++ {
		if parentRel[v] != -1 {
			res.Parent[verts[v]] = verts[parentRel[v]]
		}
	}
	// map tree edges by expanding again (store in one pass)
	var fillEdge func(X, edgeID int)
	fillEdge = func(X, edgeID int) {
		if edgeID < 0 {
			return
		}
		if !isSuper[X] {
			res.TreeEdge[verts[X]] = edgeID
			return
		}
		head := edgeHead[edgeID]
		c := head
		for parentComp[c] != X {
			c = parentComp[c]
			if c == -1 {
				return
			}
		}
		mem := members[X]
		me := memberEdges[X]
		for i := 0; i < len(mem); i++ {
			if mem[i] == c {
				fillEdge(mem[i], edgeID)
			} else {
				fillEdge(mem[i], me[i])
			}
		}
	}
	for c := 0; c < numComp; c++ {
		if parentComp[c] == -1 && baseEdge[c] != -1 {
			fillEdge(c, baseEdge[c])
		}
	}

	return res
}
```

### 2.3 Certificate verifier — `verify.go`

The verifier is independent of the solver: it recomputes reachability, the tree weight, the laminar sizes, `pre[]` and LCA, then checks dual feasibility, objective equality, and complementary slackness. `Z(e) = pre[LCA(u,v)]` is the sum of `z` over sets containing both endpoints.

```go
package arb

import "fmt"

// Verify checks an arborescence and its LP-duality certificate against the
// graph.  It returns nil iff the certificate proves that res is a minimum
// weight spanning arborescence rooted at root.
//
// The check runs in O((V+E) log V).
func Verify(n, root int, edges []Edge, res *Result) error {
	if res == nil || res.Cert == nil {
		return fmt.Errorf("nil result or certificate")
	}
	if root < 0 || root >= n {
		return fmt.Errorf("root out of range")
	}
	cert := res.Cert

	// ---- reachability ------------------------------------------------
	adj := make([][]int, n)
	for _, e := range edges {
		if e.U >= 0 && e.U < n && e.V >= 0 && e.V < n {
			adj[e.U] = append(adj[e.U], e.V)
		}
	}
	reach := make([]bool, n)
	reach[root] = true
	stack := []int{root}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, v := range adj[u] {
			if !reach[v] {
				reach[v] = true
				stack = append(stack, v)
			}
		}
	}

	// ---- 1. arborescence check ---------------------------------------
	treeWeight := int64(0)
	for v := 0; v < n; v++ {
		if !reach[v] || v == root {
			if res.Parent[v] != -1 || res.TreeEdge[v] != -1 {
				return fmt.Errorf("vertex %d should have no parent", v)
			}
			continue
		}
		eid := res.TreeEdge[v]
		if eid < 0 || eid >= len(edges) {
			return fmt.Errorf("vertex %d has no tree edge", v)
		}
		e := edges[eid]
		if e.V != v {
			return fmt.Errorf("tree edge %d does not enter vertex %d", eid, v)
		}
		if e.U != res.Parent[v] {
			return fmt.Errorf("tree edge %d tail %d != parent %d of %d", eid, e.U, res.Parent[v], v)
		}
		if !reach[e.U] {
			return fmt.Errorf("tree edge %d has unreachable tail", eid)
		}
		treeWeight += e.W
	}
	for v := 0; v < n; v++ {
		if !reach[v] {
			continue
		}
		steps := 0
		u := v
		for u != root {
			if u < 0 || u >= n || !reach[u] {
				return fmt.Errorf("parent chain of %d leaves reachable set", v)
			}
			u = res.Parent[u]
			steps++
			if steps > n {
				return fmt.Errorf("cycle in parent pointers at %d", v)
			}
		}
	}

	// ---- build laminar tree ------------------------------------------
	m := len(cert.SetZ)
	if len(cert.SetParent) != m || len(cert.VertexSet) != n || len(cert.Pi) != n {
		return fmt.Errorf("certificate arrays have inconsistent lengths")
	}
	virtual := n + m
	N := n + m + 1
	par := make([]int, N)
	for i := range par {
		par[i] = -1
	}
	for v := 0; v < n; v++ {
		vs := cert.VertexSet[v]
		if vs < -1 || vs >= m {
			return fmt.Errorf("vertex %d has bad VertexSet %d", v, vs)
		}
		if vs == -1 {
			par[v] = virtual
		} else {
			par[v] = n + vs
		}
	}
	for s := 0; s < m; s++ {
		if cert.SetZ[s] < 0 {
			return fmt.Errorf("set %d has negative z %d", s, cert.SetZ[s])
		}
		ps := cert.SetParent[s]
		if ps < -1 || ps >= m {
			return fmt.Errorf("set %d has bad SetParent %d", s, ps)
		}
		if ps == -1 {
			par[n+s] = virtual
		} else {
			par[n+s] = n + ps
		}
	}
	par[virtual] = virtual

	// ancestor / depth / pre computation (iterative DFS from virtual root)
	depth := make([]int, N)
	for i := range depth {
		depth[i] = -1
	}
	pre := make([]int64, N) // sum of z on root..node
	order := make([]int, 0, N)
	children := make([][]int, N)
	for i := 0; i < N; i++ {
		if i == virtual {
			continue
		}
		p := par[i]
		if p < 0 || p >= N {
			return fmt.Errorf("node %d has invalid parent", i)
		}
		children[p] = append(children[p], i)
	}
	stack2 := []int{virtual}
	depth[virtual] = 0
	for len(stack2) > 0 {
		u := stack2[len(stack2)-1]
		stack2 = stack2[:len(stack2)-1]
		order = append(order, u)
		for _, c := range children[u] {
			depth[c] = depth[u] + 1
			pre[c] = pre[u]
			if c >= n { // set node
				pre[c] += cert.SetZ[c-n]
			}
			stack2 = append(stack2, c)
		}
	}
	if len(order) != N {
		return fmt.Errorf("laminar structure is not a tree")
	}

	// ---- set membership / sizes --------------------------------------
	size := make([]int, m)
	for v := 0; v < n; v++ {
		if !reach[v] {
			u := v
			seen := 0
			for u != virtual {
				if u >= n {
					return fmt.Errorf("unreachable vertex %d lies in z-set %d", v, u-n)
				}
				p := par[u]
				if p == u {
					break
				}
				u = p
				seen++
				if seen > N {
					return fmt.Errorf("cycle in laminar tree")
				}
			}
			continue
		}
		u := v
		seen := 0
		for u != virtual {
			if u >= n {
				if u-n == -1 {
					break
				}
				size[u-n]++
				if v == root {
					return fmt.Errorf("root is contained in z-set %d", u-n)
				}
			}
			p := par[u]
			if p == u {
				break
			}
			u = p
			seen++
			if seen > N {
				return fmt.Errorf("cycle in laminar tree")
			}
		}
	}

	// ---- binary lifting for LCA --------------------------------------
	LOG := 1
	for (1 << LOG) < N {
		LOG++
	}
	up := make([][]int, LOG)
	up[0] = make([]int, N)
	copy(up[0], par)
	for k := 1; k < LOG; k++ {
		up[k] = make([]int, N)
		for i := 0; i < N; i++ {
			up[k][i] = up[k-1][up[k-1][i]]
		}
	}
	lca := func(a, b int) int {
		if depth[a] < depth[b] {
			a, b = b, a
		}
		d := depth[a] - depth[b]
		for k := 0; k < LOG; k++ {
			if d&(1<<k) != 0 {
				a = up[k][a]
			}
		}
		if a == b {
			return a
		}
		for k := LOG - 1; k >= 0; k-- {
			if up[k][a] != up[k][b] {
				a = up[k][a]
				b = up[k][b]
			}
		}
		return up[0][a]
	}

	// ---- 3. dual feasibility -----------------------------------------
	for ei, e := range edges {
		if e.U < 0 || e.U >= n || e.V < 0 || e.V >= n {
			continue
		}
		if !reach[e.U] || !reach[e.V] {
			continue
		}
		v := e.V
		if v == root {
			continue
		}
		if e.U == e.V {
			continue
		}
		l := lca(e.U, e.V)
		zcommon := pre[l]
		reduced := e.W - cert.Pi[v] + zcommon
		if reduced < 0 {
			return fmt.Errorf("edge %d (%d->%d, w=%d) violates dual: reduced cost %d < 0",
				ei, e.U, e.V, e.W, reduced)
		}
	}

	// ---- 4. objective equality ---------------------------------------
	var dualObj int64
	for v := 0; v < n; v++ {
		if reach[v] && v != root {
			dualObj += cert.Pi[v]
		}
	}
	for s := 0; s < m; s++ {
		if size[s] == 0 {
			if cert.SetZ[s] != 0 {
				return fmt.Errorf("set %d is empty but has z=%d", s, cert.SetZ[s])
			}
			continue
		}
		dualObj -= int64(size[s]-1) * cert.SetZ[s]
	}
	if dualObj != treeWeight {
		return fmt.Errorf("dual objective %d != arborescence weight %d", dualObj, treeWeight)
	}

	// tree edges must be tight (complementary slackness)
	for v := 0; v < n; v++ {
		if !reach[v] || v == root {
			continue
		}
		e := edges[res.TreeEdge[v]]
		l := lca(e.U, e.V)
		reduced := e.W - cert.Pi[v] + pre[l]
		if reduced != 0 {
			return fmt.Errorf("tree edge %d is not tight: reduced cost %d", res.TreeEdge[v], reduced)
		}
	}

	return nil
}
```

### 2.4 Brute-force reference — `brute.go`

Exact Held–Karp subset DP over the reachable set, `dp[S] = min_{v∈S\{r}, u∈S\{v}} dp[S\{v}] + w(u,v)`. `O(2^|R| · |R|²)`.

```go
package arb

// BruteForce computes the exact minimum spanning arborescence weight on all
// vertices reachable from root by subset DP (Held-Karp style):
//
//	dp[S] = min over v in S\{root}, u in S\{v} of dp[S\{v}] + w(u,v)
//
// where w(u,v) is the cheapest edge from u to v.
func BruteForce(n, root int, edges []Edge) (int64, bool) {
	if root < 0 || root >= n {
		return 0, false
	}
	adj := make([][]int, n)
	for _, e := range edges {
		if e.U >= 0 && e.U < n && e.V >= 0 && e.V < n {
			adj[e.U] = append(adj[e.U], e.V)
		}
	}
	reach := make([]bool, n)
	reach[root] = true
	st := []int{root}
	for len(st) > 0 {
		u := st[len(st)-1]
		st = st[:len(st)-1]
		for _, v := range adj[u] {
			if !reach[v] {
				reach[v] = true
				st = append(st, v)
			}
		}
	}
	var verts []int
	for v := 0; v < n; v++ {
		if reach[v] {
			verts = append(verts, v)
		}
	}
	k := len(verts)
	if k == 0 {
		return 0, true
	}
	loc := make([]int, n)
	for i := range loc {
		loc[i] = -1
	}
	for i, v := range verts {
		loc[v] = i
	}
	r := loc[root]
	const INF = int64(1) << 61
	w := make([][]int64, k)
	for i := range w {
		w[i] = make([]int64, k)
		for j := range w[i] {
			w[i][j] = INF
		}
	}
	for _, e := range edges {
		if !reach[e.U] || !reach[e.V] {
			continue
		}
		u, v := loc[e.U], loc[e.V]
		if u == v {
			continue
		}
		if e.W < w[u][v] {
			w[u][v] = e.W
		}
	}
	full := 1 << k
	dp := make([]int64, full)
	for i := range dp {
		dp[i] = INF
	}
	dp[1<<r] = 0
	for S := 0; S < full; S++ {
		if dp[S] == INF || S&(1<<r) == 0 {
			continue
		}
		for v := 0; v < k; v++ {
			if S&(1<<v) != 0 || v == r {
				continue
			}
			best := INF
			rest := S &^ (1 << v)
			for u := 0; u < k; u++ {
				if rest&(1<<u) == 0 {
					continue
				}
				if w[u][v] == INF {
					continue
				}
				cand := dp[rest] + w[u][v]
				if cand < best {
					best = cand
				}
			}
			if best < dp[S|(1<<v)] {
				dp[S|(1<<v)] = best
			}
		}
	}
	fullSet := full - 1
	if dp[fullSet] >= INF {
		return 0, false
	}
	return dp[fullSet], true
}
```

### 2.5 Broken variants — `buggy.go`

Three independently broken solvers used only for falsification:

- **mode 0** — stops after the first contraction round and, like many single-pass implementations, re-adds the cycle edges (double counts them).
- **mode 1** — mishandles unreachable vertices by still charging the cheapest incoming edge of every non-reachable vertex.
- **mode 2** — omits the `w -= in[v]` step when contracting, i.e. forgets to subtract the added supernode edge cost.

```go
package arb

// BuggyWeightForTest exposes buggyWeight for the benchmark/test harnesses.
func BuggyWeightForTest(n, root int, edges []Edge, mode int) (int64, bool) {
	return buggyWeight(n, root, edges, mode)
}

func buggyWeight(n, root int, edges []Edge, mode int) (int64, bool) {
	if root < 0 || root >= n {
		return 0, false
	}
	reach := make([]bool, n)
	adj := make([][]int, n)
	for _, e := range edges {
		if e.U >= 0 && e.U < n && e.V >= 0 && e.V < n {
			adj[e.U] = append(adj[e.U], e.V)
		}
	}
	reach[root] = true
	st := []int{root}
	for len(st) > 0 {
		u := st[len(st)-1]
		st = st[:len(st)-1]
		for _, v := range adj[u] {
			if !reach[v] {
				reach[v] = true
				st = append(st, v)
			}
		}
	}
	idx := make([]int, n)
	for i := range idx {
		idx[i] = -1
	}
	var verts []int
	for v := 0; v < n; v++ {
		if reach[v] {
			idx[v] = len(verts)
			verts = append(verts, v)
		}
	}
	nn := len(verts)
	if nn == 0 {
		return 0, true
	}
	rootC := idx[root]
	var cur []curEdge
	for i, e := range edges {
		if e.U < 0 || e.U >= n || e.V < 0 || e.V >= n {
			continue
		}
		if !reach[e.U] || !reach[e.V] {
			continue
		}
		u := idx[e.U]
		v := idx[e.V]
		if u == v || v == rootC {
			continue
		}
		cur = append(cur, curEdge{u, v, e.W, i})
	}
	ncur := nn
	comp := make([]int, ncur)
	for i := range comp {
		comp[i] = i
	}
	numComp := nn
	_ = numComp
	var ans int64
	rounds := 0
	for iter := 0; iter < 100000; iter++ {
		in := make([]int64, ncur)
		pre := make([]int, ncur)
		for i := range in {
			in[i] = infWeight
			pre[i] = -1
		}
		for _, e := range cur {
			if e.w < in[e.v] {
				in[e.v] = e.w
				pre[e.v] = e.u
			}
		}
		for v := 0; v < ncur; v++ {
			if v != rootC && in[v] == infWeight {
				return 0, false
			}
		}
		in[rootC] = 0
		for v := 0; v < ncur; v++ {
			ans += in[v]
		}
		id := make([]int, ncur)
		vis := make([]int, ncur)
		for i := range id {
			id[i] = -1
			vis[i] = -1
		}
		numCycles := 0
		var cycles [][]int
		for i := 0; i < ncur; i++ {
			if i == rootC {
				continue
			}
			v := i
			for vis[v] != i && id[v] == -1 && v != rootC {
				vis[v] = i
				v = pre[v]
			}
			if v != rootC && id[v] == -1 {
				cyc := []int{}
				u := pre[v]
				for u != v {
					id[u] = numCycles
					cyc = append(cyc, u)
					u = pre[u]
				}
				id[v] = numCycles
				cyc = append(cyc, v)
				cycles = append(cycles, cyc)
				numCycles++
			}
		}
		if numCycles == 0 {
			break
		}
		if mode == 0 { // stop after one contraction round
			rounds++
			if rounds >= 1 {
				for _, cyc := range cycles {
					for _, v := range cyc {
						ans += in[v] // double count the cycle edges
					}
				}
				return ans, true
			}
		}
		next := numCycles
		for i := 0; i < ncur; i++ {
			if id[i] == -1 {
				id[i] = next
				next++
			}
		}
		newN := next
		var nxt []curEdge
		for _, e := range cur {
			uu := id[e.u]
			vv := id[e.v]
			if uu == vv {
				continue
			}
			nw := e.w - in[e.v]
			if mode == 2 {
				nw = e.w // forget to subtract
			}
			nxt = append(nxt, curEdge{uu, vv, nw, e.id})
		}
		cur = nxt
		newComp := make([]int, newN)
		for i := 0; i < ncur; i++ {
			newComp[id[i]] = comp[i]
		}
		comp = newComp
		ncur = newN
		rootC = id[rootC]
	}
	if mode == 1 { // mishandle unreachable vertices
		for v := 0; v < n; v++ {
			if reach[v] {
				continue
			}
			best := infWeight
			for _, e := range edges {
				if e.U < 0 || e.U >= n || e.V < 0 || e.V >= n {
					continue
				}
				if e.V == v && e.U != v && e.W < best {
					best = e.W
				}
			}
			if best != infWeight {
				ans += best
			}
		}
	}
	return ans, true
}
```

