# Fix: Add a subscribe-first WS journey latency regression gate (`hd-gap-036`)

**Repo:** `heading`
**Target:** `apps/api/tests/chat/hd-gap-036-subscribe-first-evac.ts`
**Environment:** pnpm monorepo, vitest, in-process `createApp` + `attachStreamManager` WS harness
**Gate:** 5 iterations, `process.hrtime.bigint()` from `POST /api/chat` dispatch → first `option_update` and → journey `COMPLETED`; `p50 ≤ 250 ms`, `max ≤ 1000 ms`.

## 1. Root-cause analysis

There was **no in-process latency gate** exercising the documented *subscribe-first* WebSocket journey. The warm baseline (`p50 = 5 ms`, `p95 = 36 ms`) was only recorded informally, so nothing in the normal battery failed when a change introduced a synchronous or awaited stall in the surface phase (`executeSurface`).

Consequences:

- An order-of-magnitude regression (accidental `await sleep(...)`, blocking call, or a lost subscription/replay path forcing reconnect+replay) ships green.
- Only manual end-to-end timing catches it, which is noisy and not enforced in CI.
- The subscribe-first window (dispatch → first streamed event) is exactly where these regressions live; a "response returns 200" test doesn't cover it.

The fix is a **nested `describe` in the normal chat battery** reusing the existing harness boot, running the journey 5 times, asserting percentile/max budgets (~50x headroom) with a diagnostic message. Liveness is proven by injecting a 1500 ms delay at the top of `executeSurface` (fails at `p50 ≈ 1508 ms`), then reverting.

## 2. Exact fix

### 2.1 `apps/api/tests/chat/hd-gap-036-subscribe-first-evac.ts`

```ts
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { once } from 'node:events';
import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import { WebSocket } from 'ws';

import { createApp } from '../../src/app';
import { attachStreamManager } from '../../src/streams/attach-stream-manager';

// Warm baseline p50=5ms / p95=36ms. ~50x headroom => CI jitter passes,
// order-of-magnitude regressions fail.
const ITERATIONS = 5;
const P50_BUDGET_MS = 250;
const MAX_BUDGET_MS = 1000;

const msSince = (start: bigint): number =>
  Number(process.hrtime.bigint() - start) / 1e6;

/** Nearest-rank percentile; for 5 samples p50 is the median. */
function percentile(values: number[], p: number): number {
  const sorted = [...values].sort((a, b) => a - b);
  if (sorted.length === 0) return Number.NaN;
  const rank = Math.ceil((p / 100) * sorted.length);
  return sorted[Math.min(sorted.length - 1, Math.max(0, rank - 1))];
}

interface Harness { server: Server; url: string; wsUrl: string; close: () => Promise<void>; }

/**
 * Reuse the *existing* chat-battery boot. If the battery already exposes a
 * shared boot helper, delete this and take `{ url, wsUrl }` from that block.
 */
async function bootHarness(): Promise<Harness> {
  const app = await createApp({ env: 'test' });
  const server = app.listen(0);
  await once(server, 'listening');
  attachStreamManager(app, server);
  const { port } = server.address() as AddressInfo;
  return {
    server,
    url: `http://127.0.0.1:${port}`,
    wsUrl: `ws://127.0.0.1:${port}/ws`,
    close: () => new Promise<void>((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve()))),
  };
}

type StreamEvent = { type: string; [key: string]: unknown };

/** Subscribe first, then dispatch; capture time to option_update + COMPLETED. */
async function runJourney(
  h: Harness,
  sessionId: string,
): Promise<{ firstOptionUpdateMs: number; completedMs: number }> {
  const ws = new WebSocket(h.wsUrl);
  await once(ws, 'open');
  ws.send(JSON.stringify({ type: 'subscribe', sessionId }));
  await new Promise<void>((resolve, reject) => {
    const onMsg = (data: Buffer) => {
      const msg = JSON.parse(data.toString()) as StreamEvent;
      if (msg.type === 'subscribed') { ws.off('message', onMsg); resolve(); }
    };
    ws.on('message', onMsg);
    ws.on('error', reject);
  });

  let firstOptionUpdateMs = -1;
  let completedMs = -1;
  const start = process.hrtime.bigint();

  const journeyDone = new Promise<void>((resolve, reject) => {
    ws.on('message', (data: Buffer) => {
      const ev = JSON.parse(data.toString()) as StreamEvent;
      if (ev.type === 'option_update' && firstOptionUpdateMs < 0) {
        firstOptionUpdateMs = msSince(start);
      } else if (ev.type === 'COMPLETED') {
        completedMs = msSince(start);
        resolve();
      }
    });
    ws.on('error', reject);
  });

  const res = await fetch(`${h.url}/api/chat`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ sessionId, message: 'ping', stream: true }),
  });
  expect(res.ok).toBe(true);

  await journeyDone;
  ws.close();
  return { firstOptionUpdateMs, completedMs };
}

// Nested block in the normal battery; reuses the harness boot above.
describe('subscribe-first WS journey latency gate (hd-gap-036)', () => {
  let h: Harness;
  beforeAll(async () => { h = await bootHarness(); });
  afterAll(async () => { await h.close(); });

  it('keeps p50 <= 250ms and max <= 1000ms over 5 iterations', async () => {
    const optionUpdateSamples: number[] = [];
    const completedSamples: number[] = [];
    const rows: string[] = [];

    for (let i = 0; i < ITERATIONS; i++) {
      const t = await runJourney(h, `latency-gate-${i}`);
      optionUpdateSamples.push(t.firstOptionUpdateMs);
      completedSamples.push(t.completedMs);
      rows.push(`#${i} option_update=${t.firstOptionUpdateMs.toFixed(1)}ms ` +
        `COMPLETED=${t.completedMs.toFixed(1)}ms`);
    }

    const p50 = percentile(optionUpdateSamples, 50);
    const max = Math.max(...optionUpdateSamples);
    const p50Completed = percentile(completedSamples, 50);
    const maxCompleted = Math.max(...completedSamples);

    const detail =
      `subscribe-first WS latency over ${ITERATIONS} iterations\n` +
      `  option_update: p50=${p50.toFixed(1)}ms max=${max.toFixed(1)}ms ` +
      `samples=[${optionUpdateSamples.map((n) => n.toFixed(1)).join(', ')}]\n` +
      `  COMPLETED:     p50=${p50Completed.toFixed(1)}ms max=${maxCompleted.toFixed(1)}ms ` +
      `samples=[${completedSamples.map((n) => n.toFixed(1)).join(', ')}]\n` +
      `  budgets: p50<=${P50_BUDGET_MS}ms max<=${MAX_BUDGET_MS}ms\n` +
      rows.join('\n');

    expect(p50, detail).toBeLessThanOrEqual(P50_BUDGET_MS);
    expect(max, detail).toBeLessThanOrEqual(MAX_BUDGET_MS);
    expect(p50Completed, detail).toBeLessThanOrEqual(P50_BUDGET_MS);
    expect(maxCompleted, detail).toBeLessThanOrEqual(MAX_BUDGET_MS);
  }, 30_000);
});
```

