### `dbg.js`

```javascript
'use strict';
/*
 * dbg.js -- minimizer-indexed, canonical compacted de Bruijn graph,
 *           topology-correct unitig compaction + bubble popping.
 *
 * Node20, zero dependencies.
 *
 * Model
 * -----
 * A node is a canonical k-mer  can(x) = min(x, revcomp(x)); a forward k-mer and
 * its reverse complement are therefore the SAME node.  A node has two
 * orientations: 0 = canonical spelling, 1 = reverse complement.  A "state" is
 * (node, orient).
 *
 * An arc (u,ou) -> (v,ov) exists when oriented(u,ou)[1..] == oriented(v,ov)[..k-1]
 * and the step was observed on a read.  Every arc is mirrored by its reverse
 * complement, so the graph is rc-closed.  Reverse-complement palindromic
 * k-mers have a single orientation (forced to 0) so they never split into two
 * states.
 *
 * Minimizers: over each read, slide a window of w canonical k-mers and take the
 * window minimum (leftmost on ties).  The minimizer is stored as the sparse
 * index key of each node; the full de Bruijn topology is retained.
 */

const COMP = { A: 'T', C: 'G', G: 'C', T: 'A', N: 'N' };

function revcomp(s) {
  let r = '';
  for (let i = s.length - 1; i >= 0; i--) r += COMP[s[i]] || 'N';
  return r;
}

function canonical(s) {
  const r = revcomp(s);
  return s <= r ? s : r;
}

const ORIENTED = (node, o) => (o === 0 ? node : revcomp(node));
const isPalindrome = (node) => node === revcomp(node);
const normO = (node, o) => (isPalindrome(node) ? 0 : o);
const stateKey = (u, o) => u + '|' + o;

/* ------------------------------------------------------------------ */
/* input                                                              */
/* ------------------------------------------------------------------ */

function readFasta(text) {
  const out = [];
  let cur = null;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '') continue;
    if (line[0] === '>') {
      if (cur !== null) out.push(cur);
      cur = '';
    } else {
      if (cur === null) cur = '';
      cur += line;
    }
  }
  if (cur !== null) out.push(cur);
  return out;
}

/* ------------------------------------------------------------------ */
/* canonical k-mers + minimizers                                      */
/* ------------------------------------------------------------------ */

function minimizersOf(seq, k, w) {
  const n = seq.length - k + 1;
  if (n <= 0) return { cans: [], mins: [] };
  const cans = new Array(n);
  for (let i = 0; i < n; i++) cans[i] = canonical(seq.substr(i, k));
  const mins = new Array(n).fill(null);
  const win = Math.max(1, w);
  const dq = [];
  for (let i = 0; i < n; i++) {
    while (dq.length && cans[dq[dq.length - 1]] > cans[i]) dq.pop();
    dq.push(i);
    if (dq[0] <= i - win) dq.shift();
    if (i >= win - 1) mins[i] = cans[dq[0]];
  }
  for (let i = 0; i < n; i++) if (mins[i] === null) mins[i] = cans[i];
  return { cans, mins };
}

/* ------------------------------------------------------------------ */
/* graph build                                                        */
/* ------------------------------------------------------------------ */

function addTo(map, key, val) {
  let a = map.get(key);
  if (!a) map.set(key, (a = []));
  if (!a.includes(val)) a.push(val);
  return a;
}

function buildGraph(reads, k, w) {
  const nodes = new Map(); // canonical node -> minimizer
  const stateOf = new Map(); // "u|o" -> {u,o}
  const arcByKey = new Map();
  const supportOf = new Map();

  function touchNode(can, min) {
    const prev = nodes.get(can);
    if (prev === undefined || (min && min < prev)) nodes.set(can, min || prev || can);
  }

  function bump(u, ou, v, ov, base) {
    const key = u + '|' + ou + '|' + v + '|' + ov;
    supportOf.set(key, (supportOf.get(key) || 0) + 1);
    if (!arcByKey.has(key)) arcByKey.set(key, { key, u, ou, v, ov, base, support: 0, dead: false });
    if (!stateOf.has(stateKey(u, ou))) stateOf.set(stateKey(u, ou), { u, o: ou });
    if (!stateOf.has(stateKey(v, ov))) stateOf.set(stateKey(v, ov), { u: v, o: ov });
  }

  for (const seq of reads) {
    if (seq.length < k) continue;
    const { cans, mins } = minimizersOf(seq, k, w);
    for (let i = 0; i < cans.length; i++) touchNode(cans[i], mins[i]);
    for (let i = 0; i + 1 < cans.length; i++) {
      const x = seq.substr(i, k);
      const y = seq.substr(i + 1, k);
      const u = cans[i];
      const v = cans[i + 1];
      const ou = normO(u, x === u ? 0 : 1);
      const ov = normO(v, y === v ? 0 : 1);
      bump(u, ou, v, ov, y[y.length - 1]);
      bump(v, normO(v, ov ^ 1), u, normO(u, ou ^ 1), COMP[x[0]] || 'N');
    }
  }

  const out = new Map();
  const inn = new Map();
  const arcs = [];
  let nextId = 0;
  for (const [, rec] of arcByKey) {
    rec.support = supportOf.get(rec.key);
    rec.id = nextId++;
    arcs.push(rec);
    addTo(out, stateKey(rec.u, rec.ou), rec.id);
    addTo(inn, stateKey(rec.v, rec.ov), rec.id);
  }
  return { nodes, stateOf, arcs, out, inn };
}

const outDeg = (g, u, o) => (g.out.get(stateKey(u, o)) || []).length;
const inDeg = (g, u, o) => (g.inn.get(stateKey(u, o)) || []).length;
const isBoundary = (g, u, o) => outDeg(g, u, o) !== 1 || inDeg(g, u, o) !== 1;

/* ------------------------------------------------------------------ */
/* unitig compaction                                                  */
/* ------------------------------------------------------------------ */

function extendUnitig(g, startState, a0, visited) {
  const parts = [ORIENTED(startState.u, startState.o)];
  let arc = a0;
  visited.add(arc.id);
  let cur = { u: arc.v, o: arc.ov };
  parts.push(ORIENTED(cur.u, cur.o).slice(-1));
  while (stateKey(cur.u, cur.o) !== stateKey(startState.u, startState.o)) {
    if (isBoundary(g, cur.u, cur.o)) break;
    const outs = g.out.get(stateKey(cur.u, cur.o)) || [];
    const next = outs.find((id) => !visited.has(id) && !g.arcs[id].dead);
    if (next === undefined) break;
    visited.add(next);
    const na = g.arcs[next];
    cur = { u: na.v, o: na.ov };
    parts.push(ORIENTED(cur.u, cur.o).slice(-1));
  }
  return parts.join('');
}

function smallestStateInCycle(g, seedArc, visited) {
  const states = [];
  const arcs = [];
  let arc = seedArc;
  const seen = new Set();
  for (;;) {
    states.push({ u: arc.u, o: arc.ou });
    arcs.push(arc);
    seen.add(arc.id);
    const outs = g.out.get(stateKey(arc.v, arc.ov)) || [];
    const nextId = outs.find((id) => !visited.has(id) && !seen.has(id) && !g.arcs[id].dead);
    if (nextId === undefined) break;
    arc = g.arcs[nextId];
  }
  let best = 0;
  for (let i = 1; i < states.length; i++) {
    const a = ORIENTED(states[i].u, states[i].o);
    const b = ORIENTED(states[best].u, states[best].o);
    if (a < b || (a === b && states[i].o < states[best].o)) best = i;
  }
  return { startState: states[best], seedArc: arcs[best] };
}

function compactUnitigs(g) {
  const visited = new Set();
  const raw = [];
  const stateKeys = [...g.out.keys()].sort();

  for (const sk of stateKeys) {
    const st = g.stateOf.get(sk);
    if (!isBoundary(g, st.u, st.o)) continue;
    for (const id of g.out.get(sk) || []) {
      if (visited.has(id) || g.arcs[id].dead) continue;
      raw.push(extendUnitig(g, st, g.arcs[id], visited));
    }
  }
  for (const sk of stateKeys) {
    const st = g.stateOf.get(sk);
    for (const id of g.out.get(sk) || []) {
      if (visited.has(id) || g.arcs[id].dead) continue;
      const { startState, seedArc } = smallestStateInCycle(g, g.arcs[id], visited);
      raw.push(extendUnitig(g, startState, seedArc, visited));
    }
  }
  return raw;
}

/* ------------------------------------------------------------------ */
/* bubble detection + popping                                         */
/* ------------------------------------------------------------------ */

function pathSeq(states) {
  if (!states.length) return '';
  let s = ORIENTED(states[0].u, states[0].o);
  for (let i = 1; i < states.length; i++) s += ORIENTED(states[i].u, states[i].o).slice(-1);
  return s;
}

function uniqueSucc(g, s) {
  const seen = new Set();
  const res = [];
  for (const id of g.out.get(stateKey(s.u, s.o)) || []) {
    const a = g.arcs[id];
    if (a.dead) continue;
    const k = stateKey(a.v, a.ov);
    if (seen.has(k)) continue;
    seen.add(k);
    res.push({ u: a.v, o: a.ov, arc: a });
  }
  return res.sort((x, y) => (stateKey(x.u, x.o) < stateKey(y.u, y.o) ? -1 : 1));
}

/** Returns { start, end, arms:[{states,arcs}], kind, len, support } or null. */
function tryLockstep(g, s, a0, b0, MAX) {
  const statesA = [a0], statesB = [b0];
  const arcsA = [a0.arc], arcsB = [b0.arc];
  const seenA = new Set([stateKey(a0.u, a0.o)]);
  const seenB = new Set([stateKey(b0.u, b0.o)]);
  let x = a0, y = b0;
  for (let len = 1; len <= MAX; len++) {
    if (x.u === y.u && x.o === y.o) {
      if (statesA.length === 1 && statesB.length === 1) return null; // parallel direct arcs
      const supportA = Math.min(...arcsA.map((r) => r.support));
      const supportB = Math.min(...arcsB.map((r) => r.support));
      if (supportA < 1 || supportB < 1) return null;
      return {
        start: s,
        end: { u: x.u, o: x.o },
        arms: [
          { states: statesA, arcs: arcsA },
          { states: statesB, arcs: arcsB },
        ],
        kind: 'equal',
        len,
      };
    }
    const ox = uniqueSucc(g, x);
    const oy = uniqueSucc(g, y);
    if (ox.length !== 1 || oy.length !== 1) return null;
    const nx = ox[0], ny = oy[0];
    const kx = stateKey(nx.u, nx.o);
    const ky = stateKey(ny.u, ny.o);
    const meet = nx.u === ny.u && nx.o === ny.o;
    if (!meet && (seenA.has(kx) || seenB.has(ky) || seenA.has(ky) || seenB.has(kx))) return null;
    statesA.push(nx);
    statesB.push(ny);
    arcsA.push(nx.arc);
    arcsB.push(ny.arc);
    seenA.add(kx);
    seenB.add(ky);
    x = nx;
    y = ny;
  }
  return null;
}

function followUnique(g, start, target, MAX) {
  const states = [start];
  const arcs = [start.arc];
  let cur = start;
  for (let step = 0; step < MAX; step++) {
    if (cur.u === target.u && cur.o === target.o) return { states, arcs };
    const outs = uniqueSucc(g, cur);
    if (outs.length !== 1) return null;
    const nx = outs[0];
    states.push(nx);
    arcs.push(nx.arc);
    cur = nx;
  }
  return null;
}

function tryEmptyArm(g, s, a0, b0, MAX) {
  for (const [direct, other] of [[b0, a0], [a0, b0]]) {
    const path = followUnique(g, other, direct, MAX);
    if (!path) continue;
    const inner = path.states.slice(1, -1);
    if (inner.some((p) => p.u === direct.u && p.o === direct.o)) continue;
    const supportEmpty = direct.arc.support;
    const supportPath = Math.min(...path.arcs.map((r) => r.support));
    if (supportEmpty < 1 || supportPath < 1) continue;
    return {
      start: s,
      end: { u: direct.u, o: direct.o },
      arms: [
        { states: [direct], arcs: [direct.arc], empty: true },
        { states: path.states, arcs: path.arcs, empty: false },
      ],
      kind: 'empty-arm',
      len: 0,
    };
  }
  return null;
}

function findBubbles(g) {
  const bubbles = [];
  const seen = new Set();
  const allStates = [...g.stateOf.values()].sort((a, b) =>
    stateKey(a.u, a.o) < stateKey(b.u, b.o) ? -1 : stateKey(a.u, a.o) > stateKey(b.u, b.o) ? 1 : 0
  );
  const MAX = allStates.length + 2;

  function push(b) {
    if (!b) return;
    const k = [stateKey(b.start.u, b.start.o), stateKey(b.end.u, b.end.o), b.kind,
      ...b.arms.map((a) => pathSeq(a.states))].sort().join('~');
    if (seen.has(k)) return;
    seen.add(k);
    bubbles.push(b);
  }

  for (const s of allStates) {
    const succ = uniqueSucc(g, s);
    if (succ.length < 2) continue;
    for (let i = 0; i < succ.length; i++) {
      for (let j = i + 1; j < succ.length; j++) {
        push(tryLockstep(g, s, succ[i], succ[j], MAX));
        push(tryEmptyArm(g, s, succ[i], succ[j], MAX));
      }
    }
  }
  return bubbles;
}

function arcKeyOf(a, b) {
  return a.u + '|' + a.o + '|' + b.u + '|' + b.o;
}

function removeArc(g, from, to) {
  const key = arcKeyOf(from, to);
  const rec = g.arcs.find((a) => a.key === key && !a.dead);
  if (!rec) return;
  rec.dead = true;
  const ok = stateKey(from.u, from.o);
  const ik = stateKey(to.u, to.o);
  if (g.out.has(ok)) g.out.set(ok, g.out.get(ok).filter((id) => id !== rec.id));
  if (g.inn.has(ik)) g.inn.set(ik, g.inn.get(ik).filter((id) => id !== rec.id));
}

/** Remove an arc and its reverse-complement mirror, keeping the graph rc-closed. */
function removeArcRc(g, from, to) {
  removeArc(g, from, to);
  removeArc(g, { u: to.u, o: normO(to.u, to.o ^ 1) }, { u: from.u, o: normO(from.u, from.o ^ 1) });
}

/**
 * Detect simple bubbles, group each rc-pair, decide once with the
 * lexicographically-smallest-arm rule, and pop the rejected arm plus its
 * mirror.  When the two arms are reverse complements of one another the choice
 * is tied, so both arms are popped symmetrically.
 */
function popBubbles(g) {
  const bubbles = findBubbles(g);
  // Signature of the FULL path (start + arm) so that an rc-pair of bubbles
  // canonicalises to one key even though their arm-only strings are reversed.
  const fullSeq = (b, arm) => pathSeq([b.start, ...arm.states]);
  const groups = new Map();
  for (const b of bubbles) {
    const sCan = canonical(ORIENTED(b.start.u, b.start.o));
    const eCan = canonical(ORIENTED(b.end.u, b.end.o));
    const lo = sCan < eCan ? sCan : eCan;
    const hi = sCan < eCan ? eCan : sCan;
    const arms = b.arms.map((a) => canonical(fullSeq(b, a))).sort();
    const key = [lo, hi, b.kind, arms[0], arms[1]].join('|');
    if (!groups.has(key)) groups.set(key, b);
  }

  const out = [];
  for (const b of groups.values()) {
    const A = b.arms[0];
    const B = b.arms[1];
    const ca = canonical(fullSeq(b, A));
    const cb = canonical(fullSeq(b, B));
    let keep;
    let pop;
    let kind = b.kind;
    let symmetric = false;
    if (ca < cb) {
      keep = A;
      pop = B;
    } else if (cb < ca) {
      keep = B;
      pop = A;
    } else {
      symmetric = true;
      kind = 'symmetric';
      keep = A;
      pop = B;
    }

    const toRemove = symmetric ? [...pop.arcs, ...keep.arcs] : pop.arcs;
    for (const rec of toRemove) {
      if (rec.dead) continue;
      removeArcRc(g, { u: rec.u, o: rec.ou }, { u: rec.v, o: rec.ov });
    }

    out.push({
      start: canonical(ORIENTED(b.start.u, b.start.o)),
      end: canonical(ORIENTED(b.end.u, b.end.o)),
      kind,
      len: symmetric ? b.len : keep.arcs.length,
      kept: symmetric ? '-' : canonical(pathSeq(keep.states)),
      popped: canonical(pathSeq(pop.states)),
      symmetric,
    });
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* serialisation                                                      */
/* ------------------------------------------------------------------ */

let K = 0;

function unitigRecords(g) {
  const raw = compactUnitigs(g);
  const uniq = new Map();
  for (const seq of raw) {
    const rc = revcomp(seq);
    const c = seq <= rc ? seq : rc;
    if (!uniq.has(c)) uniq.set(c, { canonical: c, seq, length: seq.length, nodes: seq.length - K + 1 });
  }
  return [...uniq.values()].sort((a, b) => (a.canonical < b.canonical ? -1 : a.canonical > b.canonical ? 1 : 0));
}

function fastaText(recs) {
  const lines = [];
  recs.forEach((r, i) => {
    lines.push('>utg' + (i + 1) + ' nodes=' + r.nodes + ' length=' + r.length);
    lines.push(r.canonical);
  });
  return lines.join('\n') + (lines.length ? '\n' : '');
}

function bubbleTsv(records) {
  const seen = new Set();
  const rows = [];
  for (const r of records) {
    const key = [r.start, r.end, r.kind, r.kept, r.popped].join('\t');
    if (seen.has(key)) continue;
    seen.add(key);
    rows.push(r);
  }
  rows.sort((a, b) => {
    if (a.start !== b.start) return a.start < b.start ? -1 : 1;
    if (a.end !== b.end) return a.end < b.end ? -1 : 1;
    if (a.kept !== b.kept) return a.kept < b.kept ? -1 : 1;
    return a.popped < b.popped ? -1 : a.popped > b.popped ? 1 : 0;
  });
  const lines = ['start\tend\tkind\tarm_len\tkept_arm\tpopped_arm'];
  for (const r of rows) lines.push([r.start, r.end, r.kind, String(r.len), r.kept, r.popped].join('\t'));
  return lines.join('\n') + '\n';
}

function adjacencyTsv(g) {
  // 4-column edge-keyed dump: canonical from, canonical to, overlap base, support.
  // Both directions of an rc pair are genuine directed edges and are kept.
  const m = new Map();
  for (const a of g.arcs) {
    if (a.dead) continue;
    const from = canonical(a.u);
    const to = canonical(a.v);
    const key = [from, to, a.base, a.support].join('\t');
    if (!m.has(key)) m.set(key, { from, to, base: a.base, support: a.support });
  }
  const rows = [...m.values()].sort((x, y) => {
    if (x.from !== y.from) return x.from < y.from ? -1 : 1;
    if (x.to !== y.to) return x.to < y.to ? -1 : 1;
    if (x.base !== y.base) return x.base < y.base ? -1 : 1;
    return x.support - y.support;
  });
  const lines = ['from\tto\tbase\tsupport'];
  for (const r of rows) lines.push([r.from, r.to, r.base, String(r.support)].join('\t'));
  return lines.join('\n') + '\n';
}

/* ------------------------------------------------------------------ */
/* top level                                                          */
/* ------------------------------------------------------------------ */

function run(text, k, w, opts) {
  if (k <= 0) throw new Error('k must be positive');
  if (w < 1) throw new Error('w must be >= 1');
  K = k;
  const reads = readFasta(text);
  const g = buildGraph(reads, k, w);
  const bubbles = popBubbles(g);
  const utgs = unitigRecords(g);
  const out = {
    fasta: fastaText(utgs),
    bubbles: bubbleTsv(bubbles),
    adjacency: adjacencyTsv(g),
    unitigs: utgs,
    bubblesRaw: bubbles,
    graph: g,
  };
  if (opts && opts.writePrefix) {
    const fs = require('fs');
    fs.writeFileSync(opts.writePrefix + '.unitigs.fa', out.fasta);
    fs.writeFileSync(opts.writePrefix + '.bubbles.tsv', out.bubbles);
    fs.writeFileSync(opts.writePrefix + '.adj.tsv', out.adjacency);
  }
  return out;
}

if (require.main === module) {
  const fs = require('fs');
  const args = process.argv.slice(2);
  const o = { k: 31, w: 10, input: null, out: 'out' };
  for (let i = 0; i < args.length; i += 2) {
    const a = args[i];
    const v = args[i + 1];
    if (a === '-k') o.k = +v;
    else if (a === '-w') o.w = +v;
    else if (a === '-i') o.input = v;
    else if (a === '-o') o.out = v;
  }
  const text = o.input ? fs.readFileSync(o.input, 'utf8') : fs.readFileSync(0, 'utf8');
  run(text, o.k, o.w, { writePrefix: o.out });
}

module.exports = {
  revcomp,
  canonical,
  readFasta,
  minimizersOf,
  buildGraph,
  compactUnitigs,
  findBubbles,
  popBubbles,
  unitigRecords,
  run,
};
