`skill/manager.go` (core, abridged):

```go
type Executor interface {
	Run(skill Skill, payload Payload) error
}

type Manager struct {
	store   *Store
	exec    Executor
	mu      sync.Mutex
	fireCnt int64
}

// Dispatch writes the row, then invokes the runner, then transitions the row.
func (m *Manager) Dispatch(skill Skill, payload Payload) (status int, eventID string) {
	if m.exec == nil {
		return 500, "" // environment-unavailable escape hatch
	}

	ev := m.store.Insert(Event{SkillID: skill.ID, Source: skill.Source, Status: StatusRunning})

	if err := m.exec.Run(skill, payload); err != nil {
		m.store.UpdateStatus(ev.ID, StatusFailed)
		return 500, ev.ID
	}

	m.store.UpdateStatus(ev.ID, StatusCompleted)
	m.incFire()
	return 202, ev.ID
}

// MutantDispatch models the bug the tolerant test cannot see: the row is written
// as "completed" BEFORE (in fact, without) any runner call.
func (m *Manager) MutantDispatch(skill Skill, payload Payload) (status int, eventID string) {
	ev := m.store.Insert(Event{SkillID: skill.ID, Source: skill.Source, Status: StatusCompleted})
	return 202, ev.ID
}
```

The original, broken test:

```go
type alwaysFailExecutor struct{}
func (alwaysFailExecutor) Run(Skill, Payload) error { return errors.New("env unavailable") }

func TestDispatch_TolerantContract(t *testing.T) {
	store := NewStore()
	mgr := NewManager(store, alwaysFailExecutor{}) // executor hardcoded to fail

	status, _ := mgr.Dispatch(Skill{ID: "s1", Source: "skills/foo.md"}, Payload{"msg": "hi"})

	if status != 202 && status != 500 { // <-- false-acceptance clause
		t.Fatalf("status = %d, want 202 or 500", status)
	}
	if len(store.All()) == 0 {
		t.Fatal("expected an event row to be written") // true even with no execution
	}
}
```

## 3. The exact fix

### 3.1 Add a recording executor (the instrument)

```go
type call struct {
	Skill   Skill
	Payload Payload
}

type recordingExecutor struct {
	mu    sync.Mutex
	calls []call
	err   error
}

func (r *recordingExecutor) Run(s Skill, p Payload) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.calls = append(r.calls, call{Skill: s, Payload: p})
	return r.err
}

func (r *recordingExecutor) Calls() []call {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]call, len(r.calls))
	copy(out, r.calls)
	return out
}
```

### 3.2 Assert the strict contract on the live manager

```go
func assertStrict(t *testing.T, setup func(store *Store, rec *recordingExecutor) (*Manager, func(Skill, Payload) (int, string))) {
	t.Helper()

	store := NewStore()
	rec := &recordingExecutor{}
	mgr, dispatch := setup(store, rec)

	skill := Skill{ID: "s1", Source: "skills/foo.md"}
	payload := Payload{"msg": "hi"}

	status, _ := dispatch(skill, payload)

	// 1. Accepted only. The executor is wired to succeed, so 500 is a real failure.
	if status != 202 {
		t.Fatalf("status = %d, want 202", status)
	}

	// 2. Executor actually invoked, exactly once, with the exact source/payload.
	calls := rec.Calls()
	if len(calls) != 1 {
		t.Fatalf("executor invocations = %d, want 1", len(calls))
	}
	if calls[0].Skill.Source != skill.Source {
		t.Fatalf("executor skill source = %q, want %q", calls[0].Skill.Source, skill.Source)
	}
	if !reflect.DeepEqual(calls[0].Payload, payload) {
		t.Fatalf("executor payload = %#v, want %#v", calls[0].Payload, payload)
	}

	// 3. Exactly one event row, and exactly one reached "completed".
	events := store.All()
	completed := 0
	for _, e := range events {
		if e.Status == StatusCompleted {
			completed++
		}
	}
	if len(events) != 1 {
		t.Fatalf("event rows = %d, want exactly 1", len(events))
	}
	if completed != 1 {
		t.Fatalf("completed rows = %d, want exactly 1", completed)
	}

	// 4. Fire counter incremented.
	if got := mgr.FireCount(); got != 1 {
		t.Fatalf("fire counter = %d, want 1", got)
	}
}

// The real regression test: recording executor swapped onto the live manager.
func TestDispatch_StrictAgainstRecordingExecutor(t *testing.T) {
	assertStrict(t, func(store *Store, rec *recordingExecutor) (*Manager, func(Skill, Payload) (int, string)) {
		mgr := NewManager(store, rec)
		return mgr, mgr.Dispatch
	})
}
```

### 3.3 Keep the tolerant test — as a dispatch-contract check only

Rename/comment it so its scope is explicit. It may assert `202 || 500` and that a row was written; it must **not** be treated as execution coverage.

```go
// TestDispatch_TolerantContract verifies only the dispatch contract:
// a request is either accepted or explicitly refused because the environment
// is unavailable. It does NOT prove the skill ran.
func TestDispatch_TolerantContract(t *testing.T) { /* unchanged */ }
```

### 3.4 Prove the mutant is rejected

Build-tagged so the default suite stays green; `-tags mutant` points the strict body at the buggy implementation:

```go
//go:build mutant

package skill

import "testing"

func TestStrictAgainstMutant(t *testing.T) {
	assertStrict(t, func(store *Store, rec *recordingExecutor) (*Manager, func(Skill, Payload) (int, string)) {
		mgr := NewManager(store, rec)
		return mgr, mgr.MutantDispatch
	})
}
```

